type PdfParseResult = { text?: string };
type PdfParseFn = (dataBuffer: Buffer) => Promise<PdfParseResult>;

const DB_CACHE_MAX_ENTRIES = 32;
const DB_CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000; // 7 dias corridos. Previne "Database closed" após ociosidade > 30 min do processo PM2
const DB_MTIME_SAFETY_DELTA_MS = 50;
type DbCacheEntry = { db: Database; mtimeMs: number; lastUsedMs: number };
let cachedPdfParse: PdfParseFn | null = null;
let cachedPdfModule: unknown | null = null;
let cachedSqlJs: Promise<SqlJsStatic> | null = null;
const cachedDbByPath = new Map<string, DbCacheEntry>();
const GRAPH_TOKEN_CACHE_TTL_MS = 50 * 60 * 1000;
const GRAPH_TOKEN_CACHE_MAX_ENTRIES = 16;
type GraphTokenCacheEntry = { accessToken: string; expiresAtMs: number };
const _graphTokenCache = new Map<string, GraphTokenCacheEntry>();
function _graphTokenCacheKey(opts: { tenantId: string; clientId: string; clientSecret?: string }): string {
  const secretLen = typeof opts.clientSecret === 'string' ? opts.clientSecret.length : 0;
  const secretTail = secretLen > 4 ? opts.clientSecret!.slice(-4) : '';
  return `${opts.tenantId}::${opts.clientId}::${secretLen}:${secretTail}`;
}
function evictGraphTokenCacheIfNeeded(): void {
  const nowMs = Date.now();
  if (_graphTokenCache.size > 0) {
    for (const [k, entry] of Array.from(_graphTokenCache.entries())) {
      if (nowMs >= entry.expiresAtMs) _graphTokenCache.delete(k);
    }
  }
  if (_graphTokenCache.size <= GRAPH_TOKEN_CACHE_MAX_ENTRIES) return;
  const sorted = Array.from(_graphTokenCache.entries()).sort((a, b) => a[1].expiresAtMs - b[1].expiresAtMs);
  const toRemove = sorted.slice(0, _graphTokenCache.size - GRAPH_TOKEN_CACHE_MAX_ENTRIES);
  for (const [k] of toRemove) _graphTokenCache.delete(k);
}
let _dbWriteMutexHead: Promise<unknown> = Promise.resolve();
const _dbOpenCloseLock = { lock: false, pending: [] as Array<() => void> };

function withDbWriteLock<T>(fn: () => T | Promise<T>): Promise<T> {
  const next = _dbWriteMutexHead.then(() => fn());
  _dbWriteMutexHead = next.then(
    () => undefined,
    () => undefined,
  );
  return next;
}

function safeLogError(context: string, err: unknown): void {
  try {
    const t = new Date().toISOString();
    const m = err instanceof Error ? `${err.name}: ${err.message}\n${err.stack ?? ''}` : String(err);
    console.error(`[safe-error][${t}] ${context} :: ${m}`);
  } catch {
    void 0;
  }
}

function evictOldDbCacheEntriesIfNeeded(): void {
  if (cachedDbByPath.size <= DB_CACHE_MAX_ENTRIES) return;
  const sorted = Array.from(cachedDbByPath.entries()).sort(
    (a, b) => a[1].lastUsedMs - b[1].lastUsedMs,
  );
  const toRemove = sorted.slice(0, cachedDbByPath.size - DB_CACHE_MAX_ENTRIES);
  for (const [resolvedPath] of toRemove) {
    cachedDbByPath.delete(resolvedPath);
  }
}

function evictExpiredDbCacheEntriesIfNeeded(nowMs: number): void {
  for (const [resolvedPath, entry] of Array.from(cachedDbByPath.entries())) {
    if (nowMs - entry.lastUsedMs > DB_CACHE_TTL_MS) {
      cachedDbByPath.delete(resolvedPath);
    }
  }
}

type PdfParseModuleShape = {
  default?: unknown;
  PDFParse?: new (opts: { data: Buffer }) => {
    getText(): Promise<{ text?: unknown }>;
    destroy?(): Promise<unknown>;
  };
};

async function getPdfParse(): Promise<PdfParseFn> {
  if (cachedPdfParse) return cachedPdfParse;
  let mod: unknown;
  try {
    mod = await import('pdf-parse');
  } catch (e: unknown) {
    const message = e instanceof Error ? e.message : String(e);
    throw new Error(`Falha ao importar pdf-parse: ${message}`);
  }

  const pdfMod = mod as PdfParseModuleShape;
  const directFn = pdfMod?.default;
  if (typeof directFn === 'function') {
    cachedPdfParse = directFn as PdfParseFn;
    return cachedPdfParse;
  }

  const PDFParseClass = pdfMod?.PDFParse;
  if (typeof PDFParseClass === 'function') {
    cachedPdfParse = async (dataBuffer: Buffer) => {
      const parser = new PDFParseClass({ data: dataBuffer });
      try {
        const res = await parser.getText();
        return { text: typeof res?.text === 'string' ? res.text : '' };
      } finally {
        try {
          await parser.destroy?.();
        } catch (e) {
          safeLogError('pdf-parse destroy', e);
        }
      }
    };
    return cachedPdfParse;
  }

  const keys = mod && typeof mod === 'object' ? Object.keys(mod).join(', ') : '';
  throw new Error(`Falha ao carregar pdf-parse (exports: ${keys || '-'})`);
}

function looksLikeProtectedPdfWrapperText(text: string): boolean {
  const normalized = String(text ?? '').replace(/\s+/g, ' ').trim();
  if (!normalized) return false;
  return (
    /this pdf file is protected/i.test(normalized) ||
    /protected by microsoft office/i.test(normalized) ||
    /you'll need a different reader/i.test(normalized)
  );
}

function runProcess(
  cmd: string,
  args: string[],
  stdin: Buffer | null,
  opts: { timeoutMs?: number } = {},
): Promise<{ stdout: Buffer; stderr: string; exitCode: number }> {
  return new Promise((resolve) => {
    try {
      const timeoutMs = typeof opts.timeoutMs === 'number' ? opts.timeoutMs : 60_000;
      const cp = child_process.spawn(cmd, args, {
        stdio: stdin ? ['pipe', 'pipe', 'pipe'] : ['ignore', 'pipe', 'pipe'],
        windowsHide: true,
      });
      const stdoutChunks: Buffer[] = [];
      const stderrChunks: Buffer[] = [];
      let done = false;
      const timer = setTimeout(() => {
        if (done) return;
        done = true;
        try {
          cp.kill('SIGKILL');
        } catch {
          void 0;
        }
        resolve({
          stdout: Buffer.concat(stdoutChunks),
          stderr: Buffer.concat(stderrChunks).toString('utf8'),
          exitCode: -99,
        });
      }, timeoutMs);
      if (cp.stdout) {
        cp.stdout.on('data', (c: Buffer) => stdoutChunks.push(c));
      }
      if (cp.stderr) {
        cp.stderr.on('data', (c: Buffer) => stderrChunks.push(c));
      }
      cp.on('error', (err) => {
        stderrChunks.push(Buffer.from(String(err?.message ?? ''), 'utf8'));
      });
      cp.on('close', (code) => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        resolve({
          stdout: Buffer.concat(stdoutChunks),
          stderr: Buffer.concat(stderrChunks).toString('utf8'),
          exitCode: typeof code === 'number' ? code : -1,
        });
      });
      if (stdin && cp.stdin) {
        try {
          cp.stdin.end(stdin);
        } catch {
          void 0;
        }
      }
    } catch (e) {
      resolve({
        stdout: Buffer.alloc(0),
        stderr: e instanceof Error ? e.message : String(e),
        exitCode: -2,
      });
    }
  });
}

async function cliPdfTextFallback(file: Buffer): Promise<{ text: string } | null> {
  if (!Buffer.isBuffer(file) || file.length === 0) return null;
  const tmpDir = fs.realpathSync(os.tmpdir());
  const tag = `pdf-fb-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
  const srcFile = path.join(tmpDir, `${tag}.pdf`);
  const outFile = path.join(tmpDir, `${tag}-dec.pdf`);
  const clean = () => {
    try {
      fs.unlinkSync(srcFile);
    } catch {
      void 0;
    }
    try {
      fs.unlinkSync(outFile);
    } catch {
      void 0;
    }
  };
  try {
    fs.writeFileSync(srcFile, file);
  } catch {
    clean();
    return null;
  }

  let decPdf: Buffer | null = null;
  let gsText: Buffer | null = null;
  try {
    const gs = await runProcess(
      'gs',
      [
        '-q',
        '-dSAFER',
        '-dNOPAUSE',
        '-dBATCH',
        '-sDEVICE=pdfwrite',
        '-dPDFSETTINGS=/default',
        '-dCompatibilityLevel=1.7',
        '-dAutoRotatePages=/None',
        `-sOutputFile=${outFile}`,
        '-f',
        srcFile,
      ],
      null,
      { timeoutMs: 45_000 },
    );
    if (gs.exitCode === 0 && fs.existsSync(outFile) && fs.statSync(outFile).size > 0) {
      try {
        decPdf = fs.readFileSync(outFile);
      } catch {
        decPdf = null;
      }
    }
    if (!decPdf || looksLikeProtectedPdfWrapperText(decPdf.toString('latin1').slice(0, 8192))) {
      const gs2 = await runProcess(
        'gs',
        [
          '-q',
          '-dSAFER',
          '-dNOPAUSE',
          '-dBATCH',
          '-sDEVICE=txtwrite',
          '-dTextFormat=3',
          '-sOutputFile=-',
          '-f',
          srcFile,
        ],
        null,
        { timeoutMs: 45_000 },
      );
      if (gs2.exitCode === 0 && gs2.stdout.length > 200) {
        const t = gs2.stdout.toString('utf8');
        if (!looksLikeProtectedPdfWrapperText(t)) gsText = gs2.stdout;
      }
    }
  } catch {
    void 0;
  }

  if (gsText) {
    clean();
    return { text: gsText.toString('utf8') };
  }

  const pdfBuffer: Buffer = decPdf && decPdf.length > 0 ? decPdf : file;
  try {
    const res = await runProcess(
      'pdftotext',
      ['-upw', '', '-opw', '', '-layout', '-enc', 'UTF-8', '-', '-'],
      pdfBuffer,
      { timeoutMs: 45_000 },
    );
    if (res.exitCode === 0 || res.stdout.length > 512) {
      const txt = res.stdout.toString('utf8');
      if (txt && !looksLikeProtectedPdfWrapperText(txt)) {
        clean();
        return { text: txt };
      }
    }
  } catch {
    void 0;
  }

  clean();
  return null;
}

type PdfExtractPage = { num: number; text: string; tables: string[][][] };
type PdfExtractResult = { text: string; pages: PdfExtractPage[] };

function buildPdfResultFromCliText(text: string): PdfExtractResult {
  const full = String(text ?? '');
  const pages = full
    .split(/\f/)
    .map((t, i) => ({ num: i + 1, text: t, tables: [] as string[][][] }))
    .filter((p) => (p.text?.length ?? 0) > 0);
  if (pages.length === 0) return { text: full, pages: [{ num: 1, text: full, tables: [] }] };
  return { text: full, pages };
}

async function applyCliFallbackIfNeeded(
  result: PdfExtractResult,
  file: Buffer,
): Promise<PdfExtractResult> {
  const merged =
    typeof result?.text === 'string'
      ? result.text
      : Array.isArray(result?.pages)
        ? result.pages.map((p) => String(p?.text ?? '')).join('\n')
        : '';
  const emptyish =
    merged.replace(/\s+/g, '').length < 100 && Buffer.isBuffer(file) && file.length > 20_000;
  if (!looksLikeProtectedPdfWrapperText(merged) && !emptyish) return result;
  try {
    const fb = await cliPdfTextFallback(file);
    if (fb && typeof fb.text === 'string' && fb.text.replace(/\s+/g, '').length > 200) {
      return buildPdfResultFromCliText(fb.text);
    }
  } catch {
    void 0;
  }
  return result;
}

async function extractPdf(file: Buffer): Promise<PdfExtractResult> {
  if (!cachedPdfModule) {
    try {
      cachedPdfModule = await import('pdf-parse');
    } catch (e: unknown) {
      const message = e instanceof Error ? e.message : String(e);
      throw new Error(`Falha ao importar pdf-parse: ${message}`);
    }
  }
  const mod: any = cachedPdfModule;

  if (typeof mod?.PDFParse === 'function') {
    const parser = new mod.PDFParse({ data: file });
    let baseResult: PdfExtractResult | null = null;
    try {
      const textRes = await parser.getText();
      const tableRes = await parser.getTable();
      const tablePages = Array.isArray(tableRes?.pages) ? tableRes.pages : [];
      const textPages = Array.isArray(textRes?.pages) ? textRes.pages : [];
      const byPage = new Map<number, PdfExtractPage>();

      for (const p of textPages) {
        const num = typeof (p as any)?.num === 'number' ? (p as any).num : NaN;
        if (!Number.isFinite(num)) continue;
        const pageText = typeof (p as any)?.text === 'string' ? (p as any).text : '';
        byPage.set(num, { num, text: pageText, tables: [] as string[][][] });
      }

      for (const p of tablePages) {
        const num = typeof (p as any)?.num === 'number' ? (p as any).num : NaN;
        if (!Number.isFinite(num)) continue;
        const page =
          byPage.get(num) ?? { num, text: '', tables: [] as string[][][] };
        const t = (p as any)?.tables;
        if (Array.isArray(t)) {
          for (const table of t) {
            if (!Array.isArray(table)) continue;
            page.tables.push(
              table.map((row: any) =>
                Array.isArray(row) ? row.map((c) => String(c ?? '').trim()) : [],
              ),
            );
          }
        }
        byPage.set(num, page);
      }

      const pages = Array.from(byPage.values()).sort((a, b) => a.num - b.num);
      baseResult = {
        text: typeof textRes?.text === 'string' ? textRes.text : '',
        pages,
      };
    } finally {
      try {
        await parser.destroy();
      } catch {
        void 0;
      }
    }
    if (baseResult) return applyCliFallbackIfNeeded(baseResult, file);
  }

  const fn = await getPdfParse();
  const res = await fn(file);
  const text = String(res?.text ?? '');
  return applyCliFallbackIfNeeded({ text, pages: [{ num: 1, text, tables: [] }] }, file);
}

function normalizeUrl(input: string): string {
  let cleaned = String(input ?? '').replace(/[`]/g, '').replace(/\s+/g, ' ').trim();
  try {
    cleaned = decodeURIComponent(cleaned);
  } catch {
    /* ignore invalid encoding */
  }
  return cleaned.replace(/\s+/g, ' ').trim().replace(/ /g, '%20');
}

function toBase64Url(input: string): string {
  return Buffer.from(input, 'utf8')
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

function toShareId(url: string): string {
  try {
    const u = new URL(url);
    const q = u.searchParams.get('share') || u.searchParams.get('Share');
    if (q && /^[A-Za-z0-9_-]{8,}/.test(String(q).trim())) {
      return String(q).trim();
    }
    const m = u.pathname.match(/:([a-z]):\/r\//i);
    if (m) {
      const clean = `${u.origin}${u.pathname}`;
      return `u!${toBase64Url(clean)}`;
    }
  } catch {
    /* ignore parse */
  }
  return `u!${toBase64Url(url)}`;
}

async function getGraphToken(opts: {
  tenantId: string;
  clientId: string;
  clientSecret: string;
}): Promise<string> {
  const tenantId = String(opts.tenantId ?? '').trim();
  const clientId = String(opts.clientId ?? '').trim();
  const clientSecret = String(opts.clientSecret ?? '');
  if (!tenantId || !clientId) throw new Error('tenantId/clientId não informados para token Graph.');
  const cacheKey = _graphTokenCacheKey({ tenantId, clientId, clientSecret });
  evictGraphTokenCacheIfNeeded();
  const cached = _graphTokenCache.get(cacheKey);
  const nowMs = Date.now();
  if (cached && cached.accessToken && nowMs < cached.expiresAtMs) {
    return cached.accessToken;
  }
  const params = new URLSearchParams();
  params.set('client_id', clientId);
  if (clientSecret) params.set('client_secret', clientSecret);
  params.set('grant_type', 'client_credentials');
  params.set('scope', 'https://graph.microsoft.com/.default');

  const res = await fetch(
    `https://login.microsoftonline.com/${encodeURIComponent(tenantId)}/oauth2/v2.0/token`,
    {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: params,
    },
  );

  if (!res.ok) {
    throw new Error(`Falha ao obter token do Graph (HTTP ${res.status})`);
  }

  const data = (await res.json()) as { access_token?: string };
  if (!data.access_token) throw new Error('Falha ao obter token do Graph');
  const ttl = GRAPH_TOKEN_CACHE_TTL_MS;
  const expiresAtMs = nowMs + ttl;
  _graphTokenCache.set(cacheKey, { accessToken: data.access_token, expiresAtMs });
  evictGraphTokenCacheIfNeeded();
  return data.access_token;
}

async function getGraphDelegatedTokenFromRefreshToken(opts: {
  tenantId: string;
  clientId: string;
  clientSecret?: string;
  refreshToken: string;
}): Promise<string> {
  const refreshToken = String(opts.refreshToken ?? '').trim();
  if (!refreshToken) throw new Error('Refresh token do Teams não configurado.');
  const clientSecret = String(opts.clientSecret ?? '').trim();
  const tokenUrl = `https://login.microsoftonline.com/${encodeURIComponent(opts.tenantId)}/oauth2/v2.0/token`;

  const exchange = async (withSecret: boolean) => {
    const params = new URLSearchParams();
    params.set('client_id', opts.clientId);
    if (withSecret && clientSecret) params.set('client_secret', clientSecret);
    params.set('grant_type', 'refresh_token');
    params.set('refresh_token', refreshToken);
    params.set('scope', 'https://graph.microsoft.com/Chat.ReadWrite https://graph.microsoft.com/Files.ReadWrite.All https://graph.microsoft.com/Sites.Read.All offline_access openid profile');

    const res = await fetch(tokenUrl, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: params,
    });
    const data = (await res.json().catch(() => null)) as null | {
      access_token?: unknown;
      refresh_token?: unknown;
      error_description?: unknown;
    };
    if (!res.ok) {
      const msg =
        (typeof data?.error_description === 'string' && data.error_description.trim()) ||
        `Falha ao obter token delegado do Graph (HTTP ${res.status})`;
      throw new Error(msg);
    }
    const accessToken = typeof data?.access_token === 'string' ? data.access_token.trim() : '';
    if (!accessToken) throw new Error('Falha ao obter token delegado do Graph');
    const nextRefresh = typeof data?.refresh_token === 'string' ? data.refresh_token.trim() : '';
    return { accessToken, nextRefresh };
  };

  let accessToken = '';
  let nextRefresh = '';
  try {
    const r = await exchange(false);
    accessToken = r.accessToken;
    nextRefresh = r.nextRefresh;
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e ?? '');
    if (msg.includes('AADSTS50173')) {
      try {
        const dbFilePath = getSqlitePath();
        const db = await openDatabase(dbFilePath);
        ensureSchema(db);
        setConsignadoAppConfigValue(db, CONFIG_KEY_NOTIFICATION_TEAMS_DELEGATED_REFRESH_TOKEN, null);
        setConsignadoAppConfigValue(db, CONFIG_KEY_NOTIFICATION_TEAMS_DELEGATED_DEVICE_CODE, null);
        setConsignadoAppConfigValue(db, CONFIG_KEY_NOTIFICATION_TEAMS_DELEGATED_DEVICE_CODE_EXPIRES_AT, null);
        persistDatabase(db, dbFilePath);
      } catch {
        void 0;
      }
      throw new Error(
        'Teams (Chat 1:1) desconectado: o login Microsoft expirou ou foi revogado. Vá em Configurações -> Teams (Chat 1:1) e conecte novamente.',
      );
    }
    if (msg.includes('AADSTS65001') || msg.includes('consent_required') || msg.includes('has not consented')) {
      try {
        const dbFilePath = getSqlitePath();
        const db = await openDatabase(dbFilePath);
        ensureSchema(db);
        setConsignadoAppConfigValue(db, CONFIG_KEY_NOTIFICATION_TEAMS_DELEGATED_REFRESH_TOKEN, null);
        setConsignadoAppConfigValue(db, CONFIG_KEY_NOTIFICATION_TEAMS_DELEGATED_DEVICE_CODE, null);
        setConsignadoAppConfigValue(db, CONFIG_KEY_NOTIFICATION_TEAMS_DELEGATED_DEVICE_CODE_EXPIRES_AT, null);
        persistDatabase(db, dbFilePath);
      } catch {
        void 0;
      }
      throw new Error(
        'Login do Teams foi conectado sem as permissões necessárias para SharePoint (Files.ReadWrite.All / Sites.Read.All). Vá em Configurações → Teams (Chat 1:1) → clique em "Desconectar" e depois "Login Microsoft (delegado)" novamente para conceder as permissões novas.',
      );
    }
    if (clientSecret && msg.includes('AADSTS7000218')) {
      const r = await exchange(true);
      accessToken = r.accessToken;
      nextRefresh = r.nextRefresh;
    } else if (msg.includes('AADSTS700025')) {
      const r = await exchange(false);
      accessToken = r.accessToken;
      nextRefresh = r.nextRefresh;
    } else {
      throw e;
    }
  }
  if (nextRefresh && nextRefresh !== refreshToken) {
    try {
      const dbFilePath = getSqlitePath();
      const db = await openDatabase(dbFilePath);
      ensureSchema(db);
      setConsignadoAppConfigValue(db, CONFIG_KEY_NOTIFICATION_TEAMS_DELEGATED_REFRESH_TOKEN, nextRefresh);
      persistDatabase(db, dbFilePath);
    } catch {
      void 0;
    }
  }
  return accessToken;
}

async function graphGet<T>(token: string, url: string): Promise<T> {
  const res = await fetch(url, {
    headers: { authorization: `Bearer ${token}` },
  });
  if (!res.ok) {
    const text = await res.text().catch(() => '');
    throw new Error(text || `Graph GET falhou (HTTP ${res.status})`);
  }
  return (await res.json()) as T;
}

async function graphDownload(token: string, url: string): Promise<Buffer> {
  const res = await fetch(url, {
    headers: { authorization: `Bearer ${token}` },
  });
  if (!res.ok) {
    throw new Error(`Download falhou (HTTP ${res.status})`);
  }
  const arrayBuffer = await res.arrayBuffer();
  return Buffer.from(arrayBuffer);
}

async function resolveDriveItemFromShareUrl(
  token: string,
  folderUrl: string,
): Promise<{
  driveId: string;
  itemId: string;
  itemName: string;
  specificFile: null | { id: string; name: string };
  parentFolderId?: string | null;
  folderPath?: string | null;
}> {
  const isGraphShareResolutionError = (message: string): boolean => {
    const t = String(message ?? '');
    if (!t) return false;
    const parsed = parseGraphErrorText(t);
    const code = (parsed.code ?? '').toLowerCase();
    const inner = (parsed.innerCode ?? '').toLowerCase();
    return (
      code === 'accessdenied' ||
      inner === 'sharesaccessdenied' ||
      /sharesAccessDenied/i.test(t) ||
      /0x80070002/i.test(t) ||
      /cannot find the file specified/i.test(t)
    );
  };

  const isGraphPathNotFound = (message: string): boolean => {
    const t = String(message ?? '');
    if (!t) return false;
    const parsed = parseGraphErrorText(t);
    const code = (parsed.code ?? '').toLowerCase();
    const inner = (parsed.innerCode ?? '').toLowerCase();
    return (
      code === 'itemnotfound' ||
      inner === 'itemnotfound' ||
      /itemNotFound/i.test(t) ||
      /0x80070002/i.test(t) ||
      /cannot find the file specified/i.test(t) ||
      /The resource could not be found/i.test(t)
    );
  };

  const normalizeSegmentForPathMatch = (input: string): string => {
    return normalizeNameForMatch(input).replace(/\s*([._-])\s*/g, '$1');
  };

  const resolveFromDriveItem = async (driveId: string, data: {
    id: string;
    name?: string;
    folder?: unknown;
    file?: unknown;
    parentReference?: { driveId?: string; id?: string };
  }) => {
    if (!driveId) throw new Error('Não foi possível resolver o driveId do SharePoint');
    if (!data.id) throw new Error('Não foi possível resolver o itemId do SharePoint');
    const name = typeof data.name === 'string' ? data.name.trim() : '';
    if (data.folder) {
      const parentIdForFolder = data.parentReference?.id ? String(data.parentReference.id).trim() || null : null;
      return { driveId, itemId: data.id, itemName: name, specificFile: null, parentFolderId: parentIdForFolder, folderPath: name || null };
    }

    if (data.file) {
      const fileId = data.id;
      const fileName = name;
      const parentId = data.parentReference?.id
        ? String(data.parentReference.id).trim()
        : '';
      const resolvedParentId = parentId
        ? parentId
        : (await (async () => {
            const item = await graphGet<{ parentReference?: { id?: string } }>(
              token,
              `https://graph.microsoft.com/v1.0/drives/${encodeURIComponent(
                driveId,
              )}/items/${encodeURIComponent(fileId)}?$select=parentReference`,
            );
            return String(item.parentReference?.id ?? '').trim();
          })());
      if (!resolvedParentId) {
        throw new Error('Não foi possível resolver a pasta do arquivo no SharePoint');
      }
      const parent = await graphGet<{ name?: string; folder?: unknown }>(
        token,
        `https://graph.microsoft.com/v1.0/drives/${encodeURIComponent(
          driveId,
        )}/items/${encodeURIComponent(resolvedParentId)}?$select=name,folder`,
      );
      if (!parent.folder) {
        throw new Error('A URL informada não aponta para uma pasta');
      }
      const parentName = typeof parent.name === 'string' ? parent.name.trim() : '';
      return {
        driveId,
        itemId: resolvedParentId,
        itemName: parentName,
        specificFile: fileId && fileName ? { id: fileId, name: fileName } : null,
        parentFolderId: resolvedParentId,
        folderPath: parentName || null,
      };
    }

    throw new Error('A URL informada não aponta para uma pasta');
  };

  const resolveFromSitePathUrl = async () => {
    let u: URL;
    try {
      u = new URL(folderUrl);
    } catch {
      throw new Error('URL do SharePoint inválida.');
    }

    // MINIMAL FIX 3a: Copiar link usa padrão /:X:/r/sites/... (onde X é f/g/p etc).
    // Remover segmentos iniciais :X:/r/ para que parts[0] = 'sites' (parsing correto).
    const shareSpoofedMatch = u.pathname.match(/^\/:([a-z]):\/r\//i);
    if (shareSpoofedMatch) {
      const idx = u.pathname.indexOf('/sites/', shareSpoofedMatch[0].length - 1);
      if (idx >= 0) {
        u = new URL(`${u.origin}${u.pathname.slice(idx)}${u.search}${u.hash}`);
      }
    }

    const parts = u.pathname.split('/').filter(Boolean);
    if (parts.length < 3 || parts[0].toLowerCase() !== 'sites') {
      throw new Error(
        'Não foi possível resolver a URL. Use "Copiar link" do SharePoint (arquivo ou pasta).',
      );
    }

    const siteName = decodeURIComponent(parts[1] ?? '').trim();
    const libraryName = decodeURIComponent(parts[2] ?? '').trim();
    const restParts = parts.slice(3).map((p) => decodeURIComponent(p));
    const restPath = restParts.join('/');

    const site = await graphGet<{ id?: string }>(
      token,
      `https://graph.microsoft.com/v1.0/sites/${encodeURIComponent(
        u.hostname,
      )}:/sites/${encodeURIComponent(siteName)}?$select=id`,
    );
    const siteId = typeof site.id === 'string' ? site.id.trim() : '';
    if (!siteId) throw new Error('Não foi possível resolver o siteId do SharePoint.');

    const drives = await graphGet<{ value?: Array<{ id?: string; name?: string; webUrl?: string }> }>(
      token,
      `https://graph.microsoft.com/v1.0/sites/${encodeURIComponent(siteId)}/drives?$select=id,name,webUrl`,
    );
    const driveList = Array.isArray(drives.value) ? drives.value : [];
    const libraryKey = libraryName.toLowerCase();
    const pickedDrive = driveList.find((d) => String(d?.name ?? '').trim().toLowerCase() === libraryKey)
      ?? driveList.find((d) => {
        const web = String(d?.webUrl ?? '').toLowerCase();
        return Boolean(web) && web.includes(`/${encodeURIComponent(libraryName).toLowerCase()}`.replace(/%20/g, ' '));
      })
      ?? null;

    const getDefaultDriveId = async () => {
      const defaultDrive = await graphGet<{ id?: string }>(
        token,
        `https://graph.microsoft.com/v1.0/sites/${encodeURIComponent(siteId)}/drive?$select=id`,
      );
      const defId = typeof defaultDrive.id === 'string' ? defaultDrive.id.trim() : '';
      return defId || null;
    };

    const resolveByTraversal = async (driveId: string, pathToResolve: string) => {
      const segs = pathToResolve
        .split('/')
        .map((s) => String(s ?? '').trim())
        .filter(Boolean);

      const root = await graphGet<{ id?: string; name?: string; folder?: unknown }>(
        token,
        `https://graph.microsoft.com/v1.0/drives/${encodeURIComponent(
          driveId,
        )}/root?$select=id,name,folder`,
      );
      const rootId = typeof root.id === 'string' ? root.id.trim() : '';
      if (!rootId) throw new Error('Não foi possível resolver a raiz do drive do SharePoint.');

      let currentId = rootId;
      for (let i = 0; i < segs.length; i += 1) {
        const seg = segs[i]!;
        const wanted = normalizeSegmentForPathMatch(seg);
        const children = await listDriveItemChildren(token, driveId, currentId);
        const exact = children.find(
          (c) => normalizeSegmentForPathMatch(String(c?.name ?? '')) === wanted,
        );
        const fuzzyMatches = exact
          ? [exact]
          : children.filter((c) => {
            const k = normalizeSegmentForPathMatch(String(c?.name ?? ''));
            if (!k) return false;
            return k.includes(wanted) || wanted.includes(k);
          });
        const picked = exact ?? (fuzzyMatches.length === 1 ? fuzzyMatches[0]! : null);
        if (!picked) {
          const folderList = children
            .filter((c) => Boolean(c.folder))
            .slice(0, 40);
          const available = folderList.map((c) => c.name).join(', ');
          if (children.length === 0 || folderList.length === 0) {
            const err = new Error(
              `Não encontrei a pasta/arquivo "${seg}" no SharePoint. O conteúdo da pasta atual está vazio ou o usuário autenticado no Teams não tem permissão de listar o conteúdo da biblioteca/pasta no SharePoint. SOLUÇÃO: abra a pasta/arquivo diretamente no SharePoint no navegador, clique com o botão direito → Copiar link (não use a URL de endereço do navegador), e cole o link "Copiar link" aqui no Portal.`,
            );
            (err as Error & { __securityTrimming?: boolean }).__securityTrimming = true;
            throw err;
          }
          throw new Error(
            `Não encontrei a pasta/arquivo "${seg}" no SharePoint. Pastas disponíveis: ${available || '-'}`,
          );
        }

        const isLast = i === segs.length - 1;
        if (isLast) {
          return {
            id: picked.id,
            name: picked.name,
            folder: picked.folder,
            file: picked.file,
            parentReference: { driveId, id: currentId },
          };
        }

        if (!picked.folder) {
          throw new Error(`O caminho do SharePoint aponta para um arquivo antes do final: ${picked.name}`);
        }
        currentId = picked.id;
      }

      throw new Error('Falha ao resolver caminho do SharePoint.');
    };

    const resolvePathDirect = async (driveId: string, pathToResolve: string) => {
      if (!pathToResolve) {
        const root = await graphGet<{ id?: string; name?: string; folder?: unknown }>(
          token,
          `https://graph.microsoft.com/v1.0/drives/${encodeURIComponent(
            driveId,
          )}/root?$select=id,name,folder`,
        );
        if (!root.folder || !root.id) {
          throw new Error('A URL informada não aponta para uma pasta');
        }
        const rootName = typeof root.name === 'string' ? root.name.trim() : '';
        return {
          id: String(root.id),
          name: rootName,
          folder: root.folder,
          file: undefined,
          parentReference: { driveId, id: String(root.id) },
        } as { id: string; name?: string; folder?: unknown; file?: unknown; parentReference?: { driveId?: string; id?: string } };
      }

      const encoded = pathToResolve
        .split('/')
        .map((seg) => encodeURIComponent(seg))
        .join('/');
      return await graphGet<{
        id: string;
        name?: string;
        folder?: unknown;
        file?: unknown;
        parentReference?: { driveId?: string; id?: string };
      }>(
        token,
        `https://graph.microsoft.com/v1.0/drives/${encodeURIComponent(
          driveId,
        )}/root:/${encoded}?$select=id,name,folder,file,parentReference`,
      );
    };

    const resolvePath = async (driveId: string, pathToResolve: string) => {
      try {
        return await resolvePathDirect(driveId, pathToResolve);
      } catch (eDirect: unknown) {
        const msg = eDirect instanceof Error ? eDirect.message : String(eDirect);
        if (!isGraphPathNotFound(msg)) throw eDirect;
        try {
          return (await resolveByTraversal(driveId, pathToResolve)) as {
            id: string;
            name?: string;
            folder?: unknown;
            file?: unknown;
            parentReference?: { driveId?: string; id?: string };
          };
        } catch (eTrav: unknown) {
          const t = eTrav instanceof Error ? eTrav : new Error(String(eTrav));
          (t as Error & { __directFailed?: unknown }).__directFailed = eDirect;
          throw t;
        }
      }
    };

    const buildCandidatePaths = () => {
      const base = [restPath, [libraryName, restPath].filter(Boolean).join('/')].filter(Boolean);
      const out: string[] = [];
      for (const p of base) {
        if (!p) continue;
        if (!out.includes(p)) out.push(p);
      }
      return out;
    };

    const orderedDrives = async (): Promise<string[]> => {
      const seen = new Set<string>();
      const out: string[] = [];
      const push = (id: string | null | undefined) => {
        const x = typeof id === 'string' ? id.trim() : '';
        if (!x || seen.has(x)) return;
        seen.add(x);
        out.push(x);
      };
      push(pickedDrive?.id);
      for (const d of driveList) push(d?.id);
      try { push(await getDefaultDriveId()); } catch { /* ignore */ }
      return out;
    };

    const tryAllDrives = async () => {
      const dIds = await orderedDrives();
      const candidatePaths = buildCandidatePaths();
      let lastErr: unknown = null;
      let lastSecurityTrimDrive: string | null = null;

      for (const currentDriveId of dIds) {
        for (const p of candidatePaths) {
          try {
            const data = await resolvePath(currentDriveId, p);
            return await resolveFromDriveItem(currentDriveId, data);
          } catch (e: unknown) {
            const errObj = (e instanceof Error ? e : new Error(String(e))) as Error & { __securityTrimming?: boolean };
            if (errObj.__securityTrimming) lastSecurityTrimDrive = currentDriveId;
            lastErr = e;
            continue;
          }
        }
      }

      if (lastSecurityTrimDrive) {
        const trimmedErr = new Error(
          'Não foi possível encontrar a pasta/arquivo no SharePoint. O usuário autenticado não tem permissão para listar o conteúdo da biblioteca (security trimming). SOLUÇÃO: abra o arquivo/pasta diretamente no SharePoint no navegador, clique com o botão direito → Copiar link, e cole o link "Copiar link" aqui no Portal.',
        );
        throw trimmedErr;
      }
      throw lastErr instanceof Error ? lastErr : new Error('Falha ao resolver pasta do SharePoint.');
    };

    if (!restPath) {
      const dIds = await orderedDrives();
      for (const d of dIds) {
        try {
          const data = await resolvePathDirect(d, restPath);
          return await resolveFromDriveItem(d, data);
        } catch { /* ignore */ }
      }
      throw new Error('Não foi possível resolver a pasta raiz da biblioteca no SharePoint.');
    }

    return await tryAllDrives();
  };

  try {
    const shareId = toShareId(folderUrl);
    const data = await graphGet<{
      id: string;
      name?: string;
      folder?: unknown;
      file?: unknown;
      parentReference?: { driveId?: string; id?: string };
    }>(
      token,
      `https://graph.microsoft.com/v1.0/shares/${encodeURIComponent(
        shareId,
      )}/driveItem?$select=id,name,folder,file,parentReference`,
    );

    const driveId = data.parentReference?.driveId;
    return await resolveFromDriveItem(String(driveId ?? '').trim(), data);
  } catch (e: unknown) {
    const message = e instanceof Error ? e.message : String(e);
    if (!isGraphShareResolutionError(message)) throw e;
    return await resolveFromSitePathUrl();
  }
}

async function listDriveItemChildren(
  token: string,
  driveId: string,
  itemId: string,
) {
  const data = await graphGet<{
    value: Array<{
      name: string;
      id: string;
      lastModifiedDateTime?: string;
      file?: { mimeType?: string };
      folder?: unknown;
    }>;
  }>(
    token,
    `https://graph.microsoft.com/v1.0/drives/${encodeURIComponent(
      driveId,
    )}/items/${encodeURIComponent(itemId)}/children?$select=name,id,lastModifiedDateTime,file,folder`,
  );

  return data.value;
}

async function resolveDrivePathDirect(
  token: string,
  driveId: string,
  driveRelativePath: string,
): Promise<{ id: string; name?: string; folder?: unknown; file?: unknown; parentReference?: { driveId?: string; id?: string } } | null> {
  const path = String(driveRelativePath ?? '').replace(/^\s*\/+|\/+\s*$/g, '');
  if (!path || !driveId || !token) return null;
  const encoded = path
    .split('/')
    .map((seg) => encodeURIComponent(seg))
    .join('/');
  try {
    return await graphGet<{
      id: string;
      name?: string;
      folder?: unknown;
      file?: unknown;
      parentReference?: { driveId?: string; id?: string };
    }>(
      token,
      `https://graph.microsoft.com/v1.0/drives/${encodeURIComponent(
        driveId,
      )}/root:/${encoded}?$select=id,name,folder,file,parentReference`,
    );
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : String(e);
    const parsed = parseGraphErrorText(msg);
    const code = (parsed.code ?? '').toLowerCase();
    const inner = (parsed.innerCode ?? '').toLowerCase();
    if (
      code === 'itemnotfound' ||
      inner === 'itemnotfound' ||
      /itemNotFound/i.test(msg) ||
      /0x80070002/i.test(msg) ||
      /cannot find the file specified/i.test(msg) ||
      /The resource could not be found/i.test(msg) ||
      /HTTP 404/.test(msg)
    ) {
      return null;
    }
    throw e;
  }
}

const MESES_PT_BR = [
  'Janeiro',
  'Fevereiro',
  'Março',
  'Abril',
  'Maio',
  'Junho',
  'Julho',
  'Agosto',
  'Setembro',
  'Outubro',
  'Novembro',
  'Dezembro',
];

function buildRecursoAdfegoSuffixes(options?: { minYear?: number; maxYear?: number }): Array<{ suffixPath: string; targetKind: 'folder' | 'file' }> {
  const out: Array<{ suffixPath: string; targetKind: 'folder' | 'file' }> = [];
  const now = new Date();
  const currentYear = now.getFullYear();
  const maxYear = typeof options?.maxYear === 'number' ? options.maxYear : currentYear + 1;
  const minYear = typeof options?.minYear === 'number' ? options.minYear : Math.max(2023, currentYear - 3);
  const SUFIXO_FIXO = 'Relatório Orgão/ADFEGO';
  for (let y = minYear; y <= maxYear; y += 1) {
    for (const m of MESES_PT_BR) {
      out.push({ suffixPath: `${y}/${m}/${SUFIXO_FIXO}`, targetKind: 'folder' });
      for (const ext of ['xls', 'xlsx', 'xlsm']) {
        out.push({ suffixPath: `${y}/${m}/${SUFIXO_FIXO}/ADFEGO.${ext}`, targetKind: 'file' });
      }
    }
  }
  out.push({ suffixPath: SUFIXO_FIXO, targetKind: 'folder' });
  for (const ext of ['xls', 'xlsx', 'xlsm']) {
    out.push({ suffixPath: `${SUFIXO_FIXO}/ADFEGO.${ext}`, targetKind: 'file' });
  }
  return out;
}

function parseSitePathRestPath(folderUrl: string): { host: string; siteName: string; libraryName: string; restPath: string } | null {
  const u = (() => {
    try {
      return new URL(folderUrl);
    } catch {
      return null;
    }
  })();
  if (!u) return null;
  const parts = u.pathname.split('/').filter(Boolean);
  if (parts.length < 3 || parts[0].toLowerCase() !== 'sites') return null;
  const siteName = decodeURIComponent(parts[1] ?? '').trim();
  const libraryName = decodeURIComponent(parts[2] ?? '').trim();
  const restParts = parts.slice(3).map((p) => decodeURIComponent(p));
  const restPath = restParts.join('/');
  return { host: u.hostname, siteName, libraryName, restPath };
}

async function expandRecursoAdfegoFileCandidates(opts: {
  token: string;
  driveId: string;
  folderUrl: string;
  baseRestPath?: string;
  minYear?: number;
  maxYear?: number;
}): Promise<Array<{ id: string; name: string; lastModifiedDateTime?: string; folderPath: string; parentId?: string }>> {
  const { token, driveId, folderUrl } = opts;
  const out: Array<{ id: string; name: string; lastModifiedDateTime?: string; folderPath: string; parentId?: string }> = [];
  if (!driveId || !token) return out;
  const parsed = typeof opts.baseRestPath === 'string' && opts.baseRestPath.trim()
    ? null
    : parseSitePathRestPath(folderUrl);
  const basePath =
    (typeof opts.baseRestPath === 'string' && opts.baseRestPath.trim())
      ? opts.baseRestPath.trim().replace(/^\s*\/+|\/+\s*$/g, '')
      : (parsed?.restPath ?? '');
  if (!basePath && !/sharepoint\./i.test(folderUrl)) return out;
  const suffixes = buildRecursoAdfegoSuffixes({
    minYear: Number.isFinite(opts.minYear as number) ? (opts.minYear as number) : undefined,
    maxYear: Number.isFinite(opts.maxYear as number) ? (opts.maxYear as number) : undefined,
  });
  const isDoc = (n: string) => /\.(xlsx|xlsm|xls|csv)$/i.test(String(n ?? '').trim());
  const pushFile = (
    f: { id: string; name: string; lastModifiedDateTime?: string },
    folderPath: string,
    parentId?: string,
  ) => {
    if (!isDoc(f.name)) return;
    if (out.find((x) => x.id === f.id)) return;
    out.push({ id: f.id, name: f.name, lastModifiedDateTime: f.lastModifiedDateTime, folderPath, parentId });
  };
  for (const s of suffixes) {
    const fullPath = basePath ? `${basePath}/${s.suffixPath}` : s.suffixPath;
    let resolved: Awaited<ReturnType<typeof resolveDrivePathDirect>> = null;
    try {
      resolved = await resolveDrivePathDirect(token, driveId, fullPath);
    } catch {
      resolved = null;
    }
    if (!resolved || !resolved.id) continue;
    if (resolved.file) {
      const segs = s.suffixPath.split('/');
      const folderSegs = segs.slice(0, -1);
      const fpRel = folderSegs.join('/') || 'ADFEGO';
      const fpFull = basePath ? `${basePath}/${fpRel}` : fpRel;
      let parentId: string | undefined = (resolved.parentReference as { id?: string } | undefined)?.id;
      if (!parentId && folderSegs.length > 0) {
        const parentFolderFull = basePath ? `${basePath}/${folderSegs.join('/')}` : folderSegs.join('/');
        try {
          const p = await resolveDrivePathDirect(token, driveId, parentFolderFull);
          if (p && p.id && p.folder) parentId = String(p.id);
        } catch { /* ignore */ }
      }
      pushFile({ id: resolved.id, name: String(resolved.name ?? `ADFEGO_${fpRel}`).trim() }, fpFull, parentId);
    } else if (resolved.folder) {
      let children: Array<{ id: string; name: string; lastModifiedDateTime?: string; file?: unknown; folder?: unknown }> = [];
      try {
        children = await listDriveItemChildren(token, driveId, resolved.id);
      } catch {
        children = [];
      }
      const parentFpRel = s.suffixPath || 'ADFEGO';
      const parentFpFull = basePath ? `${basePath}/${parentFpRel}` : parentFpRel;
      const queue: Array<{ id: string; depth: number; path: string; parentId: string }> = [];
      if (children.length > 0) queue.push({ id: resolved.id, depth: 0, path: parentFpFull, parentId: resolved.id });
      const visited = new Set<string>();
      let safety = 0;
      while (queue.length > 0 && safety < 5000) {
        safety += 1;
        const cur = queue.shift();
        if (!cur) break;
        if (visited.has(cur.id)) continue;
        visited.add(cur.id);
        let kids = cur.id === resolved.id ? children : null;
        if (!kids) {
          try {
            kids = await listDriveItemChildren(token, driveId, cur.id);
          } catch {
            kids = [];
          }
        }
        for (const c of kids) {
          if (c.file && isDoc(String(c.name ?? ''))) {
            pushFile(
              c as { id: string; name: string; lastModifiedDateTime?: string },
              cur.path,
              cur.id,
            );
          } else if (c.folder && cur.depth < 4) {
            const cName = String(c.name ?? '').trim();
            if (cName && cName.toLowerCase() === 'importados') continue;
            queue.push({
              id: c.id,
              depth: cur.depth + 1,
              path: cur.path ? `${cur.path}/${c.name}` : String(c.name ?? ''),
              parentId: cur.id,
            });
          }
        }
      }
    }
  }
  return out;
}

type AdfegoEnvConfig = {
  baseUrl: string;
  siteHost: string;
  siteName: string;
  libraryName: string;
  restPath: string;
  minYear?: number;
  maxYear?: number;
  overrideFolderUrl?: string;
  shareLink?: string;
  specificFileUrls?: string[];
};

function loadRecursoAdfegoEnvConfig(folderUrlFallback: string): AdfegoEnvConfig | null {
  const overrideFolderUrlRaw =
    (String(process.env.SHAREPOINT_ADFEGO_OVERRIDE_FOLDER_URL ?? '').trim()) ||
    (String(process.env.SHAREPOINT_ADFEGO_SHARE_LINK ?? '').trim()) ||
    '';
  const overrideFolderUrl = overrideFolderUrlRaw || undefined;
  const shareLink = String(process.env.SHAREPOINT_ADFEGO_SHARE_LINK ?? '').trim() || undefined;
  const specificRaw = String(process.env.SHAREPOINT_ADFEGO_SPECIFIC_FILE_URLS ?? process.env.SHAREPOINT_ADFEGO_FILES ?? '').trim();
  const specificFileUrls = specificRaw
    ? specificRaw.split(/[,;]/).map((s) => s.trim()).filter(Boolean)
    : undefined;
  const baseUrl =
    (String(process.env.SHAREPOINT_ADFEGO_BASE_URL ?? '').trim()) ||
    (String(process.env.SHAREPOINT_FOLDER_URL ?? '').trim()) ||
    '';
  const explicitHost = String(process.env.SHAREPOINT_ADFEGO_SITE_HOST ?? '').trim();
  const explicitSite = String(process.env.SHAREPOINT_ADFEGO_SITE_NAME ?? '').trim();
  const explicitLib = String(process.env.SHAREPOINT_ADFEGO_LIBRARY ?? '').trim();
  const explicitRest = String(process.env.SHAREPOINT_ADFEGO_REL_PATH ?? '').trim();
  const minEnv = process.env.SHAREPOINT_ADFEGO_MIN_YEAR;
  const maxEnv = process.env.SHAREPOINT_ADFEGO_MAX_YEAR;
  const minYear = minEnv ? Number(minEnv) : undefined;
  const maxYear = maxEnv ? Number(maxEnv) : undefined;

  const primary = overrideFolderUrl || baseUrl || folderUrlFallback || '';
  const parsed = primary ? parseSitePathRestPath(primary) : null;

  const siteHost = explicitHost || parsed?.host || '';
  const siteName = explicitSite || parsed?.siteName || '';
  const libraryName = explicitLib || parsed?.libraryName || '';
  const restPath = explicitRest
    ? explicitRest.replace(/^\s*\/+|\/+\s*$/g, '')
    : (parsed?.restPath ?? '').replace(/^\s*\/+|\/+\s*$/g, '');

  if (!siteHost || !siteName || !libraryName) {
    if (!overrideFolderUrl && !shareLink && !(specificFileUrls && specificFileUrls.length > 0)) return null;
  }
  return {
    baseUrl: primary,
    siteHost,
    siteName,
    libraryName,
    restPath,
    minYear: Number.isFinite(minYear as number) ? (minYear as number) : undefined,
    maxYear: Number.isFinite(maxYear as number) ? (maxYear as number) : undefined,
    overrideFolderUrl,
    shareLink,
    specificFileUrls,
  };
}

async function resolveSingleItemByAnyUrl(
  token: string,
  url: string,
): Promise<{
  driveId: string;
  itemId: string;
  itemName: string;
  specificFile: null | { id: string; name: string };
} | null> {
  const u = String(url ?? '').trim();
  if (!u) return null;
  try {
    return await resolveDriveItemFromShareUrl(token, u);
  } catch {
    return null;
  }
}

async function resolveDriveIdFromEnvOrUrl(
  token: string,
  cfg: AdfegoEnvConfig,
): Promise<string | null> {
  try {
    const site = await graphGet<{ id?: string }>(
      token,
      `https://graph.microsoft.com/v1.0/sites/${encodeURIComponent(
        cfg.siteHost,
      )}:/sites/${encodeURIComponent(cfg.siteName)}?$select=id`,
    );
    const siteId = typeof site.id === 'string' ? site.id.trim() : '';
    if (!siteId) return null;
    const drives = await graphGet<{ value?: Array<{ id?: string; name?: string; webUrl?: string }> }>(
      token,
      `https://graph.microsoft.com/v1.0/sites/${encodeURIComponent(siteId)}/drives?$select=id,name,webUrl`,
    );
    const driveList = Array.isArray(drives.value) ? drives.value : [];
    const libKey = cfg.libraryName.toLowerCase();
    const picked = driveList.find((d) => String(d?.name ?? '').trim().toLowerCase() === libKey)
      ?? driveList.find((d) => {
        const web = String(d?.webUrl ?? '').toLowerCase();
        return Boolean(web) && web.includes(`/${encodeURIComponent(cfg.libraryName).toLowerCase()}`.replace(/%20/g, ' '));
      })
      ?? driveList[0]
      ?? null;
    return typeof picked?.id === 'string' ? picked.id.trim() : null;
  } catch {
    return null;
  }
}

function normalizeNameForMatch(input: string): string {
  return String(input ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

async function resolveRecursoMpgoFolderId(opts: {
  token: string;
  driveId: string;
  baseFolderId: string;
}): Promise<string> {
  const baseChildren = await listDriveItemChildren(opts.token, opts.driveId, opts.baseFolderId);
  const years = baseChildren
    .filter((c) => Boolean(c.folder) && /^\d{4}$/.test(String(c.name ?? '').trim()))
    .sort((a, b) => (b.lastModifiedDateTime ?? '').localeCompare(a.lastModifiedDateTime ?? ''));

  const isRelatorioOrgaoFolder = (name: string) => {
    const k = normalizeNameForMatch(name);
    return k === 'relatorio orgao';
  };

  const isMpgoFolder = (name: string) => {
    const k = normalizeNameForMatch(name);
    return k === 'mpgo' || k.endsWith(' mpgo') || k.includes('mpgo');
  };

  const importedFolderName = normalizeNameForMatch(
    process.env.SHAREPOINT_IMPORTED_FOLDER ?? 'Importados',
  );
  const candidates: Array<{
    id: string;
    year: string;
    month: string;
    monthModified: string;
    mpgoModified: string;
    directPdfCount: number;
    latestDirectPdfModified: string;
  }> = [];

  for (const y of years) {
    const yearChildren = await listDriveItemChildren(opts.token, opts.driveId, y.id);
    const months = yearChildren
      .filter((c) => Boolean(c.folder))
      .sort((a, b) => (b.lastModifiedDateTime ?? '').localeCompare(a.lastModifiedDateTime ?? ''));

    for (const m of months) {
      const monthChildren = await listDriveItemChildren(opts.token, opts.driveId, m.id);
      const relFolder = monthChildren.find((c) => c.folder && isRelatorioOrgaoFolder(c.name));
      if (!relFolder) continue;

      const relChildren = await listDriveItemChildren(opts.token, opts.driveId, relFolder.id);
      const mpgos = relChildren
        .filter((c) => c.folder && isMpgoFolder(c.name))
        .sort((a, b) => (b.lastModifiedDateTime ?? '').localeCompare(a.lastModifiedDateTime ?? ''));
      for (const mpgo of mpgos) {
        const mpgoChildren = await listDriveItemChildren(opts.token, opts.driveId, mpgo.id);
        const directPdfs = mpgoChildren
          .filter(
            (c) =>
              Boolean(c.file) &&
              /\.pdf$/i.test(String(c.name ?? '').trim()),
          )
          .sort((a, b) => (b.lastModifiedDateTime ?? '').localeCompare(a.lastModifiedDateTime ?? ''));
        candidates.push({
          id: mpgo.id,
          year: String(y.name ?? ''),
          month: String(m.name ?? ''),
          monthModified: String(m.lastModifiedDateTime ?? ''),
          mpgoModified: String(mpgo.lastModifiedDateTime ?? ''),
          directPdfCount: directPdfs.length,
          latestDirectPdfModified: String(directPdfs[0]?.lastModifiedDateTime ?? ''),
        });
      }
    }
  }

  const best = candidates.sort((a, b) => {
    if ((a.directPdfCount > 0) !== (b.directPdfCount > 0)) {
      return a.directPdfCount > 0 ? -1 : 1;
    }
    const directCmp = b.latestDirectPdfModified.localeCompare(a.latestDirectPdfModified);
    if (directCmp !== 0) return directCmp;
    const mpgoCmp = b.mpgoModified.localeCompare(a.mpgoModified);
    if (mpgoCmp !== 0) return mpgoCmp;
    return b.monthModified.localeCompare(a.monthModified);
  })[0];
  if (best) return best.id;

  throw new Error(
    'Não encontrei a pasta "Relatório Orgão/MPGO" dentro do caminho informado (anos/meses).',
  );
}

const __MESES_PT_COMPLETO = [
  'janeiro', 'fevereiro', 'marco', 'abril', 'maio', 'junho',
  'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro',
];
const __NOME_MES_PT = (mes0Idx: number): string => __MESES_PT_COMPLETO[mes0Idx] ?? '';

async function expandRecursoExtratosAnoMesCorrenteCandidates(opts: {
  token: string;
  driveId: string;
  baseFolderId: string;
  basePath: string;
  subfolderCandidates?: string[];
  __trace?: (step: string, data: Record<string, unknown>) => void;
  permitirPdfSisbr?: boolean;
}): Promise<Array<{ id: string; name: string; lastModifiedDateTime?: string; folderPath: string; parentId: string }>> {
  const tr = opts.__trace ?? (() => {});
  const isRecuperacaoCreditoInPath = (path: string) => {
    const k = normalizeNameForMatch(path);
    return k.includes('recuperacao de credito') || k.endsWith('9.recuperacao de credito');
  };
  const isDoc = (n: string) => /\.(xlsx|xlsm|xls)$/i.test(String(n ?? '').trim());
  // PDF SOMENTE para SISBR e SOMENTE se caller explicitamente permitir (forceKind=relatorio).
  // Qualquer outro forceKind (extratos, orgao etc) continua 100% Excel.
  const isDocOuPdfSeSisbr = (n: string, folderPath: string): boolean => {
    if (isDoc(n)) return true;
    if (!Boolean(opts.permitirPdfSisbr)) return false;
    const temSisbr = (path: string): boolean => {
      const k = normalizeNameForMatch(String(path ?? ''));
      return k.includes('sisbr') || k.includes('relatorio sisbr');
    };
    if (!temSisbr(folderPath)) return false;
    return isPdfFile(String(n ?? ''));
  };
  const out: Array<{ id: string; name: string; lastModifiedDateTime?: string; folderPath: string; parentId: string }> = [];
  if (!opts.driveId || !opts.token) return out;

  const cleanedBasePath = String(opts.basePath ?? '').replace(/^\s*\/+|\/+\s*$/g, '');

  // ====== REGRA DEFINITIVA: SÓ MÊS ANTERIOR DO VIGENTE (1 offset, MÁXIMA VELOCIDADE) ======
  const mesCorrente0Idx = new Date().getMonth();
  let alvoMes0 = mesCorrente0Idx - 1;
  let alvoAnoN = new Date().getFullYear();
  while (alvoMes0 < 0) { alvoMes0 += 12; alvoAnoN -= 1; }
  while (alvoMes0 > 11) { alvoMes0 -= 12; alvoAnoN += 1; }
  const alvoAno = String(alvoAnoN);
  const alvoMesNorm = __NOME_MES_PT(alvoMes0);
  const alvoMesVariacoes = [
    alvoMesNorm ? alvoMesNorm.charAt(0).toUpperCase() + alvoMesNorm.slice(1) : '',
    alvoMesNorm ? alvoMesNorm.toLowerCase() : '',
    MESES_PT_BR[alvoMes0] ?? '',
  ].filter(Boolean).filter((v, i, a) => a.indexOf(v) === i);
  const pastaExtratoVariacoesDefault = ['Extrato Recurso', 'Extratos Recurso', 'Extrato de Recurso', 'Extratos de Recurso'];
  const subfolderCandidatesNormalized: string[] = Array.isArray(opts.subfolderCandidates) && opts.subfolderCandidates.length > 0
    ? opts.subfolderCandidates.slice()
    : pastaExtratoVariacoesDefault.slice();

  tr('setup', { alvoAno, alvoMes0, alvoMesNorm, alvoMesVariacoes, cleanedBasePath, baseFolderIdLen: (opts.baseFolderId || '').length, baseFolderIdEqDriveId: opts.baseFolderId === opts.driveId });

  const safeListChildren = async (folderId: string): Promise<Array<{ id: string; name: string; lastModifiedDateTime?: string; file?: unknown; folder?: unknown }>> => {
    if (!folderId) return [];
    try {
      const r = await listDriveItemChildren(opts.token, opts.driveId, folderId);
      tr('list', { folderIdPrefix: folderId.slice(0, 8), count: r.length });
      return r;
    } catch (e) {
      tr('listErr', { folderIdPrefix: folderId.slice(0, 8), err: String(e instanceof Error ? e.message : e).slice(0, 120) });
      return [];
    }
  };

  // ====== PASSO 1: Encontrar a Pasta RAIZ de onde descender (Recuperação de Crédito ou equivalente) ======
  let startId: string | null = null;
  let startPath: string = '';
  if (opts.baseFolderId && opts.baseFolderId !== opts.driveId) {
    // Temos folderId real (resolveDirect deu certo). Usamos direto.
    startId = opts.baseFolderId;
    startPath = cleanedBasePath;
    tr('startMode', { mode: 'folderId', startIdPrefix: startId.slice(0, 8), startPath });
  } else {
    // driveId or null: listar a raiz da biblioteca e achar "Documents" filhos para chegar até Recuperação de Crédito via estrutura conhecida.
    // Como não temos path absoluto aqui, usamos basePath (se tiver) para navegar ou BFS curto (max 2 níveis) atrás de Recuperação de Crédito.
    tr('startMode', { mode: 'driveLevel' });
    const roots = await safeListChildren(opts.driveId);
    const tryNavegarPorBasePathSegmentos = async (): Promise<{ id: string | null; path: string }> => {
      if (!cleanedBasePath) return { id: null, path: '' };
      const segs = cleanedBasePath.split('/').filter(Boolean);
      let cur: Array<typeof roots[number]> = roots;
      let curId: string | null = null;
      let accPath = '';
      for (let i = 0; i < segs.length; i++) {
        const seg = segs[i];
        const segNorm = normalizeNameForMatch(seg);
        const match = cur.find((c) => c.folder && normalizeNameForMatch(c.name) === segNorm)
          ?? cur.find((c) => c.folder && normalizeNameForMatch(c.name).includes(segNorm.slice(0, Math.min(4, segNorm.length))));
        if (!match) return { id: null, path: accPath };
        curId = String(match.id);
        accPath = accPath ? `${accPath}/${match.name}` : String(match.name);
        cur = await safeListChildren(curId);
        if (cur.length === 0) return { id: null, path: accPath };
      }
      return { id: curId, path: accPath };
    };
    const naveg = await tryNavegarPorBasePathSegmentos();
    if (naveg.id) {
      startId = naveg.id;
      startPath = naveg.path;
      tr('startFound', { where: 'basePathSegments', startIdPrefix: startId.slice(0, 8), startPath });
    } else {
      // Fallback BFS curto (2 níveis) atrás de Recuperação de Crédito / 9.Recuperação / Diretoria etc.
      const queue: Array<{ id: string; path: string; depth: number }> = roots.filter((r) => r.folder).map((r) => ({ id: String(r.id), path: String(r.name ?? ''), depth: 0 }));
      const seen = new Set<string>();
      while (queue.length > 0 && !startId) {
        const cur = queue.shift()!;
        if (seen.has(cur.id)) continue;
        seen.add(cur.id);
        if (isRecuperacaoCreditoInPath(cur.path) || normalizeNameForMatch(cur.path).includes('9.recuperacao')) {
          startId = cur.id; startPath = cur.path;
          tr('startFound', { where: 'bfs2', startIdPrefix: startId.slice(0, 8), startPath });
          break;
        }
        if (cur.depth < 2) {
          const kids = await safeListChildren(cur.id);
          for (const k of kids) {
            if (k.folder) queue.push({ id: String(k.id), path: cur.path ? `${cur.path}/${k.name}` : String(k.name ?? ''), depth: cur.depth + 1 });
          }
        }
      }
      if (!startId) {
        // Sem alternativa: usar raiz drive mesmo (vazio). Provavelmente não encontra nada mas evita null.
        tr('startWarn', { msg: 'nenhuma pasta recuperacao de credito encontrada na raiz; usando drive root.' });
        if (roots.length > 0) {
          // prefer qualquer folder da raiz
          const any = roots.find((r) => r.folder) ?? roots[0];
          startId = String(any.id); startPath = String(any.name ?? '');
        }
      }
    }
  }
  if (!startId) { tr('noStart', {}); return out; }

  // ====== PASSO 2: Descender ANO (4 dígitos) ======
  let yearId: string | null = null;
  let yearName = '';
  const lvlStart = await safeListChildren(startId);
  // 1) Tem pastas de ano DIRETAMENTE?
  let yearCandidates = lvlStart.filter((c) => c.folder && /^\d{4}$/.test(String(c.name ?? '').trim())) as Array<typeof lvlStart[number]>;
  let desceuRecuperacao = false;
  if (yearCandidates.length === 0) {
    // Não tem anos direto. Ainda estamos acima (ex.: Diretoria / Tec. Inf. / 99-automações_ti). Desce primeiro até Recuperação de Crédito.
    const rc = lvlStart.find((c) => c.folder && isRecuperacaoCreditoInPath(c.name ?? ''))
      ?? lvlStart.find((c) => c.folder && normalizeNameForMatch(String(c.name ?? '')).includes('99.automacoes'));
    if (rc) {
      const kids = await safeListChildren(String(rc.id));
      yearCandidates = kids.filter((c) => c.folder && /^\d{4}$/.test(String(c.name ?? '').trim())) as Array<typeof lvlStart[number]>;
      startPath = startPath ? `${startPath}/${rc.name}` : String(rc.name ?? '');
      startId = String(rc.id);
      desceuRecuperacao = true;
      tr('desceuRC', { rcName: rc.name, startPath, newYearCandidates: yearCandidates.length });
    }
  }
  if (yearCandidates.length === 0) {
    // Ainda sem anos? BFS 1 nível dentro de TODAS as pastas do start atrás de pasta 4 dígitos.
    tr('yearFallbackBFS', {});
    for (const f of lvlStart.filter((x) => x.folder)) {
      if (yearCandidates.length > 0) break;
      const sub = await safeListChildren(String(f.id));
      const ys = sub.filter((c) => c.folder && /^\d{4}$/.test(String(c.name ?? '').trim())) as Array<typeof lvlStart[number]>;
      if (ys.length > 0) {
        yearCandidates = ys;
        startPath = startPath ? `${startPath}/${f.name}` : String(f.name ?? '');
        startId = String(f.id);
        desceuRecuperacao = true;
        break;
      }
    }
  }
  yearCandidates.sort((a, b) => String(b.name ?? '').localeCompare(String(a.name ?? '')));
  for (const y of yearCandidates) {
    if (String(y.name ?? '').trim() === alvoAno) { yearId = String(y.id); yearName = String(y.name ?? ''); break; }
  }
  if (!yearId && yearCandidates.length > 0) {
    yearId = String(yearCandidates[0].id); yearName = String(yearCandidates[0].name ?? '');
    tr('anoFallbackLatest', { yearName, expected: alvoAno });
  }
  if (!yearId) { tr('noYear', {}); return out; }
  tr('anoOk', { yearName, yearIdPrefix: yearId.slice(0, 8) });

  // ====== PASSO 3: Descender MÊS (alvo) ======
  const yearPath = startPath ? `${startPath}/${yearName}` : yearName;
  const monthChildren = await safeListChildren(yearId);
  let monthId: string | null = null;
  let monthName = '';
  for (const v of alvoMesVariacoes) {
    const vN = normalizeNameForMatch(v);
    const mt = monthChildren.find((m) => m.folder && normalizeNameForMatch(m.name) === vN)
      ?? monthChildren.find((m) => m.folder && normalizeNameForMatch(m.name).includes(vN.slice(0, Math.min(3, vN.length))));
    if (mt) { monthId = String(mt.id); monthName = String(mt.name ?? ''); break; }
  }
  if (!monthId && monthChildren.length > 0) {
    const fs = monthChildren.filter((x) => x.folder).sort((a, b) => (b.lastModifiedDateTime ?? '').localeCompare(a.lastModifiedDateTime ?? ''));
    if (fs.length > 0) { monthId = String(fs[0].id); monthName = String(fs[0].name ?? ''); tr('mesFallbackLatest', { monthName, expectedVariacoes: alvoMesVariacoes }); }
  }
  if (!monthId) { tr('noMonth', {}); return out; }
  tr('mesOk', { monthName, monthIdPrefix: monthId.slice(0, 8) });

  // ====== PASSO 4: Descender Pastas-alvo (Extrato Recurso / Relatório de Órgão / Relatório Sisbr etc) ======
  const monthPath = `${yearPath}/${monthName}`;
  const mcKids = await safeListChildren(monthId);
  // TRACE DETALHADO: listar TODAS subpastas/arquivos do mês (para diagnosticar por que só Extrato Recurso aparece)
  tr('mesSubpastasDetalhado', {
    monthName,
    totalItems: mcKids.length,
    items: mcKids.map((c, idx) => ({
      idx,
      name: String(c.name ?? ''),
      isFolder: !!c.folder,
      isFile: !!c.file,
      normName: normalizeNameForMatch(String(c.name ?? ''))
    }))
  });
  const subPastaMatches: Array<{ id: string; name: string }> = [];
  const seenSubPastaIds = new Set<string>();
  tr('subfolderCandidatesEntrada', {
    subfolderCandidatesNormalized,
    subfolderCandidatesNormalizedCount: subfolderCandidatesNormalized.length
  });
  for (const v of subfolderCandidatesNormalized) {
    if (!v) continue;
    const vN = normalizeNameForMatch(v);
    if (!vN) continue;
    const ft = mcKids.find((f) => f.folder && normalizeNameForMatch(f.name) === vN)
      ?? mcKids.find((f) => f.folder && normalizeNameForMatch(f.name).includes(vN.slice(0, Math.min(4, vN.length))));
    if (ft && !seenSubPastaIds.has(String(ft.id))) {
      seenSubPastaIds.add(String(ft.id));
      subPastaMatches.push({ id: String(ft.id), name: String(ft.name ?? '') });
      tr('subpastaMatchPorCandidate', {
        candidate: v,
        matchedName: String(ft.name ?? ''),
        totalAteAgora: subPastaMatches.length
      });
    }
  }
  tr('subpastaAposCandidatesPrincipais', {
    matches: subPastaMatches.map((s) => s.name),
    count: subPastaMatches.length
  });
  // FALLBACK: Adicionar TODAS as demais subpastas do MÊS (menos Importados) como candidatas —
  // garante que pastas com nomes não padronizados (ex.: "Relatórios", "SISBR mensal", "Por órgão" etc) também sejam vasculhadas.
  for (const c of mcKids) {
    if (!c.folder) continue;
    const cName = String(c.name ?? '').trim();
    if (!cName) continue;
    const cNameNorm = normalizeNameForMatch(cName);
    const isImportadosFilter = cNameNorm === 'importados' || cNameNorm.endsWith(' importados') || cNameNorm.startsWith('importados ');
    const jaVisto = seenSubPastaIds.has(String(c.id));
    if (isImportadosFilter) {
      tr('subpastaFallbackBloqueadaImportados', { name: cName, normName: cNameNorm });
      continue;
    }
    if (jaVisto) {
      continue;
    }
    seenSubPastaIds.add(String(c.id));
    subPastaMatches.push({ id: String(c.id), name: cName });
    tr('subpastaAdicionadaFallback', {
      name: cName,
      normName: cNameNorm,
      totalAteAgora: subPastaMatches.length
    });
  }
  tr('subpastaMatchesFinal', {
    total: subPastaMatches.length,
    nomes: subPastaMatches.map((s) => s.name)
  });
  const targetIds: Array<{ id: string; path: string }> = [];
  if (subPastaMatches.length === 0) {
    targetIds.push({ id: monthId, path: monthPath });
    tr('extratoFolderFallback', { reason: 'nenhuma subpasta encontrada no mês; usando mês diretamente.', targetPath: monthPath });
  } else {
    for (const sp of subPastaMatches) {
      targetIds.push({ id: sp.id, path: `${monthPath}/${sp.name}` });
      tr('extratoFolderOk', { extratoName: sp.name, extratoIdPrefix: String(sp.id || '').slice(0, 8), targetPath: `${monthPath}/${sp.name}` });
    }
  }

  // ====== PASSO 5: Coletar planilhas (E PDFs SISBR) de TODAS pastas-alvo ======
  // (RECUSÃO CONTROLADA: máximo 3 níveis — pasta-alvo / órgão / Importados)
  // PDF SÓ É ACEITO SE pathPrefix (caminho da pasta) pertencer ao SISBR. Demais fluxos = só Excel.
  const pushIfExcel = (f: { id?: unknown; name?: unknown; lastModifiedDateTime?: unknown; file?: unknown; folder?: unknown }, pathPrefix: string, parentIdStr: string): boolean => {
    if (!f.file) return false;
    const fname = String(f.name ?? '');
    if (!isDocOuPdfSeSisbr(fname, pathPrefix)) return false;
    out.push({
      id: String(f.id),
      name: fname,
      lastModifiedDateTime: f.lastModifiedDateTime as string | undefined,
      folderPath: pathPrefix,
      parentId: parentIdStr,
    });
    tr('passo5ItemInserido', {
      targetPath: pathPrefix,
      arquivoNome: fname,
      totalInseridosAteAgora: out.length
    });
    return true;
  };
  for (const target of targetIds) {
    const finals = await safeListChildren(target.id);
    tr('passo5ConteudoPastaAlvo', {
      targetPath: target.path,
      targetIdPrefix: String(target.id || '').slice(0, 8),
      totalItems: finals.length,
      items: finals.map((ff, i) => ({
        idx: i,
        name: String(ff.name ?? ''),
        isFolder: !!ff.folder,
        isFile: !!ff.file,
        isDocRegex: isDoc(String(ff.name ?? '')),
        isSisbrPdfPermitido: isDocOuPdfSeSisbr(String(ff.name ?? ''), target.path),
        normName: normalizeNameForMatch(String(ff.name ?? ''))
      }))
    });
    for (const f of finals) {
      if (f.file) {
        // NÍVEL 1 — arquivo direto na pasta-alvo
        const added = pushIfExcel(f, target.path, String(target.id));
        if (!added) {
          tr('passo5ItemPulado', {
            targetPath: target.path,
            itemName: String(f.name ?? ''),
            isFolder: !!f.folder,
            isFile: !!f.file,
            razoes: ['nao_bate_regex_xlsx_xlsm_xls']
          });
        }
        continue;
      }
      if (f.folder) {
        // NÍVEL 2 — SUBPASTA DENTRO da pasta-alvo.
        // 2 casos:
        //   CASO A) subpasta = "Importados" (diretamente na pasta-alvo tipo Extrato Recurso) → desce e procura Excel dentro.
        //   CASO B) subpasta = órgão (TRE, TRT, ADFEGO etc) → desce e depois, se não achar Excel, desce "Importados" NÍVEL 3.
        const subName = String(f.name ?? '').trim();
        const subNameNorm = normalizeNameForMatch(subName);
        const isImportadosDireto = subNameNorm === 'importados' || subNameNorm.endsWith(' importados') || subNameNorm.startsWith('importados ');
        const subPath = `${target.path}/${subName}`;
        const subId = String(f.id);
        if (isImportadosDireto) {
          // CASO A: IGNORAR pasta Importados (TODAS as pastas, ordem explícita usuário)
          // Não desce, não lê arquivos dentro. Pula totalmente.
          const subKidsPreview = await safeListChildren(subId);
          tr('passo5IgnoradoImportadosNivel2', {
            targetPath: target.path,
            subpasta: subName,
            subpastaPath: subPath,
            totalItensPulos: subKidsPreview.length,
            motivoIgnorar: 'usuario_ordem_ignorar_pasta_importados_todas_pastas'
          });
          continue;
        }
        // CASO B: subpasta órgão (TRE / TRT / ADFEGO / etc) dentro da pasta-alvo tipo Relatório Orgão.
        tr('passo5DescendoSubpastaOrgao', {
          targetPath: target.path,
          subpasta: subName,
          subpastaPath: subPath
        });
        const subKids = await safeListChildren(subId);
        tr('passo5SubpastaOrgaoItensDetalhe', {
          subpastaPath: subPath,
          totalItensSubpasta: subKids.length,
          itens: subKids.map((sk, idx) => ({
            idx,
            name: String(sk.name ?? ''),
            isFolder: !!sk.folder,
            isFile: !!sk.file,
            isDocRegex: isDoc(String(sk.name ?? ''))
          }))
        });
        let subAdded = 0;
        for (const sf of subKids) {
          if (sf.file) {
            const ok = pushIfExcel(sf, subPath, subId);
            if (ok) subAdded++;
          }
        }
        // ====== NÍVEL 3 (RECUSÃO FINAL): se subpasta órgão NÃO tem Excel no N2,
        //        desce 1 nível em pastas internas (normalmente "Importados") —
        //        é a estrutura padrão usada no SharePoint (9 pastas órgão → /Importados/*.xlsx)
        //        ===> EXCEÇÃO USUÁRIO EXPLÍCITA: IGNORAR pasta Importados em TODAS as pastas,
        //            por isso, se l3Name normalizado for "Importados", pula sem ler.
        if (subAdded === 0) {
          const level3Folders = subKids.filter((x) => x.folder) as Array<typeof subKids[number]>;
          for (const l3f of level3Folders) {
            const l3Name = String(l3f.name ?? '').trim();
            const l3NameNorm = normalizeNameForMatch(l3Name);
            const isL3Importados = l3NameNorm === 'importados' || l3NameNorm.endsWith(' importados') || l3NameNorm.startsWith('importados ');
            const l3Id = String(l3f.id);
            const l3Path = `${subPath}/${l3Name}`;
            if (isL3Importados) {
              tr('passo5IgnoradoImportadosNivel3', {
                subpastaOrgaoPath: subPath,
                nivel3Nome: l3Name,
                nivel3Path: l3Path,
                motivoIgnorar: 'usuario_ordem_ignorar_pasta_importados_todas_pastas'
              });
              continue;
            }
            tr('passo5DescendoNivel3', {
              subpastaOrgaoPath: subPath,
              nivel3Nome: l3Name,
              nivel3Path: l3Path,
              motivo: 'nenhum_excel_encontrado_nivel2'
            });
            const l3Kids = await safeListChildren(l3Id);
            let l3Added = 0;
            for (const l3Item of l3Kids) {
              if (l3Item.file) {
                const ok = pushIfExcel(l3Item, l3Path, l3Id);
                if (ok) { l3Added++; subAdded++; }
              }
            }
            tr('passo5Nivel3Concluido', {
              nivel3Path: l3Path,
              totalItens: l3Kids.length,
              excelAdicionadosNivel3: l3Added
            });
          }
        }
        tr('passo5SubpastaOrgaoConcluida', {
          subpastaPath: subPath,
          totalItensSubpasta: subKids.length,
          excelAdicionados: subAdded
        });
        continue;
      }
    }
  }
  tr('final', { found: out.length, files: out.map((x) => x.name).slice(0, 5), targetsCount: targetIds.length });
  return out;
}

function findFolderChildId(
  children: Array<{ name: string; id: string; folder?: unknown }>,
  variants: string[],
): string | null {
  const normalizedVariants = variants.map((v) => v.trim().toLowerCase());
  const variantSet = new Set(normalizedVariants);
  const normalizeForFuzzy = (s: string): string =>
    String(s ?? '')
      .trim()
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/\s+\b(de|do|da|dos|das|e|ou|ao|à|para|com|no|na|nos|nas|por)\b/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  const fuzzyVariantSet = new Set(normalizedVariants.map((v) => normalizeForFuzzy(v)));
  let found: { id: string } | null = null;
  for (const c of children) {
    if (!c.folder) continue;
    const childName = String(c.name ?? '').trim();
    if (!childName) continue;
    if (variantSet.has(childName.toLowerCase())) {
      found = { id: c.id };
      break;
    }
    const fuzzy = normalizeForFuzzy(childName);
    if (!fuzzy) continue;
    if (fuzzyVariantSet.has(fuzzy)) {
      found = { id: c.id };
      break;
    }
    let matchHit = false;
    for (const v of fuzzyVariantSet) {
      if (!v) continue;
      if (v === fuzzy) { matchHit = true; break; }
      if (v.length >= 6 && fuzzy.length >= 6 && (v.includes(fuzzy) || fuzzy.includes(v))) {
        matchHit = true;
        break;
      }
    }
    if (matchHit) {
      found = { id: c.id };
      break;
    }
  }
  return found?.id ?? null;
}

function findFolderChild(
  children: Array<{
    name: string;
    id: string;
    folder?: unknown;
    lastModifiedDateTime?: string;
  }>,
  variants: string[],
): null | { name: string; id: string; lastModifiedDateTime: string } {
  const normalizedVariants = variants.map((v) => v.trim().toLowerCase());
  const variantSet = new Set(normalizedVariants);
  const normalizeForFuzzy = (s: string): string =>
    String(s ?? '')
      .trim()
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/\s+\b(de|do|da|dos|das|e|ou|ao|à|para|com|no|na|nos|nas|por)\b/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  const fuzzyVariantSet = new Set(normalizedVariants.map((v) => normalizeForFuzzy(v)));
  let found: typeof children[number] | null = null;
  for (const c of children) {
    if (!c.folder) continue;
    const childName = String(c.name ?? '').trim();
    if (!childName) continue;
    if (variantSet.has(childName.toLowerCase())) {
      found = c;
      break;
    }
    const fuzzy = normalizeForFuzzy(childName);
    if (!fuzzy) continue;
    if (fuzzyVariantSet.has(fuzzy)) {
      found = c;
      break;
    }
    let matchHit = false;
    for (const v of fuzzyVariantSet) {
      if (!v) continue;
      if (v === fuzzy) { matchHit = true; break; }
      if (v.length >= 6 && fuzzy.length >= 6 && (v.includes(fuzzy) || fuzzy.includes(v))) {
        matchHit = true;
        break;
      }
    }
    if (matchHit) {
      found = c;
      break;
    }
  }
  if (!found) return null;
  return {
    name: found.name,
    id: found.id,
    lastModifiedDateTime: String(found.lastModifiedDateTime ?? ''),
  };
}

async function resolveContainerWithSubfolders(opts: {
  token: string;
  driveId: string;
  baseChildren: Array<{
    name: string;
    id: string;
    folder?: unknown;
    lastModifiedDateTime?: string;
  }>;
  extratoCandidates: string[];
  relatorioCandidates: string[];
  maxDepth?: number;
}): Promise<{
  containerName: string;
  extratoFolderId: string;
  relatorioFolderId: string;
}> {
  const directExtrato = findFolderChildId(
    opts.baseChildren,
    opts.extratoCandidates,
  );
  const directRelatorio = findFolderChildId(
    opts.baseChildren,
    opts.relatorioCandidates,
  );

  if (directExtrato && directRelatorio) {
    return {
      containerName: 'base',
      extratoFolderId: directExtrato,
      relatorioFolderId: directRelatorio,
    };
  }

  const maxDepth = opts.maxDepth ?? 5;
  const folders = opts.baseChildren
    .filter((c) => Boolean(c.folder))
    .sort((a, b) =>
      (b.lastModifiedDateTime ?? '').localeCompare(
        a.lastModifiedDateTime ?? '',
      ),
    );

  const queue: Array<{ id: string; path: string; depth: number; lastModifiedDateTime: string }> = folders.map(
    (f) => ({ id: f.id, path: f.name, depth: 1, lastModifiedDateTime: String(f.lastModifiedDateTime ?? '') }),
  );
  const visited = new Set<string>();
  const candidates: Array<{
    containerName: string;
    extratoFolderId: string;
    relatorioFolderId: string;
    lastModifiedDateTime: string;
  }> = [];

  while (queue.length > 0) {
    const current = queue.shift();
    if (!current) break;
    if (visited.has(current.id)) continue;
    visited.add(current.id);

    const children = await listDriveItemChildren(
      opts.token,
      opts.driveId,
      current.id,
    );

    const extrato = findFolderChild(children, opts.extratoCandidates);
    const relatorio = findFolderChild(children, opts.relatorioCandidates);
    if (extrato && relatorio) {
      const lastModifiedDateTime = [current.lastModifiedDateTime, extrato.lastModifiedDateTime, relatorio.lastModifiedDateTime]
        .filter(Boolean)
        .sort()
        .pop() ?? '';
      candidates.push({
        containerName: current.path,
        extratoFolderId: extrato.id,
        relatorioFolderId: relatorio.id,
        lastModifiedDateTime,
      });
    }

    if (current.depth >= maxDepth) continue;
    const childFolders = children
      .filter((c) => Boolean(c.folder))
      .sort((a, b) =>
        (b.lastModifiedDateTime ?? '').localeCompare(
          a.lastModifiedDateTime ?? '',
        ),
      );

    for (const cf of childFolders) {
      queue.push({
        id: cf.id,
        path: `${current.path}/${cf.name}`,
        depth: current.depth + 1,
        lastModifiedDateTime: String(cf.lastModifiedDateTime ?? ''),
      });
    }
  }

  if (candidates.length > 0) {
    const picked = candidates.sort((a, b) =>
      (b.lastModifiedDateTime ?? '').localeCompare(a.lastModifiedDateTime ?? ''),
    )[0]!;
    return {
      containerName: picked.containerName,
      extratoFolderId: picked.extratoFolderId,
      relatorioFolderId: picked.relatorioFolderId,
    };
  }

  const available = folders.map((f) => f.name).join(', ');
  throw new Error(
    `Não encontrei as subpastas de extrato/relatório. Pastas dentro da base: ${available}`,
  );
}

type ResolvedContainer = {
  containerName: string;
  extratoFolderId: string | null;
  relatorioFolderId: string | null;
};

async function resolveFolderIdRecursive(opts: {
  token: string;
  driveId: string;
  baseChildren: Array<{
    name: string;
    id: string;
    folder?: unknown;
    lastModifiedDateTime?: string;
  }>;
  wantedCandidates: string[];
  maxDepth?: number;
}): Promise<{ containerName: string; folderId: string }> {
  const direct = findFolderChildId(opts.baseChildren, opts.wantedCandidates);
  if (direct) return { containerName: 'base', folderId: direct };

  const maxDepth = opts.maxDepth ?? 5;
  const folders = opts.baseChildren
    .filter((c) => Boolean(c.folder))
    .sort((a, b) =>
      (b.lastModifiedDateTime ?? '').localeCompare(a.lastModifiedDateTime ?? ''),
    );

  const queue: Array<{ id: string; path: string; depth: number; lastModifiedDateTime: string }> = folders.map(
    (f) => ({ id: f.id, path: f.name, depth: 1, lastModifiedDateTime: String(f.lastModifiedDateTime ?? '') }),
  );
  const visited = new Set<string>();
  const candidates: Array<{ containerName: string; folderId: string; lastModifiedDateTime: string }> = [];

  while (queue.length > 0) {
    const current = queue.shift();
    if (!current) break;
    if (visited.has(current.id)) continue;
    visited.add(current.id);

    const children = await listDriveItemChildren(opts.token, opts.driveId, current.id);
    const found = findFolderChild(children, opts.wantedCandidates);
    if (found) {
      candidates.push({
        containerName: current.path,
        folderId: found.id,
        lastModifiedDateTime: found.lastModifiedDateTime || current.lastModifiedDateTime,
      });
    }

    if (current.depth >= maxDepth) continue;
    const childFolders = children
      .filter((c) => Boolean(c.folder))
      .sort((a, b) =>
        (b.lastModifiedDateTime ?? '').localeCompare(a.lastModifiedDateTime ?? ''),
      );
    for (const cf of childFolders) {
      queue.push({
        id: cf.id,
        path: `${current.path}/${cf.name}`,
        depth: current.depth + 1,
        lastModifiedDateTime: String(cf.lastModifiedDateTime ?? ''),
      });
    }
  }

  if (candidates.length > 0) {
    const picked = candidates.sort((a, b) =>
      (b.lastModifiedDateTime ?? '').localeCompare(a.lastModifiedDateTime ?? ''),
    )[0]!;
    return { containerName: picked.containerName, folderId: picked.folderId };
  }

  const available = folders.map((f) => f.name).join(', ');
  throw new Error(
    `Não encontrei a subpasta desejada. Pastas dentro da base: ${available}`,
  );
}

function splitFolderCandidatePath(candidate: string): string[] {
  return String(candidate ?? '')
    .split(/[\\/]+/g)
    .map((part) => part.trim())
    .filter(Boolean);
}

function getFolderCandidateLeafNames(candidates: string[]): string[] {
  return candidates
    .map((candidate) => {
      const parts = splitFolderCandidatePath(candidate);
      return parts.length > 0 ? parts[parts.length - 1] : String(candidate ?? '').trim();
    })
    .filter(Boolean);
}

async function resolveFolderIdFromCandidatePaths(opts: {
  token: string;
  driveId: string;
  baseItemId: string;
  baseItemName: string;
  baseChildren: Array<{
    name: string;
    id: string;
    folder?: unknown;
    lastModifiedDateTime?: string;
  }>;
  wantedCandidates: string[];
}): Promise<{ containerName: string; folderId: string } | null> {
  const baseItemName = String(opts.baseItemName ?? '').trim().toLowerCase();
  for (const candidate of opts.wantedCandidates) {
    const parts = splitFolderCandidatePath(candidate);
    if (parts.length < 2) continue;

    const leafName = parts[parts.length - 1]!.trim().toLowerCase();
    if (baseItemName && baseItemName === leafName) {
      return { containerName: 'base', folderId: opts.baseItemId };
    }

    let currentId = opts.baseItemId;
    let currentChildren = opts.baseChildren;
    let currentPath = 'base';
    let startIndex = 0;

    if (baseItemName && baseItemName === parts[0]!.trim().toLowerCase()) {
      startIndex = 1;
    }

    let matched = true;
    for (let index = startIndex; index < parts.length; index += 1) {
      const match = findFolderChild(currentChildren, folderNameVariants(parts[index]!));
      if (!match) {
        matched = false;
        break;
      }
      currentId = match.id;
      currentPath = currentPath === 'base' ? match.name : `${currentPath}/${match.name}`;
      if (index < parts.length - 1) {
        currentChildren = await listDriveItemChildren(opts.token, opts.driveId, currentId);
      }
    }

    if (matched) {
      return { containerName: currentPath, folderId: currentId };
    }
  }
  return null;
}

async function resolveContainerForTarget(opts: {
  token: string;
  driveId: string;
  baseItemId: string;
  baseItemName: string;
  baseChildren: Array<{
    name: string;
    id: string;
    folder?: unknown;
    lastModifiedDateTime?: string;
  }>;
  extratoCandidates: string[];
  relatorioCandidates: string[];
  target: 'both' | 'extratos' | 'relatorio';
}): Promise<ResolvedContainer> {
  if (opts.target === 'both') {
    const both = await resolveContainerWithSubfolders({
      token: opts.token,
      driveId: opts.driveId,
      baseChildren: opts.baseChildren,
      extratoCandidates: opts.extratoCandidates,
      relatorioCandidates: opts.relatorioCandidates,
    });
    return {
      containerName: both.containerName,
      extratoFolderId: both.extratoFolderId,
      relatorioFolderId: both.relatorioFolderId,
    };
  }

  const matchesBase = (candidates: string[]) => {
    const normalized = candidates.map((v) => v.trim().toLowerCase());
    return normalized.includes((opts.baseItemName || '').trim().toLowerCase());
  };

  if (opts.target === 'relatorio') {
    const direct = findFolderChildId(opts.baseChildren, opts.relatorioCandidates);
    if (direct) {
      return { containerName: 'base', extratoFolderId: null, relatorioFolderId: direct };
    }
    if (matchesBase(opts.relatorioCandidates)) {
      return {
        containerName: 'base',
        extratoFolderId: null,
        relatorioFolderId: opts.baseItemId,
      };
    }
    try {
      const found = await resolveFolderIdRecursive({
        token: opts.token,
        driveId: opts.driveId,
        baseChildren: opts.baseChildren,
        wantedCandidates: opts.relatorioCandidates,
      });
      return {
        containerName: found.containerName,
        extratoFolderId: null,
        relatorioFolderId: found.folderId,
      };
    } catch {
      return {
        containerName: 'base',
        extratoFolderId: null,
        relatorioFolderId: opts.baseItemId,
      };
    }
  }

  const direct = findFolderChildId(opts.baseChildren, opts.extratoCandidates);
  if (direct) {
    return { containerName: 'base', extratoFolderId: direct, relatorioFolderId: null };
  }
  if (matchesBase(opts.extratoCandidates)) {
    return {
      containerName: 'base',
      extratoFolderId: opts.baseItemId,
      relatorioFolderId: null,
    };
  }
  const found = await resolveFolderIdRecursive({
    token: opts.token,
    driveId: opts.driveId,
    baseChildren: opts.baseChildren,
    wantedCandidates: opts.extratoCandidates,
  });
  return {
    containerName: found.containerName,
    extratoFolderId: found.folderId,
    relatorioFolderId: null,
  };
}

function folderNameVariants(name: string): string[] {
  const variants = new Set<string>();
  const baseRaw = String(name ?? '').trim();
  if (baseRaw) variants.add(baseRaw);

  const lower = baseRaw.toLowerCase();
  const noAccents = lower.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  if (noAccents && noAccents !== lower) variants.add(noAccents);

  const addPluralAndSingular = (n: string) => {
    const v = n.trim();
    if (!v) return;
    variants.add(v);
    const l = v.toLowerCase();
    if (l.endsWith('s')) variants.add(v.slice(0, -1));
    else variants.add(`${v}s`);
  };

  if (noAccents) addPluralAndSingular(noAccents);
  if (lower) addPluralAndSingular(lower);

  const capitalizeWords = (raw: string): string => {
    const s = String(raw ?? '').trim();
    if (!s) return '';
    return s
      .split(/\s+/)
      .map((w) => (w.length > 0 ? `${w.charAt(0).toUpperCase()}${w.slice(1)}` : ''))
      .join(' ');
  };

  const lowercaseAll = (raw: string): string => String(raw ?? '').toLowerCase();
  const uppercaseAll = (raw: string): string => String(raw ?? '').toUpperCase();
  const stripConjunctions = (s: string): string =>
    String(s ?? '')
      .replace(/\s+\b(de|do|da|dos|das|e|ou|ao|à|para|com|no|na|nos|nas|por)\b/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim();

  const addVariantsFor = (canonical: string, opts: { withConjunctions?: boolean } = {}) => {
    const withConj = opts.withConjunctions ?? true;
    const cap = capitalizeWords(canonical);
    const low = lowercaseAll(canonical);
    const upe = uppercaseAll(canonical);
    const noAcc = low.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const capNoAcc = capitalizeWords(noAcc);
    variants.add(cap);
    variants.add(low);
    variants.add(upe);
    if (noAcc !== low) {
      variants.add(noAcc);
      variants.add(capNoAcc);
      variants.add(uppercaseAll(noAcc));
    }
    addPluralAndSingular(cap);
    addPluralAndSingular(low);
    addPluralAndSingular(upe);
    if (noAcc !== low) {
      addPluralAndSingular(noAcc);
      addPluralAndSingular(capNoAcc);
      addPluralAndSingular(uppercaseAll(noAcc));
    }
    const stripped = stripConjunctions(cap);
    if (withConj && stripped && stripped !== cap) {
      addVariantsFor(stripped, { withConjunctions: false });
    }
  };

  if (noAccents === 'relatorio' || lower === 'relatório' || lower === 'relatorio') {
    addVariantsFor('Relatório');
    addVariantsFor('Relatorios');
    addVariantsFor('Relatórios');
  }

  if (lower === 'extrato' || noAccents === 'extrato') {
    addVariantsFor('Extrato');
    addVariantsFor('Extratos');
  }

  if (lower === 'relatorio' || noAccents === 'relatorio' || lower === 'relatório') {
    const relatorioCompostos = [
      'Relatório Sisbr',
      'Relatório SISBR',
      'Relatório de Sisbr',
      'Relatório do Sisbr',
      'Relatório dos Sisbr',
      'Relatório Orgão',
      'Relatório Órgão',
      'Relatório de Orgão',
      'Relatório de Órgão',
      'Relatório do Orgão',
      'Relatório do Órgão',
      'Relatório dos Orgãos',
      'Relatório dos Órgãos',
      'Relatório SISBR - Valores Liberados',
      'Relatório Orgão SISBR',
      'Relatório de Orgão SISBR',
      'Relatório do Orgão SISBR',
      'Relatório de Órgão SISBR',
      'Relatórios Sisbr',
      'Relatorios Sisbr',
      'Relatorios Orgaos',
    ];
    for (const c of relatorioCompostos) addVariantsFor(c);
  }

  if (lower === 'extrato' || noAccents === 'extrato') {
    const extratoCompostos = [
      'Extrato Recurso',
      'Extratos Recurso',
      'Extrato Recursos',
      'Extratos Recursos',
      'Extrato de Recurso',
      'Extratos de Recurso',
      'Extrato de Recursos',
      'Extratos de Recursos',
      'Extrato do Recurso',
      'Extratos do Recurso',
      'Extrato dos Recursos',
      'Extratos dos Recursos',
      'Extrato da Recurso',
      'Extratos da Recurso',
      'Extrato das Recursos',
      'Extratos das Recursos',
      'Recurso Extrato',
      'Recursos Extrato',
      'Recurso Extratos',
      'Recursos Extratos',
      'Recurso de Extrato',
      'Recursos de Extrato',
      'Recurso do Extrato',
      'Recursos do Extrato',
      'Extrato Bancário',
      'Extrato Bancario',
      'Extratos Bancário',
      'Extratos Bancario',
      'Extrato Bancários',
      'Extratos Bancários',
      'Extrato Bancaria',
      'Extratos Bancaria',
      'Extrato de Conta',
      'Extrato da Conta',
      'Movimento',
      'Movimentações',
      'Movimentacoes',
      'Conta',
      'Contas',
      'Conta Corrente',
      'Contas Correntes',
      'Bancário',
      'Bancario',
      'Bancários',
      'Bancarios',
    ];
    for (const c of extratoCompostos) addVariantsFor(c);
  }

  if (lower === 'relatorio' || noAccents === 'relatorio' || lower === 'relatório') {
    addVariantsFor('Relatório SISBR - Valores Liberados');
    addVariantsFor('Relatório Orgão SISBR');
    addVariantsFor('Relatorio Orgao SISBR');
  }

  return Array.from(variants);
}

function isSpreadsheetFile(name: string): boolean {
  const lower = name.toLowerCase();
  return (
    lower.endsWith('.xlsx') ||
    lower.endsWith('.xls') ||
    lower.endsWith('.csv') ||
    lower.endsWith('.xlsm')
  );
}

function isPdfFile(name: string): boolean {
  return name.trim().toLowerCase().endsWith('.pdf');
}

async function listSpreadsheetFilesRecursive(opts: {
  token: string;
  driveId: string;
  rootFolderId: string;
  maxDepth?: number;
  excludeFolderNames?: string[];
  fileFilter?: (name: string) => boolean;
}): Promise<Array<{ id: string; name: string; lastModifiedDateTime: string; folderPath: string; parentId: string }>> {
  const maxDepth = opts.maxDepth ?? 6;
  const excluded = new Set(
    (opts.excludeFolderNames ?? []).map((n) => n.trim().toLowerCase()),
  );
  const fileFilter = opts.fileFilter ?? isSpreadsheetFile;
  const out: Array<{ id: string; name: string; lastModifiedDateTime: string; folderPath: string; parentId: string }> =
    [];
  const queue: Array<{ id: string; depth: number; path: string }> = [
    { id: opts.rootFolderId, depth: 0, path: '' },
  ];
  const visited = new Set<string>();

  while (queue.length > 0) {
    const current = queue.shift();
    if (!current) break;
    if (visited.has(current.id)) continue;
    visited.add(current.id);

    const children = await listDriveItemChildren(
      opts.token,
      opts.driveId,
      current.id,
    );

    for (const item of children) {
      if (item.file && fileFilter(item.name)) {
        out.push({
          id: item.id,
          name: item.name,
          lastModifiedDateTime: item.lastModifiedDateTime ?? '',
          folderPath: current.path ? current.path : 'base',
          parentId: current.id,
        });
      } else if (item.folder && current.depth < maxDepth) {
        if (excluded.has(item.name.trim().toLowerCase())) continue;
        queue.push({
          id: item.id,
          depth: current.depth + 1,
          path: current.path ? `${current.path}/${item.name}` : item.name,
        });
      }
    }
  }

  return out;
}

function readSheetTable(file: Buffer, profileKind?: string): {
  headers: string[];
  rows: Array<Record<string, unknown>>;
  extractedCompetenciaMmAaaa: string | null;
  topHeaderLines: string[];
} {
  const wb = XLSX.read(file, { type: 'buffer', cellDates: true });
  const extractedCompetenciaMmAaaa: string | null = null;
  const topHeaderLinesAcc: string[] = [];
  function cellHasValue(v: unknown): boolean {
    if (v === null || v === undefined) return false;
    if (typeof v === 'string') return v.trim().length > 0;
    if (typeof v === 'number') return !Number.isNaN(v);
    return true;
  }

  function toHeaderName(v: unknown): string {
    if (v === null || v === undefined) return '';
    const raw =
      typeof v === 'string'
        ? v
        : typeof v === 'number'
          ? String(v)
          : typeof v === 'boolean'
            ? v
              ? 'true'
              : 'false'
            : '';
    if (!raw) return '';
    let cleaned = raw.normalize('NFKC');
    cleaned = cleaned.replace(/[\u0000-\u001F\u007F-\u009F]/g, '');
    cleaned = cleaned.replace(/\s+/g, ' ').trim();
    cleaned = cleaned.replace(/[^\p{L}\p{N} _.\-\/]/gu, '');
    cleaned = cleaned.replace(/\s+/g, ' ').trim();
    if (cleaned.length > 80) cleaned = cleaned.slice(0, 80).trim();
    return cleaned;
  }

  const sheetNames = wb.SheetNames;
  if (!sheetNames || sheetNames.length === 0) return {
    headers: [], rows: [], extractedCompetenciaMmAaaa: null, topHeaderLines: [],
  };

  const MESES_PT_BR_ADFEGO_COMPETENCIA = [
    'janeiro','fevereiro','março','abril','maio','junho','julho','agosto',
    'setembro','outubro','novembro','dezembro',
  ];
  const extractCompetencia = (headerLines: string[]): string | null => {
    const joined = headerLines.join(' | ');
    const patterns = [
      /Relat[oó]rio\s+Financeiro\s+por\s+Provento\s*\/?\s*Desconto\s*[–\-—]\s*([A-Za-zçãõâêîôûáéíóúÀÁÂÃÄÉÊÍÔÕÖÙÚÛÜ\s]+)\s+(\d{4})/i,
      /Compet[eê]ncia\s*[=:：]\s*([A-Za-zçãõâêîôûáéíóúÀÁÂÃÄÉÊÍÔÕÖÙÚÛÜ\s]+)\s+(\d{4})/i,
      /Compet[eê]ncia\s*[=:：]\s*(\d{1,2})[\/\-\.](\d{4})/i,
      /([A-Za-zçãõâêîôûáéíóúÀÁÂÃÄÉÊÍÔÕÖÙÚÛÜ]+)\s+de\s+(\d{4})/i,
    ];
    for (const re of patterns) {
      const m = joined.match(re);
      if (!m) continue;
      if (/^\d{1,2}$/.test(String(m[1]).trim())) {
        const mm = String(m[1]).trim().padStart(2, '0');
        if (/^\d{4}$/.test(String(m[2]).trim())) return `${mm}/${String(m[2]).trim()}`;
      }
      const monthName = String(m[1]).normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().trim();
      const idx = MESES_PT_BR_ADFEGO_COMPETENCIA
        .map((m2) => m2.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase())
        .indexOf(monthName);
      if (idx >= 0 && /^\d{4}$/.test(String(m[2]).trim())) {
        return `${String(idx + 1).padStart(2, '0')}/${String(m[2]).trim()}`;
      }
    }
    return null;
  };

  const parseSheet = (sheet: XLSX.WorkSheet) => {
    const aoa = XLSX.utils.sheet_to_json(sheet, {
      header: 1,
      defval: null,
      blankrows: false,
      raw: false,
      dateNF: 'dd/mm/yyyy',
    }) as unknown[][];

    if (!Array.isArray(aoa) || aoa.length === 0) {
      return {
        headers: [] as string[],
        rows: [] as Array<Record<string, unknown>>,
      };
    }

    // Top header lines: first 15 lines, regardless of content — used for Competência extraction
    const topLines: string[] = [];
    for (let i = 0; i < Math.min(15, aoa.length); i += 1) {
      const r = aoa[i];
      if (!Array.isArray(r)) continue;
      const line = r.map((c) => (c === null || c === undefined ? '' : String(c))).filter(Boolean).join(' ').trim();
      if (line) topLines.push(line);
    }
    topHeaderLinesAcc.push(...topLines);

    // ===== DETECÇÃO LAYOUT TRE-EXTRATO (linha A1 = "EXTRATO CONTA CORRENTE", header real na LINHA 2) =====
    // (H5 confirmada no arquivo modelo TRE-JULHO-2026.xlsx)
    const detectaLinhaHeaderTREExtrato = (): number => {
      if (aoa.length < 2) return -1;
      const linha0 = Array.isArray(aoa[0]) ? aoa[0] : [];
      const cell00 = typeof linha0[0] === 'string' ? linha0[0].trim().toUpperCase() : '';
      if (!/EXTRATO\s*CONTA\s*CORRENTE/.test(cell00)) return -1;
      const linha1 = Array.isArray(aoa[1]) ? aoa[1] : [];
      const headerNomes = linha1
        .map((c) => (typeof c === 'string' ? c.normalize('NFD').replace(/\p{M}/gu, '').toUpperCase().trim() : ''))
        .filter(Boolean);
      const marcadores = ['DATA', 'DOCUMENTO', 'HISTORICO', 'INFORMACOES COMPLEMENTARES', 'VALOR'];
      const achou = marcadores.every((m) => headerNomes.some((h) => h === m || h.includes(m)));
      return achou ? 1 : -1;
    };

    const searchLimit = Math.min(50, aoa.length);
    let headerIndex = detectaLinhaHeaderTREExtrato();
    let bestScore = -1;

    if (headerIndex === -1) {
      for (let i = 0; i < searchLimit; i += 1) {
        const row = aoa[i];
        if (!Array.isArray(row)) continue;
        const nonEmpty = row.filter((v) => cellHasValue(v)).length;
        if (nonEmpty < 2) continue;
        const stringish = row.filter(
          (v) => typeof v === 'string' && v.trim().length > 0,
        ).length;
        const score = nonEmpty * 2 + stringish;
        if (score > bestScore) {
          bestScore = score;
          headerIndex = i;
        }
      }
    }

    if (headerIndex === -1) {
      return {
        headers: [] as string[],
        rows: [] as Array<Record<string, unknown>>,
      };
    }

    const maxCols = Math.max(
      ...(aoa
        .slice(headerIndex)
        .map((r) => (Array.isArray(r) ? r.length : 0)) as number[] | []),
      0,
    );
    const headerRow: unknown[] = Array.isArray(aoa[headerIndex])
      ? aoa[headerIndex]
      : [];

    const headersRaw: string[] = [];
    for (let c = 0; c < maxCols; c += 1) {
      headersRaw.push(toHeaderName(headerRow[c]));
    }

    const headers: string[] = [];
    const counts = new Map<string, number>();
    for (let i = 0; i < headersRaw.length; i += 1) {
      const base = headersRaw[i] || `COL_${i + 1}`;
      const prev = counts.get(base) ?? 0;
      counts.set(base, prev + 1);
      headers.push(prev === 0 ? base : `${base}_${prev}`);
    }

    const rows: Array<Record<string, unknown>> = [];
    for (let r = headerIndex + 1; r < aoa.length; r += 1) {
      const row = aoa[r];
      if (!Array.isArray(row)) continue;
      const obj: Record<string, unknown> = {};
      let nonEmptyCount = 0;
      for (let c = 0; c < headers.length; c += 1) {
        const v: unknown = c < row.length ? row[c] : null;
        obj[headers[c]] = v;
        if (cellHasValue(v)) nonEmptyCount += 1;
      }
      // Linhas com apenas 1 valor significativo (ex: extratos com 1 dado)
      // são aceitas para não descartar dados de extratos pequenos (TRE modelo).
      if (nonEmptyCount >= 1) rows.push(obj);
    }

    return { headers, rows };
  };

  let best = {
    headers: [] as string[],
    rows: [] as Array<Record<string, unknown>>,
  };
  let bestRank = -1;
  for (const name of sheetNames) {
    const sheet = wb.Sheets[name];
    if (!sheet) continue;
    const parsed = parseSheet(sheet);
    const rank = parsed.rows.length * 1000 + parsed.headers.length;
    if (rank > bestRank) {
      bestRank = rank;
      best = parsed;
    }
  }

  const compet = extractCompetencia(topHeaderLinesAcc);

  return {
    headers: best.headers,
    rows: best.rows,
    extractedCompetenciaMmAaaa: compet,
    topHeaderLines: topHeaderLinesAcc,
  };
}

const RELATORIO_PDF_COLUMNS = [
  'EMPRESA',
  'Cliente',
  'Matrícula',
  'CPF',
  'Nome',
  'Atividade',
  'Telefone',
  'Operação',
  'Modalidade',
  'Vencto. Operação',
  'Tx. Juros',
  'Parcela',
  'Vencimento',
  'Valor Operação',
  'Valor Parcela',
  'Valor Juros',
  'Valorização',
  'Rendas Apropriar',
] as const;

function normalizePdfLabel(value: string): string {
  return value
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function parseRelatorioClienteLine(value: string): Record<string, string> {
  const cleaned = value.replace(/\s+/g, ' ').trim();
  const tokens = cleaned.split(' ').filter(Boolean);
  const out: Record<string, string> = {};

  const moneyTokenRe = /^\d{1,3}(?:\.\d{3})*,\d{2}$|^\d+,\d{2}$/;
  const dateRe = /^\d{1,2}\/\d{1,2}\/\d{2,4}$/;
  const txRe = /^\d{1,3},\d{1,4}$/;

  const digitsOnly = (s: string) => s.replace(/\D/g, '');
  const formatCpf = (digits: string) =>
    `${digits.slice(0, 3)}.${digits.slice(3, 6)}.${digits.slice(6, 9)}-${digits.slice(9, 11)}`;

  if (/\btotal\b/i.test(cleaned) && digitsOnly(cleaned).length < 11) return {};

  const takeMoneyPrefix = () => {
    const pref: string[] = [];
    for (let i = 0; i < tokens.length; i += 1) {
      if (!moneyTokenRe.test(tokens[i] ?? '')) break;
      pref.push(tokens[i] as string);
      if (pref.length >= 4) break;
    }
    if (pref.length === 4) {
      out['Valor Parcela'] = pref[0] ?? '';
      out['Valor Juros'] = pref[1] ?? '';
      out['Valorização'] = pref[2] ?? '';
      out['Rendas Apropriar'] = pref[3] ?? '';
      return 4;
    }
    return 0;
  };

  const startIdx = takeMoneyPrefix();

  const isInvalidCpfDigits = (digits: string) =>
    digits.length === 11 && /^(\d)\1{10}$/.test(digits);

  let cpfIndex = -1;
  let cpfSpan = 0;
  let cpfValue = '';
  for (let i = 0; i < tokens.length; i += 1) {
    const d1 = digitsOnly(tokens[i] ?? '');
    if (d1.length === 11 && !isInvalidCpfDigits(d1)) {
      cpfIndex = i;
      cpfSpan = 1;
      cpfValue = formatCpf(d1);
      break;
    }
    const d2 = digitsOnly(tokens[i + 1] ?? '');
    if (d1.length === 9 && d2.length === 2 && !isInvalidCpfDigits(d1 + d2)) {
      cpfIndex = i;
      cpfSpan = 2;
      cpfValue = formatCpf(d1 + d2);
      break;
    }
    const d3 = digitsOnly(tokens[i + 2] ?? '');
    const d4 = digitsOnly(tokens[i + 3] ?? '');
    if (
      d1.length === 3 &&
      d2.length === 3 &&
      d3.length === 3 &&
      d4.length === 2 &&
      !isInvalidCpfDigits(d1 + d2 + d3 + d4)
    ) {
      cpfIndex = i;
      cpfSpan = 4;
      cpfValue = formatCpf(d1 + d2 + d3 + d4);
      break;
    }
  }
  if (cpfIndex !== -1 && cpfValue) out.CPF = cpfValue;

  let telefoneIndex =
    cpfIndex > 0 && /^\d{8,11}$/.test(tokens[cpfIndex - 1] ?? '')
      ? cpfIndex - 1
      : -1;
  if (telefoneIndex === -1 && cpfIndex !== -1) {
    for (let i = cpfIndex - 1; i >= 0; i -= 1) {
      const t = String(tokens[i] ?? '');
      if (/^\d{8,11}$/.test(t)) {
        telefoneIndex = i;
        break;
      }
    }
  }
  if (telefoneIndex !== -1) out.Telefone = tokens[telefoneIndex] ?? '';

  const findClienteTokenInRange = (
    fromIdx: number,
    toIdx: number,
  ): { cliente: string; idx: number; span: number } | null => {
    const start = Math.max(0, fromIdx);
    const end = Math.min(tokens.length - 1, toIdx);
    for (let i = start; i <= end; i += 1) {
      const t0 = String(tokens[i] ?? '');
      if (/^\d{1,10}-\d{1,4}$/.test(t0)) return { cliente: t0, idx: i, span: 1 };
      const t1 = String(tokens[i + 1] ?? '');
      const t2 = String(tokens[i + 2] ?? '');
      if (/^\d{1,10}$/.test(t0) && t1 === '-' && /^\d{1,4}$/.test(t2)) {
        return { cliente: `${t0}-${t2}`, idx: i, span: 3 };
      }
      if (/^\d{1,10}$/.test(t0) && /^-\d{1,4}$/.test(t1)) {
        return { cliente: `${t0}${t1}`, idx: i, span: 2 };
      }
      if (/^\d{1,10}-$/.test(t0) && /^\d{1,4}$/.test(t1)) {
        return { cliente: `${t0}${t1}`, idx: i, span: 2 };
      }
    }
    return null;
  };

  let clienteIdx = -1;
  let clienteSpan = 0;
  const foundCliente =
    cpfIndex !== -1
      ? findClienteTokenInRange(startIdx, Math.max(startIdx, cpfIndex))
      : findClienteTokenInRange(startIdx, tokens.length - 1);
  if (foundCliente) {
    clienteIdx = foundCliente.idx;
    clienteSpan = foundCliente.span;
    out.Cliente = foundCliente.cliente;
  }

  const matriculaIdx =
    clienteIdx !== -1
      ? (() => {
          const start = clienteIdx + Math.max(1, clienteSpan || 1);
          for (let i = start; i < Math.min(tokens.length, start + 6); i += 1) {
            const t = String(tokens[i] ?? '');
            if (/^\d{1,10}$/.test(t)) return i;
            if (cpfIndex !== -1 && i >= cpfIndex) break;
          }
          return -1;
        })()
      : -1;
  if (matriculaIdx !== -1) out['Matrícula'] = tokens[matriculaIdx] ?? '';

  const nomeStart =
    matriculaIdx !== -1
      ? matriculaIdx + 1
      : clienteIdx !== -1
        ? clienteIdx + Math.max(1, clienteSpan || 1)
        : startIdx;
  const nomeEnd =
    telefoneIndex !== -1 ? telefoneIndex : cpfIndex !== -1 ? cpfIndex : -1;
  if (nomeEnd !== -1 && nomeEnd > nomeStart) {
    const nome = tokens.slice(nomeStart, nomeEnd).join(' ').trim();
    if (nome) out.Nome = nome;
  }
  if (cpfIndex !== -1) {
    const segStart =
      clienteIdx !== -1 ? clienteIdx + Math.max(1, clienteSpan || 1) : startIdx;
    const segEnd = telefoneIndex !== -1 ? telefoneIndex : cpfIndex;
    if (segEnd !== -1 && segEnd > segStart) {
      const between = tokens.slice(segStart, segEnd);
      const lettersOnly = between.filter((t) => /[A-Za-zÀ-ÿ]/.test(String(t ?? '')));
      const candidate = lettersOnly.join(' ').trim().replace(/\s+/g, ' ');
      if (candidate && !/\bPESSOA\s+(FISICA|JURIDICA)\b/i.test(candidate)) {
        const existing = typeof out.Nome === 'string' ? out.Nome.trim() : '';
        if (!existing || /\d/.test(existing)) out.Nome = candidate;
      }
    }
  }

  if (cpfIndex !== -1) {
    const after = tokens.slice(cpfIndex + Math.max(1, cpfSpan));

    const opToken = after.find((t) => /^\d{3,}(?:-\d+)?$/.test(t ?? '')) ?? '';
    if (opToken) out['Operação'] = opToken;

    const opIdx = opToken ? after.indexOf(opToken) : -1;
    if (opIdx !== -1) {
      const window = after.slice(opIdx + 1, opIdx + 8);
      const parcelaToken = window.find((t) => /^\d{1,5}$/.test(t ?? '')) ?? '';
      if (parcelaToken) out.Parcela = parcelaToken;

      const modToken =
        window.find((t) => /^[A-Z]{2,10}$/.test(t ?? '')) ?? '';
      if (modToken) out.Modalidade = modToken;
    }

    const dates = after.filter((t) => dateRe.test(t ?? ''));
    if (dates[0]) out['Vencto. Operação'] = dates[0];
    if (dates[1]) out.Vencimento = dates[1];

    const txToken = after.find((t) => txRe.test(t ?? '')) ?? '';
    if (txToken) out['Tx. Juros'] = txToken;

    const ignore = new Set<string>();
    for (const k of [
      'Tx. Juros',
      'Valor Parcela',
      'Valor Juros',
      'Valorização',
      'Rendas Apropriar',
    ] as const) {
      const v = out[k];
      if (v) ignore.add(v);
    }

    const toNumber = (raw: string) => {
      const s = raw.replace(/\./g, '').replace(',', '.');
      const n = Number.parseFloat(s);
      return Number.isFinite(n) ? n : Number.NaN;
    };

    const moneyCandidates = after
      .filter((t) => moneyTokenRe.test(t ?? ''))
      .map((t) => String(t ?? ''))
      .filter((t) => !ignore.has(t));
    if (moneyCandidates.length > 0) {
      let best = moneyCandidates[0] ?? '';
      let bestVal = toNumber(best);
      for (const c of moneyCandidates) {
        const v = toNumber(c);
        if (Number.isFinite(v) && (!Number.isFinite(bestVal) || v > bestVal)) {
          best = c;
          bestVal = v;
        }
      }
      if (best) out['Valor Operação'] = best;
    }
  }

  const activityMatch = /\bPESSOA\s+(FISICA|JURIDICA)\b/i.exec(cleaned);
  if (activityMatch) out.Atividade = `PESSOA ${activityMatch[1]?.toUpperCase() ?? ''}`.trim();

  return out;
}

function parseRelatorioOperacaoLine(value: string): Record<string, string> {
  const cleaned = value.replace(/\s+/g, ' ').trim();
  const tokens = cleaned.split(' ').filter(Boolean);
  const out: Record<string, string> = {};

  if (tokens.length < 3) return out;
  if (/\b\d{3}\.\d{3}\.\d{3}-\d{2}\b/.test(cleaned)) return out;
  const op = String(tokens[0] ?? '');
  if (!/^\d{3,}(?:-\d+)?$/.test(op)) return out;
  out['Operação'] = op;

  const parcela = String(tokens.find((t, idx) => idx > 0 && /^\d{1,5}$/.test(String(t ?? ''))) ?? '');
  if (parcela) out.Parcela = parcela;

  const modalidade =
    String(tokens.find((t) => /^[A-Z]{2,10}$/.test(String(t ?? ''))) ?? '');
  if (modalidade) out.Modalidade = modalidade;

  const dateRe = /^\d{1,2}\/\d{1,2}\/\d{2,4}$/;
  const dates = tokens.filter((t) => dateRe.test(String(t ?? ''))).map((t) => String(t));
  if (dates[0]) out['Vencto. Operação'] = dates[0];
  if (dates[1]) out.Vencimento = dates[1];

  const txRe = /^\d{1,3},\d{1,4}$/;
  const tx = tokens.find((t) => txRe.test(String(t ?? '')));
  if (tx) out['Tx. Juros'] = String(tx);

  const moneyRe = /^\d{1,3}(?:\.\d{3})*,\d{2}$|^\d+,\d{2}$/;
  const money = tokens.filter((t) => moneyRe.test(String(t ?? ''))).map((t) => String(t));
  if (dates.length === 0 && money.length === 0) return {};
  if (money.length >= 4) {
    out['Valor Parcela'] = money[money.length - 4] ?? '';
    out['Valor Juros'] = money[money.length - 3] ?? '';
    out['Valorização'] = money[money.length - 2] ?? '';
    out['Rendas Apropriar'] = money[money.length - 1] ?? '';
  }
  if (money.length >= 5) {
    out['Valor Operação'] = money[money.length - 5] ?? '';
  }
  if (money.length > 0 && !out['Valor Parcela']) {
    out['Valor Parcela'] = money[money.length - 1] ?? '';
  }

  return out;
}

async function readRelatorioPdfTable(
  fileName: string,
  file: Buffer,
): Promise<{
  headers: string[];
  rows: Array<Record<string, unknown>>;
}> {
  const looksLikePdf = (() => {
    const idx = file.indexOf(Buffer.from('%PDF'));
    return idx !== -1 && idx < 1024;
  })();
  if (!isPdfFile(fileName) && !looksLikePdf) {
    throw new Error('Relatório deve ser importado a partir de PDF.');
  }

  const parsed = await extractPdf(file);
  const pages = Array.isArray(parsed.pages) && parsed.pages.length > 0
    ? parsed.pages
    : [{ num: 1, text: String(parsed.text ?? ''), tables: [] as string[][][] }];
  const joinedPagesText = pages.map((p) => String((p as any)?.text ?? '')).join('\n');

  // #region debug-point A:relatorio-pdf-extract
  ;(() => { let u = 'http://127.0.0.1:7777/event', s = 'sisbr-pdf-import'; try { const e = fs.readFileSync('.dbg/sisbr-pdf-import.env', 'utf8'); u = e.match(/DEBUG_SERVER_URL=(.+)/)?.[1] || u; s = e.match(/DEBUG_SESSION_ID=(.+)/)?.[1] || s; } catch { void 0; } const joined = joinedPagesText; const tableCount = pages.reduce((acc, p) => acc + (Array.isArray((p as any)?.tables) ? (p as any).tables.length : 0), 0); const tableRows = pages.reduce((acc, p) => { const t = Array.isArray((p as any)?.tables) ? (p as any).tables : []; const first = Array.isArray(t[0]) ? t[0] : []; return acc + (Array.isArray(first) ? first.length : 0); }, 0); fetch(u, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ sessionId: s, runId: 'pre', hypothesisId: 'A', location: 'import-consignado.ts:readRelatorioPdfTable', msg: '[DEBUG] relatorio_pdf_extracted', data: { fileName, bytes: file.length, pages: pages.length, textChars: joined.length, tables: tableCount, tableRows, head: joined.replace(/\s+/g, ' ').slice(0, 420) }, ts: Date.now() }) }).catch(() => { void 0; }); })();
  // #endregion

  const looksLikeProtectedPdf = (() => {
    const normalized = joinedPagesText.replace(/\s+/g, ' ').trim();
    return (
      /this pdf file is protected/i.test(normalized) ||
      /protected by microsoft office/i.test(normalized) ||
      /you'll need a different reader/i.test(normalized)
    );
  })();

  const competenciaFromDateValue = (value: unknown): string => {
    const d = parseDateValue(value);
    if (!d) return '';
    return `${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getFullYear())}`;
  };

  const isEmpresaContinuationLine = (line: string): boolean => {
    const clean = line.trim().replace(/\s+/g, ' ');
    if (clean.length < 3) return false;
    if (/\d{2}\/\d{2}\/\d{4}/.test(clean)) return false;
    if (/\d{3}\.?\d{3}\.?\d{3}-?\d{2}/.test(clean)) return false;
    if (/^\d+(?:-\d+)?\s+\d+\s+\d+/.test(clean)) return false;
    if (/^(?:CENTRAL|COOPERATIVA|PER[IÍ]ODO|DATA|HORA|ÓRGÃO|ORGÃO|ORGAO)\s*:/i.test(clean)) {
      return false;
    }
    if (/\bEMPRESA\b/i.test(clean)) return false;
    return /[A-Za-zÀ-ÿ]/.test(clean);
  };

  const appendEmpresaContinuations = (
    baseText: string,
    getLine: (idx: number) => string,
    startIdx: number,
    maxLookahead = 2,
  ): string => {
    const parts = [baseText.trim().replace(/\s+/g, ' ')].filter(Boolean);
    for (let step = 1; step <= maxLookahead; step += 1) {
      const next = getLine(startIdx + step);
      if (!isEmpresaContinuationLine(next)) break;
      parts.push(next.trim().replace(/\s+/g, ' '));
    }
    return parts.join(' ').trim().replace(/\s+/g, ' ');
  };

  const normalizeEmpresaCompareText = (value: string): string =>
    value
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toUpperCase()
      .replace(/[^A-Z0-9]+/g, ' ')
      .trim();

  const enrichEmpresaFromFileName = (empresa: string): string => {
    const cleanEmpresa = empresa.trim().replace(/\s+/g, ' ');
    const match = /^(\d{1,8})\s*-\s*(.+)$/.exec(cleanEmpresa);
    if (!match) return cleanEmpresa;

    const fileEmpresa = path
      .basename(fileName, path.extname(fileName))
      .trim()
      .replace(/\s+/g, ' ');
    if (!fileEmpresa) return cleanEmpresa;

    const currentName = (match[2] ?? '').trim();
    if (!currentName) return cleanEmpresa;

    const currentNorm = normalizeEmpresaCompareText(currentName);
    const fileNorm = normalizeEmpresaCompareText(fileEmpresa);
    if (!currentNorm || !fileNorm) return cleanEmpresa;
    if (fileNorm === currentNorm) return `${match[1]} - ${fileEmpresa}`.slice(0, 220).trim();
    if (fileNorm.startsWith(`${currentNorm} `) && fileNorm.length > currentNorm.length) {
      return `${match[1]} - ${fileEmpresa}`.slice(0, 220).trim();
    }
    return cleanEmpresa;
  };

  const applyEmpresaFileNameFallback = (
    rows: Array<Record<string, unknown>>,
  ): Array<Record<string, unknown>> =>
    rows.map((row) => {
      const empresa =
        typeof (row as any).EMPRESA === 'string' ? String((row as any).EMPRESA).trim() : '';
      if (!empresa) return row;
      const enriched = enrichEmpresaFromFileName(empresa);
      if (!enriched || enriched === empresa) return row;
      return { ...row, EMPRESA: enriched };
    });

  const parseRelatorioLiquidacaoRows = (rawPages: string[]) => {
    const content = rawPages.map((t) => String(t ?? '')).join('\n').replace(/\r/g, '\n');
    const lines = content
      .split('\n')
      .map((l) => l.trim().replace(/\s+/g, ' '))
      .filter(Boolean);

    const looksLikeLiquidacao = lines.some((l) =>
      /movimento\s+de\s+liquida[cç][õo]es\s+em\s+folha/i.test(l),
    );
    if (!looksLikeLiquidacao) return [] as Array<Record<string, unknown>>;

    const empresa =
      (() => {
        for (const p of rawPages) {
          const e = pickEmpresaFromPageText(String(p ?? ''));
          if (e) return e;
        }
        return '';
      })() || '';

    const competencia =
      (() => {
        const periodoLine =
          lines.find((l) => /\bper[ií]odo\b\s*:/i.test(l)) ?? '';
        const dates = periodoLine.match(/\d{2}\/\d{2}\/\d{4}/g) ?? [];
        const d0 = dates[0] ?? '';
        const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(d0);
        if (!m) return '';
        const mm = Number(m[2]);
        const yyyy = Number(m[3]);
        if (!Number.isFinite(mm) || !Number.isFinite(yyyy)) return '';
        return `${String(mm).padStart(2, '0')}/${String(yyyy)}`;
      })() || '';

    const out: Array<Record<string, unknown>> = [];
    let currentEmpresa = empresa;
    let currentCliente = '';
    let currentNome = '';
    let currentMatricula = '';
    let currentCpf = '';
    let countCpf = 0;
    let countOp = 0;
    let countOpWithMoney = 0;

    const dateRe = /\d{2}\/\d{2}\/\d{4}/g;
    const moneyRe = /\d{1,3}(?:\.\d{3})*,\d{2}|\d+,\d{2}/g;
    const cpfRe = /\d{3}\.?\d{3}\.?\d{3}-?\d{2}/;

    const normalizeEmpresaInline = (raw: string) => {
      const cleaned = raw.trim().replace(/\s+/g, ' ');
      if (!cleaned) return '';
      const entries: string[] = [];
      const codeRe = /\d{1,8}\s*-\s*/g;
      const codeMatches = Array.from(cleaned.matchAll(codeRe));
      for (let i = 0; i < codeMatches.length; i += 1) {
        const m = codeMatches[i];
        const full = m[0] ?? '';
        const code = full.replace(/\D/g, '');
        const start = (m.index ?? 0) + full.length;
        const end = i + 1 < codeMatches.length ? (codeMatches[i + 1]?.index ?? cleaned.length) : cleaned.length;
        const name = cleaned.slice(start, end).trim().replace(/\s+/g, ' ');
        if (!code || !name) continue;
        if (!/[A-Za-zÀ-ÿ]/.test(name)) continue;
        if (/^\d/.test(name)) continue;
        entries.push(`${code} - ${name}`.slice(0, 220).trim());
      }
      if (entries.length > 0) return entries[entries.length - 1] ?? '';
      const m0 = /^(\d{1,8})\s*-\s*(.+)$/.exec(cleaned);
      if (!m0) return '';
      const code = (m0[1] ?? '').trim();
      const name = (m0[2] ?? '').trim().replace(/\s+/g, ' ');
      if (!code || !name) return '';
      if (name.length < 6) return '';
      if (!/[A-Za-zÀ-ÿ]/.test(name)) return '';
      if (/^\d/.test(name)) return '';
      return `${code} - ${name}`.slice(0, 220).trim();
    };

    const empresaFromLineWithLookahead = (idx: number) => {
      const line = lines[idx] ?? '';
      const up = line.toUpperCase();
      if (up.includes('TOTAL') || up.includes('MOVIMENTO DE LIQUIDA')) return '';

      const explicit = /\bEMPRESA\b\s*(?::|\s)\s*(.+)$/i.exec(line)?.[1] ?? '';
      const explicitWithContinuation = appendEmpresaContinuations(
        explicit,
        (lineIdx) => lines[lineIdx] ?? '',
        idx,
      );
      const c1 = normalizeEmpresaInline(explicitWithContinuation);
      if (c1) return c1;

      const c2 = normalizeEmpresaInline(line);
      if (c2) {
        return appendEmpresaContinuations(
          c2,
          (lineIdx) => lines[lineIdx] ?? '',
          idx,
        ).slice(0, 220).trim();
      }

      return '';
    };

    for (let i = 0; i < lines.length; i += 1) {
      const line = lines[i] ?? '';
      const emp = empresaFromLineWithLookahead(i);
      if (emp) {
        currentEmpresa = emp;
        continue;
      }
      if (cpfRe.test(line)) {
        countCpf += 1;
        const tokens = line.split(' ');
        const cpfMatch = line.match(cpfRe);
        if (cpfMatch) {
          currentCpf = cpfMatch[0];
          const cpfIndex = tokens.findIndex((t) => t.includes(currentCpf));
          if (cpfIndex > 0) {
            currentMatricula = tokens[cpfIndex - 1];
            currentCliente = tokens[0];
            currentNome = tokens.slice(1, cpfIndex - 1).join(' ');
          }
        }
        continue;
      }

      if (/^\d+(?:-\d+)?\s+\d+\s+\d+/.test(line)) {
        countOp += 1;
        const dates = Array.from(line.matchAll(dateRe)).map((m) => m[0]);
        const moneys = Array.from(line.matchAll(moneyRe)).map((m) => m[0]);
        const tokens = line.split(' ');

        const operacao = tokens[0];
        const parcela = tokens[2];
        const venctoOperacao = dates[0] ?? '';
        const vencimento = dates[1] ?? dates[0] ?? '';

        if (moneys.length >= 6) {
          countOpWithMoney += 1;
          const valorOperacao = moneys[0];
          const valorParcela = moneys[5];
          const rowCompetencia = competenciaFromDateValue(vencimento) || competencia;

          out.push({
            ...(currentEmpresa ? { EMPRESA: currentEmpresa } : {}),
            ...(rowCompetencia ? { Copetencia: rowCompetencia } : {}),
            Cliente: currentCliente,
            Matrícula: currentMatricula,
            CPF: currentCpf,
            Nome: currentNome,
            Operação: operacao,
            Parcela: parcela,
            ...(venctoOperacao ? { 'Vencto. Operação': venctoOperacao } : {}),
            Vencimento: vencimento,
            'Valor Operação': valorOperacao,
            'Valor Parcela': valorParcela,
          });
        }
      }
    }
    if (process.env.RELATORIO_PDF_DEBUG === '1') {
      process.stdout.write(
        `Relatório PDF debug: liquidacao_parser | cop=${competencia || '-'} | cpf=${countCpf} | op=${countOp} | op_money=${countOpWithMoney} | out=${out.length}\n`,
      );
    }
    return out;
  };

  const parseOperacoesVencidasRows = (rawPages: string[]) => {
    const content = rawPages.map((t) => String(t ?? '')).join('\n').replace(/\r/g, '\n');
    const lines = content
      .split('\n')
      .map((l) => l.trim().replace(/\s+/g, ' '))
      .filter(Boolean);

    const looksLikeOperacoesVencidas =
      /opera[cç][aã]o/i.test(fileName) && /vencid/i.test(fileName) ||
      lines.some((l) => /total\s+receber/i.test(l)) ||
      lines.some((l) => /\bvalor\s+nominal\b/i.test(l));
    if (!looksLikeOperacoesVencidas) return [] as Array<Record<string, unknown>>;

    const isHeaderLine = (l: string) => {
      const up = l.toUpperCase();
      if (up.includes('CLIENTE') && up.includes('CPF') && up.includes('NOME')) return true;
      if (up.includes('ATIVIDADE') && up.includes('TELEFONE')) return true;
      if (up.includes('TOTAL RECEBER') || up.includes('VALOR NOMINAL')) return true;
      if (up.includes('OPERA') && up.includes('MODALIDADE') && up.includes('VENC')) return true;
      return false;
    };

    const cpfRe = /\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/;
    const rowStartRe =
      /^\d+\s+\d+\s+\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/;

    const rowBuffers: string[] = [];
    let cur = '';
    for (const l0 of lines) {
      const l = l0.trim();
      if (!l) continue;
      if (/^total\s+/i.test(l)) {
        if (cur) rowBuffers.push(cur);
        cur = '';
        continue;
      }
      if (isHeaderLine(l)) continue;
      if (rowStartRe.test(l)) {
        if (cur) rowBuffers.push(cur);
        cur = l;
        continue;
      }
      if (cur) {
        cur = `${cur} ${l}`.trim().replace(/\s+/g, ' ');
        continue;
      }
    }
    if (cur) rowBuffers.push(cur);

    const dateRe = /\b\d{2}\/\d{2}\/\d{4}\b/g;
    const moneyRe =
      /\b\d{1,3}(?:\.\d{3})*,\d{2}\b|\b\d+,\d{2}\b|\b\d+\.\d{2}\b/g;
    const opRe = /\b\d{4,}-\d+\b|\b\d{6,}\b/g;
    const phoneRe = /\(\d{2}\)\s*\d{4,5}-\d{4}/;

    const empresaFromText = (rawText: string): string => {
      const trimmed = rawText.trim().replace(/\s+/g, ' ');
      if (!trimmed) return '';
      const tre =
        /\bTRIBUNAL\s+REGIONAL\s+ELEITORAL\b/i.test(trimmed) ? 'TRIBUNAL REGIONAL ELEITORAL' : '';
      if (tre) return tre;
      const emp = /\bEMP-\d+\b/i.exec(trimmed)?.[0] ?? '';
      return emp ? emp.toUpperCase() : '';
    };

    const empresa =
      (() => {
        for (const p of rawPages) {
          const e = empresaFromText(String(p ?? ''));
          if (e) return e;
        }
        return '';
      })() || '';

    const out: Array<Record<string, unknown>> = [];
    for (const rowText of rowBuffers) {
      if (!cpfRe.test(rowText)) continue;

      const m0 = /^(\d+)\s+(\d+)\s+(\d{3}\.?\d{3}\.?\d{3}-?\d{2})\s+(.+)$/.exec(
        rowText,
      );
      if (!m0) continue;
      const cliente = (m0[1] ?? '').trim();
      const matricula = (m0[2] ?? '').trim();
      const cpf = (m0[3] ?? '').trim();
      const tail = (m0[4] ?? '').trim();

      const ops = Array.from(tail.matchAll(opRe)).map((x) => x[0]).filter(Boolean);
      const operacao = ops[0] ?? '';

      const tailTokens = tail.split(' ').filter(Boolean);
      let modalidade = '';
      for (const t of tailTokens) {
        const cleaned = t.trim();
        const mMod = /^(?:\d{1,6}-)?([A-Z]{3,6})$/.exec(cleaned.toUpperCase());
        if (!mMod) continue;
        const code = (mMod[1] ?? '').trim();
        if (!code) continue;
        if (['CPF', 'CLIENTE', 'NOME', 'DIAS', 'IOF'].includes(code)) continue;
        modalidade = code;
        break;
      }

      const dates = Array.from(tail.matchAll(dateRe)).map((x) => x[0]).filter(Boolean);
      const vencimento = dates[0] ?? '';

      const money = Array.from(tail.matchAll(moneyRe)).map((x) => x[0]).filter(Boolean);
      const valorOperacao = money[0] ?? '';
      const valorParcela = money.length > 0 ? money[money.length - 1] : '';

      const telefone = phoneRe.exec(tail)?.[0] ?? '';

      const nome = (() => {
        if (!modalidade) return tail;
        const idx = tailTokens.findIndex((t) =>
          /^(?:\d{1,6}-)?[A-Z]{3,6}$/i.test(t),
        );
        if (idx <= 0) return tail;
        const before = tailTokens.slice(0, idx).join(' ');
        const stopIdx = before.search(opRe);
        const namePart = (stopIdx >= 0 ? before.slice(0, stopIdx) : before)
          .trim()
          .replace(/\s+/g, ' ');
        return namePart || before;
      })();

      if (!operacao || !modalidade || !vencimento || !valorParcela) continue;

      out.push({
        ...(empresa ? { EMPRESA: empresa } : {}),
        Cliente: cliente,
        Matrícula: matricula,
        CPF: cpf,
        Nome: nome,
        ...(telefone ? { Telefone: telefone } : {}),
        Operação: operacao,
        Modalidade: modalidade,
        'Vencto. Operação': vencimento,
        Parcela: '',
        Vencimento: vencimento,
        ...(valorOperacao ? { 'Valor Operação': valorOperacao } : {}),
        ...(valorParcela ? { 'Valor Parcela': valorParcela } : {}),
      });
    }

    return out;
  };

  const pickEmpresaFromPageText = (rawText: string): string => {
    const content = rawText.replace(/\r/g, '\n');
    const empresaExplicit = (() => {
      const header = content.split('\n').slice(0, 450).join('\n');
      const nextLabelRe =
        /(?:CENTRAL|COOPERATIVA|PER[IÍ]ODO|DATA|HORA|ÓRGÃO|ORGÃO|ORGAO)\s*:/i;
      const bestByCode = (raw: string) => {
        const nextLabelIdx = raw.search(nextLabelRe);
        const cutRaw = (nextLabelIdx === -1 ? raw : raw.slice(0, nextLabelIdx))
          .trim()
          .replace(/\s+/g, ' ');
        if (!cutRaw) return '';

        const entries: Array<{ code: string; value: string }> = [];
        const codeRe = /\d{1,8}\s*-\s*/g;
        const codeMatches = Array.from(cutRaw.matchAll(codeRe));
        for (let i = 0; i < codeMatches.length; i += 1) {
          const m = codeMatches[i];
          const full = m[0] ?? '';
          const code = full.replace(/\D/g, '');
          const start = (m.index ?? 0) + full.length;
          const end = i + 1 < codeMatches.length ? (codeMatches[i + 1]?.index ?? cutRaw.length) : cutRaw.length;
          const name = cutRaw.slice(start, end).trim().replace(/\s+/g, ' ');
          if (!code || !name) continue;
          entries.push({ code, value: `${code} - ${name}`.slice(0, 220).trim() });
        }

        if (entries.length > 0) {
          return entries[entries.length - 1]?.value ?? cutRaw;
        }

        return cutRaw;
      };

      const explicitSegmentMatch =
        /\bEMPRESA\b\s*:\s*([\s\S]{0,320}?)(?=\bÓRGÃO\b\s*:|\bORGÃO\b\s*:|\bORGAO\b\s*:)/i.exec(
          header,
        );
      const explicitSegment = explicitSegmentMatch?.[1]
        ?.trim()
        .replace(/\s+/g, ' ');
      if (explicitSegment) {
        const picked = bestByCode(explicitSegment);
        if (picked) return picked;
      }

      const re = /\bEMPRESA\b\s*(?::|\s)\s*/gi;
      const candidates: string[] = [];
      let m: RegExpExecArray | null;
      while ((m = re.exec(header))) {
        const before = header.slice(Math.max(0, m.index - 12), m.index).toLowerCase();
        if (before.includes('total')) continue;
        const start = m.index + m[0].length;
        const tail = header.slice(start, start + 300);
        const tailLines = tail
          .split('\n')
          .map((line) => line.trim().replace(/\s+/g, ' '))
          .filter(Boolean);
        const mergedParts: string[] = [];
        for (let i = 0; i < tailLines.length; i += 1) {
          const line = tailLines[i] ?? '';
          if (i === 0) {
            mergedParts.push(line);
            continue;
          }
          if (!isEmpresaContinuationLine(line)) break;
          mergedParts.push(line);
          if (mergedParts.length >= 3) break;
        }
        const merged = mergedParts.join(' ').trim().replace(/\s+/g, ' ');
        if (merged) candidates.push(merged);
      }
      if (candidates.length === 0) return '';

      for (const c of candidates) {
        const v = bestByCode(c);
        if (v) return v;
      }
      return bestByCode(candidates[0] ?? '');
    })();
    if (empresaExplicit) return empresaExplicit;

    const matches: string[] = [];
    const re =
      /\b(?:EMPRESA|CONV[ÊE]NIO|CONVENIO|ORG[ÃA]O|ORGAO|EMPREGADOR|ENTIDADE)\s*(?::|\s)\s*(.+?)(?=\n|$)/gi;
    let m: RegExpExecArray | null;
    while ((m = re.exec(content))) {
      const v = (m[1] ?? '').trim().replace(/\s+/g, ' ');
      if (v) matches.push(v);
    }
    const generic: string[] = [];
    const genericRe =
      /\b(\d{1,8})\s*-\s*([A-ZÇÁÉÍÓÚÂÊÔÃÕ][^\n]{8,}?)(?=\n|$)/g;
    while ((m = genericRe.exec(content))) {
      const code = (m[1] ?? '').trim();
      const name = (m[2] ?? '').trim().replace(/\s+/g, ' ');
      if (!code || !name) continue;
      const v = `${code} - ${name}`.slice(0, 220).trim();
      generic.push(v);
    }

    const candidates = matches.length > 0 ? matches : generic;
    if (candidates.length === 0) return '';
    const preferred = candidates.filter((v) => /^\d+\s*-\s*/.test(v));
    const list = preferred.length > 0 ? preferred : candidates;
    return list[list.length - 1] ?? '';
  };

  const fixedHeaderKeys: Array<{
    key: (typeof RELATORIO_PDF_COLUMNS)[number];
    patterns: RegExp[];
  }> = [
    { key: 'Cliente', patterns: [/\bcliente\b/i] },
    { key: 'Matrícula', patterns: [/\bmatr[ií]cula\b/i] },
    { key: 'CPF', patterns: [/\bcpf\b/i] },
    { key: 'Nome', patterns: [/\bnome\b/i] },
    {
      key: 'Operação',
      patterns: [/\bopera[cç][aã]o\b/i, /\boperacao\b/i],
    },
    { key: 'Modalidade', patterns: [/\bmodalidade\b/i, /\bmod\.\b/i] },
    {
      key: 'Vencto. Operação',
      patterns: [
        /\bvencto\.?\s*opera[cç][aã]o\b/i,
        /\bvencto\.?\s*operacao\b/i,
        /\bvencto\b/i,
      ],
    },
    { key: 'Tx. Juros', patterns: [/\btx\.?\s*juros\b/i, /\btaxa\s*juros\b/i] },
    { key: 'Parcela', patterns: [/\bparcela\b/i] },
    { key: 'Vencimento', patterns: [/\bvencimento\b/i] },
    {
      key: 'Valor Operação',
      patterns: [
        /\bvalor\s*opera[cç][aã]o\b/i,
        /\bvalor\s*operacao\b/i,
        /\bvlr\.?\s*opera[cç][aã]o\b/i,
        /\bvlr\.?\s*operacao\b/i,
      ],
    },
    { key: 'Valor Parcela', patterns: [/\bvalor\s*parcela\b/i, /\bvlr\.?\s*parcela\b/i] },
    { key: 'Valor Juros', patterns: [/\bvalor\s*juros\b/i, /\bvlr\.?\s*juros\b/i] },
    {
      key: 'Valorização',
      patterns: [/\bvaloriz[aç][aã]o\b/i, /\bvalorizacao\b/i],
    },
    {
      key: 'Rendas Apropriar',
      patterns: [/\brendas?\s*apropriar\b/i, /\brendas?\s*aprop/i],
    },
  ];

  const cpfRe = /\b\d{3}\.\d{3}\.\d{3}-\d{2}\b/;

  const headerKeyByNormalized = new Map<string, (typeof RELATORIO_PDF_COLUMNS)[number]>([
    ['cliente', 'Cliente'],
    ['matricula', 'Matrícula'],
    ['cpf', 'CPF'],
    ['nome', 'Nome'],
    ['atividade', 'Atividade'],
    ['telefone', 'Telefone'],
    ['operacao', 'Operação'],
    ['modalidade', 'Modalidade'],
    ['vencto operacao', 'Vencto. Operação'],
    ['vencto operacao', 'Vencto. Operação'],
    ['tx juros', 'Tx. Juros'],
    ['taxa juros', 'Tx. Juros'],
    ['parcela', 'Parcela'],
    ['vencimento', 'Vencimento'],
    ['valor operacao', 'Valor Operação'],
    ['valor da operacao', 'Valor Operação'],
    ['valor parcela', 'Valor Parcela'],
    ['valor juros', 'Valor Juros'],
    ['valorizacao', 'Valorização'],
    ['rendas apropriar', 'Rendas Apropriar'],
  ]);

  const expectedHeaderSignals = new Set([
    'cliente',
    'cpf',
    'matricula',
    'nome',
    'operacao',
    'modalidade',
  ]);
 
  const allRows: Array<Record<string, unknown>> = [];

  const variantsByKey: Array<{ key: string; variants: string[] }> = [
    { key: 'EMPRESA', variants: ['EMPRESA'] },
    { key: 'Cliente', variants: ['Cliente'] },
    { key: 'Matrícula', variants: ['Matrícula', 'Matricula'] },
    { key: 'CPF', variants: ['CPF'] },
    { key: 'Nome', variants: ['Nome'] },
    { key: 'Atividade', variants: ['Atividade'] },
    { key: 'Telefone', variants: ['Telefone'] },
    { key: 'Operação', variants: ['Operação', 'Operacao'] },
    { key: 'Modalidade', variants: ['Modalidade'] },
    {
      key: 'Vencto. Operação',
      variants: [
        'Vencto. Operação',
        'Vencto. Operacao',
        'Vencto Operação',
        'Vencto Operacao',
      ],
    },
    { key: 'Tx. Juros', variants: ['Tx. Juros', 'Tx Juros', 'Taxa Juros'] },
    { key: 'Parcela', variants: ['Parcela'] },
    { key: 'Vencimento', variants: ['Vencimento'] },
    {
      key: 'Valor Operação',
      variants: [
        'Valor Operação',
        'Valor Operacao',
        'Valor da Operação',
        'Valor da Operacao',
      ],
    },
    { key: 'Valor Parcela', variants: ['Valor Parcela'] },
    { key: 'Valor Juros', variants: ['Valor Juros'] },
    { key: 'Valorização', variants: ['Valorização', 'Valorizacao'] },
    { key: 'Rendas Apropriar', variants: ['Rendas Apropriar'] },
  ];

  const labelToKey = new Map<string, string>();
  const allLabelVariants: string[] = [];
  for (const entry of variantsByKey) {
    for (const v of entry.variants) {
      labelToKey.set(normalizePdfLabel(v), entry.key);
      allLabelVariants.push(v);
    }
  }

  const labelRegex = new RegExp(
    `(${allLabelVariants
      .sort((a, b) => b.length - a.length)
      .map(escapeRegExp)
      .join('|')})\\s*(?:[\\.·•_\\-]{1,40}\\s*)?:\\s*`,
    'gi',
  );

  let fallbackCarryBase: Record<string, unknown> | null = null;
  let fallbackCarryHasOperation = false;

  for (const page of pages) {
    const rowsBeforePage = allRows.length;
    const rawText = String(page.text ?? '').replace(/\r/g, '\n');
    const text = rawText.replace(/[ \t]+/g, ' ');
    const empresa = pickEmpresaFromPageText(rawText);
    const rawLines = rawText
      .split('\n')
      .map((l) => l.replace(/\s+$/g, ''))
      .filter((l) => l.trim().length > 0);

    const hasClienteLabel =
      /(?:^|\n)\s*Cliente\s*(?:[\\.·•_\\-]{1,40}\s*)?:/i.test(rawText);
    let fallbackFixedRows: Array<Record<string, unknown>> | null = null;
    if (hasClienteLabel) {
      fallbackCarryBase = null;
      fallbackCarryHasOperation = false;
    }

    const debugMatchRaw = process.env.RELATORIO_PDF_DEBUG_MATCH ?? '';
    if (process.env.RELATORIO_PDF_DEBUG === '1' && debugMatchRaw.trim().length > 0) {
      const needles = debugMatchRaw
        .split('|')
        .map((s) => s.trim())
        .filter(Boolean);
      const foundNeedles = needles.filter((n) =>
        rawText.toLowerCase().includes(n.toLowerCase()),
      );
      if (foundNeedles.length > 0) {
        process.stdout.write(
          `Relatório PDF debug: match page=${page.num} EMPRESA=${empresa || '-'} needles=${foundNeedles.join(' | ')}\n`,
        );
        let shown = 0;
        for (const line of rawLines) {
          const hit = foundNeedles.some((n) =>
            line.toLowerCase().includes(n.toLowerCase()),
          );
          if (!hit) continue;
          process.stdout.write(`Relatório PDF debug: match_line=${line}\n`);
          shown += 1;
          if (shown >= 12) break;
        }
      }
    }

    if (!hasClienteLabel) {
      const fixedRows: Array<Record<string, unknown>> = [];
      let base: Record<string, unknown> | null = fallbackCarryBase;
      let baseHasOperation = fallbackCarryHasOperation;
      for (const line of rawLines) {
        if (/\btotal\b/i.test(line)) continue;
        const opFields = base ? parseRelatorioOperacaoLine(line) : {};
        if (base && typeof (opFields as any)['Operação'] === 'string') {
          fixedRows.push({ ...base, ...opFields });
          baseHasOperation = true;
          continue;
        }

        if (base) {
          const cpf = normalizeCpfValue((base as any).CPF);
          const nome = typeof (base as any).Nome === 'string' ? String((base as any).Nome).trim() : '';
          const normalized = normalizePdfLabel(line);
          const looksLikeActivity = /\bpessoa\s+(fisica|juridica)\b/i.test(line);
          const looksLikeHeaderish =
            /(cliente|matricula|cpf|nome|atividade|telefone|operacao|modalidade|vencimento|valor|juros|parcela|empresa|cooperativa|central)/i.test(
              normalized,
            );
          const looksLikeNameLine =
            cpf &&
            normalized.length >= 4 &&
            /[a-z]/i.test(line) &&
            !looksLikeActivity &&
            !looksLikeHeaderish &&
            !/\d/.test(line);
          if (looksLikeNameLine) {
            (base as any).Nome = (nome ? `${nome} ${line}` : line).replace(/\s+/g, ' ').trim();
            continue;
          }
          if (cpf && !nome && looksLikeActivity) {
            const m = /\bPESSOA\s+(FISICA|JURIDICA)\b/i.exec(line);
            if (m) (base as any).Atividade = `PESSOA ${String(m[1] ?? '').toUpperCase()}`.trim();
            continue;
          }
        }

        const parsedLine = parseRelatorioClienteLine(line);
        const parsedCliente = (parsedLine.Cliente ?? '').trim();
        const parsedCpf = typeof parsedLine.CPF === 'string' ? parsedLine.CPF.trim() : '';
        if (!/^\d+-\d+$/.test(parsedCliente) || !parsedCpf) continue;

        if (base && !baseHasOperation) fixedRows.push(base);

        const nextBase: Record<string, unknown> = empresa ? { EMPRESA: empresa } : {};
        nextBase.Cliente = parsedCliente;
        for (const col of RELATORIO_PDF_COLUMNS) {
          if (col === 'EMPRESA' || col === 'Cliente') continue;
          const v = (parsedLine as any)[col];
          if (typeof v === 'string' && v.trim().length > 0) (nextBase as any)[col] = v;
        }
        base = nextBase;
        baseHasOperation =
          typeof (base as any)['Operação'] === 'string' ||
          typeof (base as any)['Valor Operação'] === 'string' ||
          typeof (base as any)['Valor Parcela'] === 'string';

        if (baseHasOperation) {
          fixedRows.push(base);
          base = null;
          baseHasOperation = false;
        }
      }
      fallbackCarryBase = base;
      fallbackCarryHasOperation = baseHasOperation;
      if (fixedRows.length > 0) fallbackFixedRows = fixedRows;
    }

    if (!hasClienteLabel && fallbackFixedRows) {
      for (const r of fallbackFixedRows) allRows.push(r);
      continue;
    }

    const tables = Array.isArray(page.tables) ? page.tables : [];
    if (tables.length > 0) {
      type TableCandidate = {
        table: string[][];
        headerIndex: number;
        score: number;
      };
      let best: TableCandidate | null = null;
      for (const table of tables) {
        for (let i = 0; i < Math.min(table.length, 6); i += 1) {
          const row = table[i] ?? [];
          if (row.length < 3) continue;
          const normalizedCells = row
            .map((c) => normalizePdfLabel(String(c ?? '')))
            .filter(Boolean);
          const hitCount = normalizedCells.filter((c) =>
            expectedHeaderSignals.has(c),
          ).length;
          const score = hitCount * 100 + normalizedCells.length;
          if (score <= 0) continue;
          if (!best || score > best.score) best = { table, headerIndex: i, score };
        }
      }

      if (best) {
        const headerRow = best.table[best.headerIndex] ?? [];
        const headerKeys: Array<(typeof RELATORIO_PDF_COLUMNS)[number] | null> =
          headerRow.map((cell) => {
            const normalized = normalizePdfLabel(String(cell ?? ''));
            if (!normalized) return null;
            return headerKeyByNormalized.get(normalized) ?? null;
          });

        for (let r = best.headerIndex + 1; r < best.table.length; r += 1) {
          const row = best.table[r] ?? [];
          const joined = row.join(' ').toLowerCase();
          if (/\btotal\b/.test(joined)) continue;
          const obj: Record<string, unknown> = empresa ? { EMPRESA: empresa } : {};
          let filled = 0;
          for (let c = 0; c < headerKeys.length; c += 1) {
            const key = headerKeys[c];
            if (!key) continue;
            const value = String(row[c] ?? '').trim();
            if (!value) continue;
            obj[key] = key === 'CPF' ? normalizeCpfValue(value) : value;
            filled += 1;
          }
          const cpf = typeof (obj as any).CPF === 'string' ? normalizeCpfValue((obj as any).CPF) : '';
          const nome =
            typeof (obj as any).Nome === 'string' ? String((obj as any).Nome).trim() : '';
          if (cpf && !nome) {
            const rowLine = row.join(' ').replace(/\s+/g, ' ').trim();
            const parsedLine = parseRelatorioClienteLine(rowLine);
            const parsedNome = typeof parsedLine.Nome === 'string' ? parsedLine.Nome.trim() : '';
            if (parsedNome) (obj as any).Nome = parsedNome;
            if (!(obj as any).Cliente && typeof parsedLine.Cliente === 'string' && parsedLine.Cliente.trim()) {
              (obj as any).Cliente = parsedLine.Cliente.trim();
            }
            if (!(obj as any)['Matrícula'] && typeof (parsedLine as any)['Matrícula'] === 'string' && String((parsedLine as any)['Matrícula']).trim()) {
              (obj as any)['Matrícula'] = String((parsedLine as any)['Matrícula']).trim();
            }
          }
          if (filled > 0) allRows.push(obj);
        }
      }
    }

    type Token = { key: string; valueStart: number; labelStart: number };
    const tokens: Token[] = [];
    let m: RegExpExecArray | null;
    labelRegex.lastIndex = 0;
    while ((m = labelRegex.exec(text))) {
      const label = m[1] ?? '';
      if (m.index > 0 && !/\s/.test(text[m.index - 1] ?? '')) continue;
      const key = labelToKey.get(normalizePdfLabel(label));
      if (!key) continue;
      const before = text.slice(Math.max(0, m.index - 12), m.index);
      if (/total\s*$/i.test(before)) continue;
      tokens.push({ key, valueStart: labelRegex.lastIndex, labelStart: m.index });
    }

    const pageRows: Array<Record<string, unknown>> = [];
    let current: Record<string, unknown> = empresa ? { EMPRESA: empresa } : {};
    const flush = () => {
      const keyCount = Object.keys(current).length;
      const minKeys = empresa ? 2 : 1;
      if (keyCount >= minKeys) pageRows.push(current);
    };

    for (let i = 0; i < tokens.length; i += 1) {
      const t = tokens[i];
      const next = i + 1 < tokens.length ? tokens[i + 1] : null;
      const rawValue = text.slice(t.valueStart, next?.labelStart ?? text.length);
      const value = rawValue.replace(/\s+/g, ' ').trim();

      if (t.key === 'EMPRESA') continue;
      if (t.key === 'Cliente') {
        if (Object.keys(current).length > 0) flush();
        current = empresa ? { EMPRESA: empresa } : {};
      }
      if (value) current[t.key] = value;
    }
    flush();

    const validPageRows: Array<Record<string, unknown>> = [];
    for (const r of pageRows) {
      const clienteVal =
        typeof (r as any).Cliente === 'string' ? String((r as any).Cliente) : '';
      const onlyCliente =
        clienteVal.trim().length > 0 &&
        Object.keys(r).every((k) => k === 'EMPRESA' || k === 'Cliente');

      if (onlyCliente) {
        const parsedLine = parseRelatorioClienteLine(clienteVal);
        const parsedCliente = (parsedLine.Cliente ?? '').trim();
        if (!/^\d+-\d+$/.test(parsedCliente)) continue;
        (r as any).Cliente = parsedCliente;
        for (const [k, v] of Object.entries(parsedLine)) {
          if (k === 'Cliente') continue;
          (r as any)[k] = v;
        }
        validPageRows.push(r);
        continue;
      }

      const normalizedCliente = clienteVal.trim();
      if (normalizedCliente && !/^\d+-\d+$/.test(normalizedCliente)) continue;
      validPageRows.push(r);
    }

    for (const r of validPageRows) allRows.push(r);

    if (fallbackFixedRows && allRows.length === rowsBeforePage) {
      for (const r of fallbackFixedRows) allRows.push(r);
    }
  }

  if (allRows.length === 0) {
    const altLiquidacao = parseRelatorioLiquidacaoRows(pages.map((p) => String(p.text ?? '')));
    if (altLiquidacao.length > 0) {
      return {
        headers: [...RELATORIO_PDF_COLUMNS, 'Copetencia'],
        rows: applyEmpresaFileNameFallback(altLiquidacao),
      };
    }

    const alt = parseOperacoesVencidasRows(pages.map((p) => String(p.text ?? '')));
    if (alt.length > 0) {
      return { headers: [...RELATORIO_PDF_COLUMNS], rows: applyEmpresaFileNameFallback(alt) };
    }

    const joined = joinedPagesText;
      // #region debug-point B:relatorio-pdf-empty
      ;(() => { let u = 'http://127.0.0.1:7777/event', s = 'sisbr-pdf-import'; try { const e = fs.readFileSync('.dbg/sisbr-pdf-import.env', 'utf8'); u = e.match(/DEBUG_SERVER_URL=(.+)/)?.[1] || u; s = e.match(/DEBUG_SESSION_ID=(.+)/)?.[1] || s; } catch { void 0; } const normalizedLines = joined.replace(/\r/g, '\n').split('\n').map((l) => l.trim().replace(/\s+/g, ' ')).filter(Boolean); const hasTotals = /total\s*(cliente|empresa|cooperativa|central|geral)\s*:/i.test(joined) || /\bEMP-\d+\b/i.test(joined) || /\btotal\s+receber\b/i.test(joined); const cpfMatches = joined.match(/\d{3}\.?\d{3}\.?\d{3}-?\d{2}/g) ?? []; const liquidacaoMarker = normalizedLines.some((l) => /movimento\s+de\s+liquida[cç][õo]es\s+em\s+folha/i.test(l)); const empresaLines = normalizedLines.filter((l) => /\bEMPRESA\b/i.test(l)).slice(0, 12); const dashUnique = Array.from(new Set(normalizedLines.filter((l) => /^\d{1,8}\s*-\s*/.test(l)).map((l) => l.slice(0, 220).trim()))).slice(0, 20); fetch(u, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ sessionId: s, runId: 'pre', hypothesisId: 'B', location: 'import-consignado.ts:readRelatorioPdfTable', msg: '[DEBUG] relatorio_pdf_no_rows', data: { fileName, lines: normalizedLines.length, head: normalizedLines.slice(0, 40).join(' || ').slice(0, 1200), hasTotals, cpfMatches: cpfMatches.length, liquidacaoMarker, empresaHits: empresaLines, codigoUnique: dashUnique }, ts: Date.now() }) }).catch(() => { void 0; }); })();
      // #endregion
    if (process.env.RELATORIO_PDF_DEBUG === '1') {
      const normalizedLines = joined
        .replace(/\r/g, '\n')
        .split('\n')
        .map((l) => l.trim().replace(/\s+/g, ' '))
        .filter(Boolean);
      const head = normalizedLines.slice(0, 40);
      const cpfRe = /\d{3}\.?\d{3}\.?\d{3}-?\d{2}/g;
      const empresaHits = normalizedLines.filter((l) => /\bEMPRESA\b/i.test(l)).slice(0, 20);
      const dashHits = normalizedLines.filter((l) => /\b\d{1,8}\s*-\s*/.test(l)).slice(0, 20);
      const dashUnique = Array.from(
        new Set(
          normalizedLines
            .filter((l) => /^\d{1,8}\s*-\s*/.test(l))
            .map((l) => l.slice(0, 220).trim()),
        ),
      ).slice(0, 40);
      const cpfMatches = joined.match(cpfRe) ?? [];
      process.stdout.write(
        `Relatório PDF debug: ${fileName} | registros=0 | pages=${pages.length} | linhas=${normalizedLines.length} | cpf_matches=${cpfMatches.length} | empresa_linhas=${empresaHits.length} | codigo_linhas=${dashHits.length}\n`,
      );
      process.stdout.write(`Relatório PDF debug: head=${head.join(' || ')}\n`);
      if (empresaHits.length > 0) {
        process.stdout.write(`Relatório PDF debug: empresa_hits=${empresaHits.join(' | ')}\n`);
      }
      if (dashHits.length > 0) {
        process.stdout.write(`Relatório PDF debug: codigo_hits=${dashHits.join(' | ')}\n`);
      }
      if (dashUnique.length > 0) {
        process.stdout.write(`Relatório PDF debug: codigo_unique=${dashUnique.join(' | ')}\n`);
      }
    }
    const hasTotals =
      /total\s*(cliente|empresa|cooperativa|central|geral)\s*:/i.test(joined) ||
      /\bEMP-\d+\b/i.test(joined) ||
      /\btotal\s+receber\b/i.test(joined);
    const cpfMatches = joined.match(/\d{3}\.?\d{3}\.?\d{3}-?\d{2}/g) ?? [];
    if (looksLikeProtectedPdf) {
      throw new Error(
        'Relatório em PDF protegido pela Microsoft. Salve ou exporte o arquivo sem proteção antes de importar.',
      );
    }
    if (hasTotals && cpfMatches.length === 0) return { headers: [...RELATORIO_PDF_COLUMNS], rows: [] };
    throw new Error(
      'Relatório em PDF: não foi possível extrair registros (layout do arquivo pode ter mudado).',
    );
  }

  const cpfToNome = new Map<string, string>();
  for (const r of allRows) {
    const cpf = normalizeCpfValue((r as any).CPF);
    if (!cpf) continue;
    const nome = typeof (r as any).Nome === 'string' ? String((r as any).Nome).trim() : '';
    if (nome) cpfToNome.set(cpf, nome);
  }
  if (cpfToNome.size > 0) {
    for (const r of allRows) {
      const cpf = normalizeCpfValue((r as any).CPF);
      if (!cpf) continue;
      (r as any).CPF = cpf;
      const nome = typeof (r as any).Nome === 'string' ? String((r as any).Nome).trim() : '';
      if (!nome) {
        const best = cpfToNome.get(cpf) ?? '';
        if (best) (r as any).Nome = best;
      }
    }
  }

  if (process.env.RELATORIO_PDF_DEBUG === '1') {
    const empresas = new Set<string>();
    for (const r of allRows) {
      const e = typeof (r as any).EMPRESA === 'string' ? String((r as any).EMPRESA).trim() : '';
      if (e) empresas.add(e);
    }
    const empresasPagina = new Set<string>();
    for (const p of pages) {
      const e = pickEmpresaFromPageText(String(p.text ?? ''));
      if (e) empresasPagina.add(e);
    }
    const sampleRow = allRows[0] ?? {};
    const filledCols = RELATORIO_PDF_COLUMNS.filter(
      (c) =>
        typeof (sampleRow as any)[c] === 'string' &&
        String((sampleRow as any)[c]).trim().length > 0,
    );
    process.stdout.write(
      `Relatório PDF debug: ${fileName} | registros=${allRows.length} | empresas_linhas=${empresas.size} | empresas_paginas=${empresasPagina.size}\n`,
    );
    const previewPages = pages.slice(0, 5).map((p) => {
      const e = pickEmpresaFromPageText(String(p.text ?? '')) || '-';
      return `p${p.num}=${e}`;
    });
    process.stdout.write(
      `Relatório PDF debug: empresas_preview=${previewPages.join(' | ')}\n`,
    );
    const tablesPreview = pages.slice(0, 5).map((p) => {
      const t0 = Array.isArray((p as any).tables) ? (p as any).tables[0] : null;
      const rows = Array.isArray(t0) ? t0.length : 0;
      const cols = rows > 0 && Array.isArray(t0[0]) ? t0[0].length : 0;
      const count = Array.isArray((p as any).tables) ? (p as any).tables.length : 0;
      return `p${p.num}:tables=${count}:${rows}x${cols}`;
    });
    process.stdout.write(
      `Relatório PDF debug: tables_preview=${tablesPreview.join(' | ')}\n`,
    );
    const empSnippets = pages.slice(0, 3).map((p) => {
      const t = String(p.text ?? '').replace(/\r/g, '\n');
      const idx = t.toUpperCase().indexOf('EMPRESA');
      if (idx === -1) return `p${p.num}=sem_EMPRESA`;
      const from = Math.max(0, idx - 60);
      const to = Math.min(t.length, idx + 240);
      const snip = t.slice(from, to).replace(/\s+/g, ' ').trim();
      return `p${p.num}=${snip}`;
    });
    process.stdout.write(
      `Relatório PDF debug: empresa_snippet=${empSnippets.join(' || ')}\n`,
    );
    process.stdout.write(
      `Relatório PDF debug: colunas_preenchidas_amostra=${filledCols.join(' | ') || '-'}\n`,
    );
    const debugMatchRaw = process.env.RELATORIO_PDF_DEBUG_MATCH ?? '';
    const needles = debugMatchRaw
      .split('|')
      .map((s) => s.trim())
      .filter(Boolean);
    if (needles.length > 0) {
      const matchingRows = allRows.filter((r) => {
        const hay = JSON.stringify(r).toLowerCase();
        return needles.some((n) => hay.includes(n.toLowerCase()));
      });
      for (const r of matchingRows.slice(0, 10)) {
        process.stdout.write(`Relatório PDF debug: parsed_row=${JSON.stringify(r)}\n`);
      }
    }
  }

  return { headers: [...RELATORIO_PDF_COLUMNS], rows: applyEmpresaFileNameFallback(allRows) };
}

async function readExtratoPdfTable(
  fileName: string,
  file: Buffer,
): Promise<{
  headers: string[];
  rows: Array<Record<string, unknown>>;
}> {
  const looksLikePdf = (() => {
    const idx = file.indexOf(Buffer.from('%PDF'));
    return idx !== -1 && idx < 1024;
  })();
  if (!isPdfFile(fileName) && !looksLikePdf) {
    throw new Error('Extrato deve ser importado a partir de PDF.');
  }

  const parsed = await extractPdf(file);
  const pages = Array.isArray(parsed.pages) && parsed.pages.length > 0
    ? parsed.pages
    : [{ num: 1, text: String(parsed.text ?? ''), tables: [] as string[][][] }];

  const normalizeCompetencia = (mm: number, yyyy: number) => {
    if (!Number.isFinite(mm) || !Number.isFinite(yyyy)) return '';
    if (mm < 1 || mm > 12) return '';
    const yy = String(yyyy % 100).padStart(2, '0');
    return `${String(mm).padStart(2, '0')}/${yy}`;
  };

  const normalizeString = (v: unknown) =>
    String(v ?? '')
      .replace(/\r/g, '\n')
      .replace(/[\u0000-\u001F\u007F]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

  const normalizeCpfValue = (v: unknown) => {
    const d = String(v ?? '').replace(/\D/g, '');
    return d.length === 11 ? `${d.slice(0, 3)}.${d.slice(3, 6)}.${d.slice(6, 9)}-${d.slice(9)}` : d;
  };

  const fileNameNorm = normalizeString(fileName)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

  const pickCompetenciaFromText = (content: string): string => {
    const t = content
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '');

    const periodRe = /(periodo|competencia)\s*:?\s*(\d{2})\s*[\/\-]\s*(\d{4})/i;
    const m = periodRe.exec(t);
    if (m) {
      const mm = Number(m[2]);
      const yyyy = Number(m[3]);
      const out = normalizeCompetencia(mm, yyyy);
      if (out) return out;
    }

    const anyMmYyyy = /\b(\d{2})\s*[\/\-]\s*(\d{4})\b/.exec(t);
    if (anyMmYyyy) {
      const mm = Number(anyMmYyyy[1]);
      const yyyy = Number(anyMmYyyy[2]);
      const out = normalizeCompetencia(mm, yyyy);
      if (out) return out;
    }

    const yearMatch = /\b(20\d{2})\b/.exec(fileNameNorm);
    const yyyy = yearMatch ? Number(yearMatch[1]) : NaN;
    const monthNames: Array<[string, number]> = [
      ['janeiro', 1],
      ['fevereiro', 2],
      ['marco', 3],
      ['abril', 4],
      ['maio', 5],
      ['junho', 6],
      ['julho', 7],
      ['agosto', 8],
      ['setembro', 9],
      ['outubro', 10],
      ['novembro', 11],
      ['dezembro', 12],
    ];
    for (const [name, mm] of monthNames) {
      if (fileNameNorm.includes(name) && Number.isFinite(yyyy)) {
        const out = normalizeCompetencia(mm, yyyy);
        if (out) return out;
      }
    }

    return '';
  };

  const competencia =
    pickCompetenciaFromText(pages.map((p) => String(p.text ?? '')).join('\n')) ||
    pickCompetenciaFromText(String(parsed.text ?? ''));

  const cpfTokenRe = /\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b|\b\d{11}\b/;
  const cpfTokenReGlobal = new RegExp(cpfTokenRe.source, 'g');
  const moneyRe =
    /\b\d{1,3}(?:\.\d{3})*,\d{2}\b|\b\d+,\d{2}\b|\b\d+\.\d{2}\b/g;

  const normalizeCpf = (v: string) => {
    const digits = v.replace(/\D/g, '');
    return digits.length === 11 ? digits : '';
  };

  const parseLine = (lineRaw: string): { nome: string; cpf: string; valor: string } | null => {
    const line = normalizeString(lineRaw);
    if (!line) return null;
    const up = line.toUpperCase();
    if (up.includes('TOTAL')) return null;
    if (/CPF/i.test(line) && /VLR|PARC|VALOR/i.test(line) && !cpfTokenRe.test(line))
      return null;

    const cpfMatches = Array.from(line.matchAll(cpfTokenReGlobal)).map((m) => m[0]);
    if (cpfMatches.length !== 1) return null;
    const cpfHit = cpfMatches[0] ?? '';
    const cpf = normalizeCpf(cpfHit);
    if (!cpf) return null;

    const moneys = Array.from(line.matchAll(moneyRe)).map((m) => m[0]);
    if (moneys.length === 0) return null;
    if (moneys.length > 4) return null;
    const valor = moneys[moneys.length - 1] ?? '';
    if (!valor) return null;

    const cpfIdx = line.indexOf(cpfHit);
    const nomeRaw = cpfIdx > 0 ? line.slice(0, cpfIdx).trim() : '';
    const nome = nomeRaw
      .replace(/^SERVIDOR\s*:?\s*/i, '')
      .replace(/^NOME\s*:?\s*/i, '')
      .replace(/^\d+\s*-\s*/i, '')
      .replace(/^\d+\s+/, '')
      .replace(/^-+\s*/, '')
      .replace(/\s*-\s*$/, '')
      .trim();

    return { nome, cpf, valor };
  };

  const extractMoneyToken = (s: string): string | null => {
    const matches = s.match(moneyRe);
    if (!matches || matches.length === 0) return null;
    const raw = matches[matches.length - 1] ?? '';
    if (!raw) return null;
    if (raw.includes(',')) return raw;
    return raw.replace('.', ',');
  };

  const parseServidorCell = (cellRaw: string): { nome: string; cpf: string } | null => {
    const cell = normalizeString(cellRaw);
    if (!cell) return null;
    const cpfMatch = cpfTokenRe.exec(cell);
    if (!cpfMatch) return null;
    const cpf = normalizeCpf(cpfMatch[0]);
    if (!cpf) return null;
    const cpfIdx = cell.indexOf(cpfMatch[0]);
    const nomeRaw = cpfIdx > 0 ? cell.slice(0, cpfIdx).trim() : '';
    const nome = nomeRaw
      .replace(/^SERVIDOR\s*:?\s*/i, '')
      .replace(/^NOME\s*:?\s*/i, '')
      .replace(/^\d+\s*-\s*/i, '')
      .replace(/^\d+\s+/, '')
      .replace(/^-+\s*/, '')
      .replace(/\s*-\s*$/, '')
      .trim();
    return { nome, cpf };
  };

  const rowsFromTables: Array<Record<string, unknown>> = [];
  const bestNameByCpf = new Map<string, string>();
  for (const p of pages) {
    const tables = Array.isArray(p.tables) ? p.tables : [];
    for (const t of tables) {
      if (!Array.isArray(t) || t.length === 0) continue;

      let headerIndex = -1;
      let idxServidor = -1;
      let idxVlrParc = -1;

      for (let i = 0; i < t.length; i += 1) {
        const row = t[i];
        if (!Array.isArray(row) || row.length === 0) continue;
        const cells = row.map((c) => normalizeString(c));
        const joined = cells.join(' ').toUpperCase();
        const looksLikeHeader =
          joined.includes('SERVIDOR') &&
          (joined.includes('VLR') || joined.includes('VALOR')) &&
          joined.includes('PARC');
        if (!looksLikeHeader) continue;

        headerIndex = i;
        idxServidor = cells.findIndex((c) => c.toUpperCase().includes('SERVIDOR'));
        idxVlrParc = cells.findIndex((c) => {
          const up = c.toUpperCase();
          return (up.includes('VLR') || up.includes('VALOR')) && up.includes('PARC');
        });
        break;
      }

      if (headerIndex < 0) continue;

      for (let i = headerIndex + 1; i < t.length; i += 1) {
        const row = t[i];
        if (!Array.isArray(row) || row.length === 0) continue;
        const cells = row.map((c) => normalizeString(c));

        const servidorCell = cells[idxServidor] ?? '';
        const servidor = parseServidorCell(servidorCell) ?? parseServidorCell(cells.join(' '));
        if (!servidor) continue;

        const valorCell = cells[idxVlrParc] ?? '';
        const valor =
          extractMoneyToken(valorCell) ??
          (() => {
            const joined = cells.join(' ');
            return extractMoneyToken(joined);
          })();
        if (!valor) continue;

        const nome = servidor.nome || '';
        const prev = bestNameByCpf.get(servidor.cpf) ?? '';
        if (nome && (!prev || nome.length > prev.length)) {
          bestNameByCpf.set(servidor.cpf, nome);
        }

        rowsFromTables.push({
          ...(nome ? { NOME: nome } : { NOME: '' }),
          NMR_CPF: servidor.cpf,
          VALOR: valor,
          Competencia: competencia || '',
        });
      }
    }
  }

  const candidateLines: string[] = [];
  for (const p of pages) {
    const tables = Array.isArray(p.tables) ? p.tables : [];
    for (const t of tables) {
      if (!Array.isArray(t)) continue;
      for (const row of t) {
        if (!Array.isArray(row)) continue;
        const joined = row.map((c) => normalizeString(c)).filter(Boolean).join(' ');
        if (joined) candidateLines.push(joined);
      }
    }
    const textLines = String(p.text ?? '')
      .replace(/\r/g, '\n')
      .split('\n')
      .map((l) => l.trim())
      .filter(Boolean);
    for (const l of textLines) candidateLines.push(l);
  }

  const rows: Array<Record<string, unknown>> = [];
  let carry = '';
  for (const raw of candidateLines) {
    const rawLine = normalizeString(raw);
    if (!rawLine) continue;
    const line = carry ? `${carry} ${rawLine}`.trim() : rawLine;
    const parsedLine = parseLine(line);
    if (!parsedLine) {
      const up = line.toUpperCase();
      const isHeaderish =
        (up.includes('SERVIDOR') && up.includes('CPF')) ||
        up.includes('CORRESP') ||
        up.includes('SERVIÇO') ||
        up.includes('VLR') ||
        up.includes('PARC') ||
        up.includes('COMPET') ||
        up.includes('PERÍODO') ||
        up.includes('PERIODO');
      if (isHeaderish) {
        carry = '';
        continue;
      }

      if (cpfTokenRe.test(line) && !moneyRe.test(line)) {
        carry = line;
        continue;
      }

      const looksLikeNameFragment =
        /[A-Za-zÀ-ÿ]/.test(rawLine) &&
        !cpfTokenRe.test(rawLine) &&
        !moneyRe.test(rawLine) &&
        rawLine.length >= 6 &&
        rawLine.length <= 140;
      if (looksLikeNameFragment) {
        carry = rawLine;
        continue;
      }
      continue;
    }
    carry = '';
    rows.push({
      ...(parsedLine.nome ? { NOME: parsedLine.nome } : { NOME: '' }),
      NMR_CPF: parsedLine.cpf,
      VALOR: parsedLine.valor,
      Competencia: competencia || '',
    });
  }

  const looksBadName = (nomeRaw: string) => {
    const nome = nomeRaw.trim();
    if (!nome) return true;
    if (nome.length < 8) return true;
    const up = nome.toUpperCase();
    if (
      up.includes('LIQUIDADA') ||
      up.includes('EM ANDAMENTO') ||
      up.includes('FOLHA') ||
      up.includes('CONTRATO') ||
      up.includes('PARCELA') ||
      up.includes('SERVIÇO') ||
      up.includes('SERVICO')
    ) return true;
    const words = nome.split(/\s+/g).filter(Boolean);
    if (words.length <= 1) return true;
    return false;
  };

  const merged: Array<Record<string, unknown>> = [];
  const seen = new Set<string>();
  const addRow = (r: Record<string, unknown>) => {
    const cpf = String((r as any).NMR_CPF ?? '').replace(/\D/g, '');
    const valor = String((r as any).VALOR ?? '').trim();
    const comp = String((r as any).Competencia ?? '').trim();
    const key = `${cpf}|${valor}|${comp}`;
    if (!cpf || !valor) return;
    if (seen.has(key)) return;
    seen.add(key);
    merged.push(r);
  };

  for (const r of rowsFromTables) addRow(r);
  for (const r of rows) {
    const cpf = String((r as any).NMR_CPF ?? '').replace(/\D/g, '');
    const best = cpf ? (bestNameByCpf.get(cpf) ?? '') : '';
    const nome = String((r as any).NOME ?? '');
    const bad = looksBadName(nome);
    if (cpf && bestNameByCpf.has(cpf)) {
      const words = nome.trim().split(/\s+/g).filter(Boolean);
      if (bad || words.length < 3 || (best && nome.trim().length < best.length * 0.7)) {
        continue;
      }
    }
    if (best && bad) {
      (r as any).NOME = best;
    }
    addRow(r);
  }

  const headers = ['NOME', 'NMR_CPF', 'VALOR', 'Competencia'];
  return { headers, rows: merged };
}

export async function readRelatorioTable(fileName: string, file: Buffer): Promise<{
  headers: string[];
  rows: Array<Record<string, unknown>>;
}> {
  const looksLikePdf = (() => {
    const idx = file.indexOf(Buffer.from('%PDF'));
    return idx !== -1 && idx < 1024;
  })();
  if (!isPdfFile(fileName) && !looksLikePdf) return readSheetTable(file);

  const pdfParse = await getPdfParse();
  const parsed = await pdfParse(file);
  const text = String(parsed.text ?? '');
  // Preserva TABs para separar Atividade (opcional) e CPF nas linhas cliente/operacao.
  // Só colapsa ESPAÇOS consecutivos (2+) em 1 único espaço, mantendo \t intacto.
  const lines = text
    .split(/\r?\n/g)
    .map((l) => l.trim().replace(/[ ]{2,}/g, ' '))
    .filter(Boolean)
    .filter((l) => !(/opera[cç][aã]o/i.test(l) && /parcela|valor/i.test(l)));

  // ============================================================================
  // SISBR PDF: PARSER POSICIONAL (REGEX FORTE PRIORIDADE MÁXIMA)
  // Padrão oficial SISBR "Relatório de Parcelas a Vencer" 25/08/2026 (TRE-GO, TRT, etc)
  // ESTRUTURA LINHAS:
  //   TOPO: EMPRESA:\n1004 - XXX\n45039 - TRIBUNAL REGIONAL... ÓRGÃO: → extrai EMPRESA
  //         PERÍODO: 01/08/2026 31/08/2026 → Copetencia = MM/YYYY
  //         "Relatório de Parcelas a Vencer DD/MM/YYYY" → vencimentoDefault (operações de 10 campos)
  //   LINHA CLIENTE: <Cliente HIFEN-DV> <Matrícula(digitos)> <Nome> <Tel(digitos)> [\t <Atividade> ] \t <CPF>
  //                  Atividade é OPCIONAL (ex: TRE-GO cliente 2/3 não tem)
  //   LINHA OPERAÇÃO (11 campos, COM Vencimento): <Op> <Parcela> <Mod> <VenctoOp> <TxJ> <Venc> <VOp> <VParc> <VJur> <Val> <Rend>
  //   LINHA OPERAÇÃO (10 campos, SEM Vencimento = vencimentoDefault): <Op> <Parcela> <Mod> <VenctoOp> <TxJ> <VOp> <VParc> <VJur> <Val> <Rend>
  //   PULAR: Total Cliente/Empresa/Cooperativa/Central/Geral, headers repetidos, TOTAIS, EMP-158, -- X of Y --
  // ============================================================================
  try {
    const sisbrHeaderRe = /(?:SISBR\s+2\.0|Relatório\s+de\s+Parcelas\s+a\s+Vencer)/;
    if (sisbrHeaderRe.test(text)) {
      // ---------------- EMPRESA ----------------
      let empresaHeader = '';
      const orgaoRe = /(?:^|\n)\s*([^\n]{0,200}?\d{3,6}\s*-\s*[^\n]{0,200}?)\s*ÓRGÃO\s*:/s;
      const mOrgao = text.match(orgaoRe);
      if (mOrgao && mOrgao[1]) {
        empresaHeader = mOrgao[1].replace(/\s+/g, ' ').trim();
      }
      if (!empresaHeader) {
        const mEmp = text.match(/EMPRESA\s*:\s*\n([^\n]+)\s*\n([^\n]+)/s);
        if (mEmp && mEmp[2]) empresaHeader = mEmp[2].replace(/\s+/g, ' ').trim();
      }
      if (!empresaHeader) {
        empresaHeader = fileName.replace(/\.pdf$/i, '').trim();
      }
      // ---------------- COPETENCIA (MM/YYYY) ----------------
      let copetencia = '';
      const perRe = /PERÍODO\s*:\s*(\d{2}\/\d{2}\/\d{4})\s+(\d{2}\/\d{2}\/\d{4})/;
      const mPer = text.match(perRe);
      if (mPer && mPer[2]) {
        const parts = mPer[2].split('/'); if (parts.length === 3) copetencia = `${parts[1]}/${parts[2]}`;
      } else if (mPer && mPer[1]) {
        const parts = mPer[1].split('/'); if (parts.length === 3) copetencia = `${parts[1]}/${parts[2]}`;
      }
      // ---------------- VENCIMENTO DEFAULT (para opRe10 = 10 campos sem Vencimento) ----------------
      // Extrai de "Relatório de Parcelas a Vencer 25/08/2026"
      let vencimentoDefault = '';
      const venDefRe = /Relatório\s+de\s+Parcelas\s+a\s+Vencer\s+(\d{2}\/\d{2}\/\d{4})/;
      const mVenDef = text.match(venDefRe);
      if (mVenDef && mVenDef[1]) vencimentoDefault = mVenDef[1].trim();
      // Fallback: data final do PERÍODO se não achar no título
      if (!vencimentoDefault && mPer && mPer[2]) {
        const parts = mPer[2].split('/');
        if (parts.length === 3) vencimentoDefault = `25/${parts[1]}/${parts[2]}`;
      }
      // ---------------- REGEX LINHAS ----------------
      // Op 11 campos (COM Vencimento explícito na 6ª posição):
      const opRe11 = /^(\d{1,6}-\d{1,2})\s+(\d{1,4})\s+([A-Z]{3,6})\s+(\d{2}\/\d{2}\/\d{4})\s+([\d.,]+)\s+(\d{2}\/\d{2}\/\d{4})\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s*$/;
      // Op 10 campos (SEM Vencimento → usa vencimentoDefault): Vencimento é omitido da 6ª posição
      const opRe10 = /^(\d{1,6}-\d{1,2})\s+(\d{1,4})\s+([A-Z]{3,6})\s+(\d{2}\/\d{2}\/\d{4})\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s*$/;
      // Cliente COM Atividade (PESSOA FISICA / PESSOA JURIDICA / OUTROS) entre TABS:
      const cliReComAtiv = /^(\d{1,6}-\d{1,2})\s+(\d+)\s+([A-ZÀ-ÜÇÃÕÔÂÊÉÍÓÚ][A-ZÀ-ÜÇÃÕÔÂÊÉÍÓÚ\s']+?)\s+(\d+)\s*\t\s*([A-ZÀ-ÜÇÃÕÔÂÊÉÍÓÚ ]{3,50}?)\s*\t\s*(\d{3}\.\d{3}\.\d{3}-\d{2})\s*$/i;
      // Cliente SEM Atividade (só TAB para CPF, sem campo intermediário):
      const cliReSemAtiv = /^(\d{1,6}-\d{1,2})\s+(\d+)\s+([A-ZÀ-ÜÇÃÕÔÂÊÉÍÓÚ][A-ZÀ-ÜÇÃÕÔÂÊÉÍÓÚ\s']+?)\s+(\d+)\s*\t\s*(\d{3}\.\d{3}\.\d{3}-\d{2})\s*$/i;
      const skipRe = /^\s*(Total\s+(Cliente|Empresa|Cooperativa|Central|Geral)\s*:|CENTRAL\s*:|EMPRESA\s*:|ÓRGÃO\s*:|COOPERATIVA\s*:|Hora\s+Emissão\s*:|Data\s+Emissão\s*:|Data\s+Processamento\s*:|PERÍODO\s*:|SISBR\s+2\.0|Relatório\s+de\s+Parcelas|Matrícula\s*$|Valor\s+Juros\s+Valorização|Atividade\s*$|Valor\s+Operação\s*$|Telefone\s*$|Tx\.\s*Juros|Vencto\.\s*Operação|Operação\s*$|Cliente\s*$|Parcela\s+Valor\s+Parcela|Nome\s*$|Rendas\s+Apropriar|Vencimento\s*$|CPF\s*$|\*\s+parcela\s+em\s+carência|EMP-158\s+Pag\.\s*:|--\s+\d+\s+of\s+\d+\s+--|Total\s+Geral\s*:)/i;
      type C = { Cliente: string; Matrícula: string; Nome: string; Telefone: string; Atividade: string; CPF: string };
      let currentClient: C | null = null;
      const resultRows: Array<Record<string, unknown>> = [];
      const resultHeaders = [
        'EMPRESA', 'Cliente', 'Matrícula', 'CPF', 'Nome', 'Atividade', 'Telefone',
        'Operação', 'Modalidade', 'Vencto. Operação', 'Tx. Juros', 'Parcela', 'Vencimento',
        'Valor Operação', 'Valor Parcela', 'Valor Juros', 'Valorização', 'Rendas Apropriar', 'Copetencia',
      ];
      for (const l of lines) {
        const ll = l.trim();
        if (!ll) continue;
        if (skipRe.test(ll)) continue;
        // ----- Tenta linha cliente (primeiro com atividade, depois sem) -----
        let cM = ll.match(cliReComAtiv);
        if (cM) {
          currentClient = {
            Cliente: cM[1],
            Matrícula: cM[2],
            Nome: cM[3].replace(/\s+/g, ' ').trim(),
            Telefone: cM[4],
            Atividade: (cM[5] || '').toUpperCase().replace(/\s+/g, ' ').trim(),
            CPF: cM[6],
          };
          continue;
        }
        cM = ll.match(cliReSemAtiv);
        if (cM) {
          currentClient = {
            Cliente: cM[1],
            Matrícula: cM[2],
            Nome: cM[3].replace(/\s+/g, ' ').trim(),
            Telefone: cM[4],
            Atividade: '',
            CPF: cM[5],
          };
          continue;
        }
        // ----- Tenta linha operação 11 campos (Vencimento explícito) -----
        const oM11 = ll.match(opRe11);
        if (oM11) {
          resultRows.push({
            EMPRESA: empresaHeader,
            Cliente: currentClient?.Cliente ?? '',
            Matrícula: currentClient?.Matrícula ?? '',
            CPF: currentClient?.CPF ?? '',
            Nome: currentClient?.Nome ?? '',
            Atividade: currentClient?.Atividade ?? '',
            Telefone: currentClient?.Telefone ?? '',
            Operação: oM11[1],
            Modalidade: oM11[3],
            'Vencto. Operação': oM11[4],
            'Tx. Juros': oM11[5],
            Parcela: oM11[2],
            Vencimento: oM11[6],
            'Valor Operação': oM11[7],
            'Valor Parcela': oM11[8],
            'Valor Juros': oM11[9],
            Valorização: oM11[10],
            'Rendas Apropriar': oM11[11],
            Copetencia: copetencia,
          });
          continue;
        }
        // ----- Tenta linha operação 10 campos (Vencimento = vencimentoDefault) -----
        const oM10 = ll.match(opRe10);
        if (oM10) {
          resultRows.push({
            EMPRESA: empresaHeader,
            Cliente: currentClient?.Cliente ?? '',
            Matrícula: currentClient?.Matrícula ?? '',
            CPF: currentClient?.CPF ?? '',
            Nome: currentClient?.Nome ?? '',
            Atividade: currentClient?.Atividade ?? '',
            Telefone: currentClient?.Telefone ?? '',
            Operação: oM10[1],
            Modalidade: oM10[3],
            'Vencto. Operação': oM10[4],
            'Tx. Juros': oM10[5],
            Parcela: oM10[2],
            Vencimento: vencimentoDefault,
            'Valor Operação': oM10[6],
            'Valor Parcela': oM10[7],
            'Valor Juros': oM10[8],
            Valorização: oM10[9],
            'Rendas Apropriar': oM10[10],
            Copetencia: copetencia,
          });
          continue;
        }
      }
      if (resultRows.length > 0) return { headers: resultHeaders, rows: resultRows };
    }
  } catch (_eSisbrPos) {
    try { safeLogError('readRelatorioTable SISBR positional regex parser', _eSisbrPos); } catch { /* ignore */ }
  }

  const headers = ['Operação', 'Vencimento', 'Parcela', 'Valor Operação'];
  let rows: Array<Record<string, unknown>> = [];
  const moneyRe =
    /R\$\s*\d{1,3}(?:\.\d{3})*,\d{2}|R\$\s*\d+,\d{2}|R\$\s*\d+\.\d{2}|\b\d{1,3}(?:\.\d{3})*,\d{2}\b|\b\d+,\d{2}\b|\b\d+\.\d{2}\b/g;
  const dateRe =
    /\b(\d{1,2}\/\d{1,2}\/\d{2,4})\b|\b(\d{1,2}[-_\. ](?:janeiro|fevereiro|março|marco|abril|maio|junho|julho|agosto|setembro|outubro|novembro|dezembro|jan|fev|mar|abr|mai|jun|jul|ago|set|out|nov|dez|january|february|march|april|june|july|august|september|october|november|december)[-_\. ]\d{2,4})\b/i;
  const opRe = /\b\d{2,6}-\d{1,2}\b|\b\d{3,}\b/;

  const extractMoney = (s: string): string | null => {
    const matches = s.match(moneyRe);
    if (!matches || matches.length === 0) return null;
    const raw = matches[matches.length - 1].replace(/R\$\s*/i, '').trim();
    if (!raw) return null;
    if (raw.includes(',')) return raw;
    return raw.replace('.', ',');
  };

  const extractAllMoneys = (s: string): string[] => {
    const matches = s.match(moneyRe);
    if (!matches || matches.length === 0) return [];
    return matches.map((m) => {
      const raw = m.replace(/R\$\s*/i, '').trim();
      if (!raw) return '';
      if (raw.includes(',')) return raw;
      return raw.replace('.', ',');
    }).filter(Boolean);
  };

  const extractOperation = (s: string): string | null => {
    const m = s.match(opRe);
    return m ? m[0] : null;
  };

  const extractDate = (s: string): string | null => {
    const m = dateRe.exec(s);
    if (!m) return null;
    return m[1] ?? m[2] ?? null;
  };

  const extractFallbackFromRawText = (
    allTextLines: string[],
  ): Array<Record<string, unknown>> => {
    const out: Array<Record<string, unknown>> = [];
    let buf = '';
    const pushFromBuf = (raw: string) => {
      const line = raw.trim().replace(/\s+/g, ' ');
      const moneys = extractAllMoneys(line);
      if (moneys.length === 0) return;
      const op = extractOperation(line);
      const venc = extractDate(line);
      const mainValue = moneys[moneys.length - 1];
      if (!mainValue) return;
      out.push({
        Operação: op ?? '',
        Vencimento: venc ?? '',
        Parcela: mainValue,
        'Valor Operação': mainValue,
      });
    };
    for (const l of allTextLines) {
      if (/^\s*$/.test(l)) { if (buf.trim().length) { pushFromBuf(buf); buf = ''; } continue; }
      const hasMoney = /\d,\d{2}|\d\.\d{2}|R\$/i.test(l);
      if (hasMoney && buf.trim().length === 0 && extractAllMoneys(l).length >= 1) {
        pushFromBuf(l);
        buf = '';
      } else if (hasMoney || /\d{3,}/.test(l) || /\/\d{2,4}/.test(l)) {
        buf = `${buf} ${l}`.trim();
      } else {
        if (buf.trim().length) { pushFromBuf(buf); buf = ''; }
      }
    }
    if (buf.trim().length) pushFromBuf(buf);
    return out;
  };

  let carry = '';
  for (const raw of lines) {
    const line = `${carry} ${raw}`.trim();
    const op = extractOperation(line);
    const value = extractMoney(line);
    const venc = extractDate(line);

    if (!value && (op || venc)) {
      carry = line;
      continue;
    }

    if (value) {
      rows.push({
        Operação: op ?? '',
        Vencimento: venc ?? '',
        Parcela: value,
        'Valor Operação': value,
      });
      carry = '';
      continue;
    }

    carry = '';
  }

  if (rows.length === 0) {
    const fb = extractFallbackFromRawText(lines);
    if (fb.length > 0) rows = fb;
  }

  // Fallback final de ALL-MONEYS (antes gerava 0/0 com dinheiro em Parcela; DESATIVADO por
  // GERAR_TOTAIS como se fossem linhas. Só usar em cenários EXTREMOS onde nem carry nem raw
  // funcionaram. Se você chegou aqui com SISBR oficial, significa que o regex posicional acima
  // precisa ser ajustado, NÃO disparar este fallback.
  if (false && rows.length === 0 && text.trim().length > 0) {
    const allMoneys = extractAllMoneys(text.replace(/\r?\n/g, ' \n '));
    if (allMoneys.length > 0) {
      for (let i = 0; i < allMoneys.length; i++) {
        rows.push({
          Operação: '',
          Vencimento: '',
          Parcela: allMoneys[i],
          'Valor Operação': allMoneys[i],
        });
      }
    }
  }

  return { headers, rows };
}

export async function debugLocalSisbrPdfFile(
  filePathAbs: string,
): Promise<{
  ok: boolean;
  filePath: string;
  fileExists: boolean;
  fileName: string;
  fileSizeBytes: number | null;
  pdfText: string | null;
  pdfTextLength: number;
  extractResult: {
    headers: string[];
    rows: Array<Record<string, unknown>>;
  } | null;
  extractRowsCount: number;
  headersFirst30: Array<{ key: string; sampleRow0: unknown; sampleRow1: unknown }>;
  rowsFirst20: Array<Record<string, unknown>>;
  allMoneysCount: number;
  allMoneysFirst30: string[];
  error?: string;
}> {
  type R = Awaited<ReturnType<typeof debugLocalSisbrPdfFile>>;
  const result: R = {
    ok: true,
    filePath: filePathAbs,
    fileExists: false,
    fileName: path.basename(filePathAbs),
    fileSizeBytes: null,
    pdfText: null,
    pdfTextLength: 0,
    extractResult: null,
    extractRowsCount: 0,
    headersFirst30: [],
    rowsFirst20: [],
    allMoneysCount: 0,
    allMoneysFirst30: [],
  };
  try {
    if (!fs.existsSync(filePathAbs)) {
      result.ok = false;
      result.error = `Arquivo não encontrado em ${filePathAbs}`;
      return result;
    }
    result.fileExists = true;
    const st = fs.statSync(filePathAbs);
    result.fileSizeBytes = st.size;
    const buf = fs.readFileSync(filePathAbs);
    const parseFn = await getPdfParse();
    const parsed = await parseFn(buf);
    const text = typeof parsed?.text === 'string' ? parsed.text : '';
    result.pdfText = text.slice(0, 12000);
    result.pdfTextLength = text.length;
    const moneyRe = /(?:\d{1,3}(?:\.\d{3})+|\d+)(?:,\d{1,2})/g;
    const moneyMatches = Array.from(text.matchAll(moneyRe) || []).map((m) => m[0]);
    result.allMoneysCount = moneyMatches.length;
    result.allMoneysFirst30 = moneyMatches.slice(0, 30);
    const extracted = await readRelatorioTable(result.fileName, buf);
    result.extractResult = extracted;
    result.extractRowsCount = extracted.rows.length;
    result.rowsFirst20 = extracted.rows.slice(0, 20).map((r) => {
      const out: Record<string, unknown> = {};
      const keys = Object.keys(r);
      for (const k of keys.slice(0, 12)) {
        const v = r[k];
        if (typeof v === 'string' && v.length > 80) out[k] = v.slice(0, 80) + `...(${v.length} chars)`;
        else out[k] = v;
      }
      return out;
    });
    result.headersFirst30 = extracted.headers.slice(0, 30).map((h) => ({
      key: h,
      sampleRow0: extracted.rows[0]?.[h] ?? null,
      sampleRow1: extracted.rows[1]?.[h] ?? null,
    }));
    return result;
  } catch (e) {
    result.ok = false;
    result.error = e instanceof Error ? e.message : String(e ?? 'Erro desconhecido em debugLocalSisbrPdfFile');
    return result;
  }
}

async function openDatabase(dbPath: string): Promise<Database> {
  if (!cachedSqlJs) cachedSqlJs = initSqlJs();
  const SQL: SqlJsStatic = await cachedSqlJs;
  const resolvedPath = path.resolve(dbPath);
  const nowMs = Date.now();
  evictExpiredDbCacheEntriesIfNeeded(nowMs);
  evictOldDbCacheEntriesIfNeeded();

  let currentMtimeMs = 0;
  if (fs.existsSync(resolvedPath)) {
    try {
      currentMtimeMs = fs.statSync(resolvedPath).mtimeMs;
    } catch (e) {
      safeLogError(`openDatabase stat mtime ${resolvedPath}`, e);
      currentMtimeMs = 0;
    }
  }

  const cached = cachedDbByPath.get(resolvedPath);
  if (
    cached &&
    Math.abs(cached.mtimeMs - currentMtimeMs) <= DB_MTIME_SAFETY_DELTA_MS
  ) {
    cached.lastUsedMs = nowMs;
    return cached.db;
  }
  if (cached) {
    cachedDbByPath.delete(resolvedPath);
  }

  let db: Database;
  try {
    db = fs.existsSync(resolvedPath)
      ? new SQL.Database(fs.readFileSync(resolvedPath))
      : new SQL.Database();
  } catch (e) {
    safeLogError(`openDatabase create/read ${resolvedPath}`, e);
    throw e instanceof Error ? e : new Error(String(e));
  }
  try {
    // ===== CORREÇÃO CRÍTICA 2026-08-19: REMOVER PRAGMAS QUE SÓ EXISTEM NO SQLITE NATIVO =====
    //
    // Antecedente: o engine aqui é **SQL.js / WebAssembly SQLite EM MEMÓRIA**.
    // NÃO É a libsqlite3 nativa (better-sqlite3) que implementa journal_mode=WAL /
    // synchronous=FULL / auto_vacuum / busy_timeout.
    //
    // Problema grave: se o usuário abrir o arquivo `consignado.sqlite` de disco com UM
    // VISUALIZADOR NATIVO (DB Browser, DBeaver, Excel ODBC, Power BI, Beekeeper etc.),
    // esse visualizador **ativa o WAL mode e cria os arquivos consignado.sqlite-wal e
    // consignado.sqlite-shm no disco**, travando (FileShare=Read) o buffer de escrita
    // do windows para o trio. Quando o `persistDatabase()` do Nest tenta escrever o buffer
    // exportado do sql.js de volta, o Windows bloqueia → fs.writeFileSync FALHA → ou
    // apaga o `consignado.sqlite` (fica só -wal e -shm), ou só atualiza em memória e o
    // usuário fica vendo "313 linhas" no DB Browser enquanto o Nest vivo retorna 315 (cache).
    //
    // Como o SQL.js não usa o WAL do disco (ele controla em memória tudo), o correto é
    // NUNCA configurar journal_mode = WAL. Quando for necessário no futuro, usar
    // DELETE mode (SQLite default). Os outros pragmas também são sem efeito.
    const pragmas = [
      'PRAGMA journal_mode = DELETE;',
      'PRAGMA foreign_keys = ON;',
      'PRAGMA cache_size = -20000;',
    ];
    for (const p of pragmas) {
      try { db.run(p); } catch (e) { safeLogError(`openDatabase pragma ${p}`, e); }
    }
  } catch (e) {
    safeLogError('openDatabase pragmas block', e);
  }
  const finalMtimeMs = fs.existsSync(resolvedPath)
    ? (() => {
        try {
          return fs.statSync(resolvedPath).mtimeMs;
        } catch {
          return currentMtimeMs;
        }
      })()
    : currentMtimeMs;
  cachedDbByPath.set(resolvedPath, {
    db,
    mtimeMs: finalMtimeMs,
    lastUsedMs: Date.now(),
  });
  return db;
}

function persistDatabase(db: Database, dbFilePath: string) {
  try {
    const out = db.export();
    const resolvedPath = path.resolve(dbFilePath);
    fs.writeFileSync(resolvedPath, Buffer.from(out));
    if (cachedDbByPath.has(resolvedPath)) {
      let mtimeMs = Date.now();
      if (fs.existsSync(resolvedPath)) {
        try {
          mtimeMs = fs.statSync(resolvedPath).mtimeMs;
        } catch (e) {
          safeLogError('persistDatabase stat mtime', e);
        }
      }
      const prev = cachedDbByPath.get(resolvedPath)!;
      cachedDbByPath.set(resolvedPath, {
        db,
        mtimeMs,
        lastUsedMs: Date.now(),
      });
      void prev;
    }
  } catch (e) {
    safeLogError(`persistDatabase SYNC for ${dbFilePath}`, e);
    throw e instanceof Error ? e : new Error(String(e));
  }
}

async function persistDatabaseAsync(db: Database, dbFilePath: string): Promise<void> {
  return withDbWriteLock(async () => {
    const out = db.export();
    const resolvedPath = path.resolve(dbFilePath);
    try {
      await fsp.writeFile(resolvedPath, Buffer.from(out));
    } catch (e) {
      safeLogError(`persistDatabaseAsync writeFile for ${resolvedPath}`, e);
      try {
        fs.writeFileSync(resolvedPath, Buffer.from(out));
      } catch (e2) {
        safeLogError(`persistDatabaseAsync fallback sync for ${resolvedPath}`, e2);
        throw e2 instanceof Error ? e2 : new Error(String(e2));
      }
    }
    if (cachedDbByPath.has(resolvedPath)) {
      let mtimeMs = Date.now();
      if (fs.existsSync(resolvedPath)) {
        try {
          mtimeMs = fs.statSync(resolvedPath).mtimeMs;
        } catch (e) {
          safeLogError('persistDatabaseAsync stat mtime', e);
        }
      }
      cachedDbByPath.set(resolvedPath, {
        db,
        mtimeMs,
        lastUsedMs: Date.now(),
      });
    }
  });
}

const PRE_IMPORT_SNAP_MAX_KEEP = 24;
const PRE_IMPORT_SNAP_DIRNAME = 'snaps';
type PreImportSnapshotResult = { snapshotPath: string | null; skippedReason?: string };
async function takePreImportSnapshot(dbFilePath: string, label?: string): Promise<PreImportSnapshotResult> {
  try {
    const resolvedDb = path.resolve(dbFilePath);
    if (!fs.existsSync(resolvedDb)) return { snapshotPath: null, skippedReason: 'arquivo_nao_existe' };
    const stat = fs.statSync(resolvedDb);
    if (!stat.isFile() || stat.size <= 0) return { snapshotPath: null, skippedReason: 'arquivo_vazio' };
    const dbDir = path.dirname(resolvedDb);
    const dbBasename = path.basename(resolvedDb);
    const snapDir = path.join(dbDir, PRE_IMPORT_SNAP_DIRNAME);
    fs.mkdirSync(snapDir, { recursive: true });
    const stamp = new Date()
      .toISOString()
      .replace(/[-:]/g, '')
      .replace(/\.\d{3}Z$/, '')
      .replace('T', '-');
    const cleanLabel = typeof label === 'string' && label.trim()
      ? label.replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 60)
      : 'pre';
    const snapBasename = `${dbBasename}.${cleanLabel}-${stamp}.sqlite`;
    const snapPath = path.join(snapDir, snapBasename);
    try {
      await fsp.copyFile(resolvedDb, snapPath, fs.constants.COPYFILE_FICLONE);
    } catch {
      try {
        fs.copyFileSync(resolvedDb, snapPath);
      } catch (e) {
        safeLogError('takePreImportSnapshot copyFile', e);
        return { snapshotPath: null, skippedReason: 'copy_failed' };
      }
    }
    try {
      const existing = fs.readdirSync(snapDir)
        .filter((f) => f.startsWith(`${dbBasename}.`))
        .map((f) => {
          const full = path.join(snapDir, f);
          try { return { full, mtime: fs.statSync(full).mtimeMs }; } catch { return null; }
        })
        .filter((x): x is { full: string; mtime: number } => Boolean(x))
        .sort((a, b) => b.mtime - a.mtime);
      if (existing.length > PRE_IMPORT_SNAP_MAX_KEEP) {
        const toDelete = existing.slice(PRE_IMPORT_SNAP_MAX_KEEP);
        for (const x of toDelete) {
          try { fs.unlinkSync(x.full); } catch { void 0; }
        }
      }
    } catch (e) {
      safeLogError('takePreImportSnapshot trim old', e);
    }
    // === GARANTIA: assegurar que SNAPSHOT TEM TABELAS NOVAS Extratos/Relatorios (e schemas defaults)
    //   A cópia binária pode ter ocorrido ANTES do ensureSchema() no db principal atualizar,
    //   então reabrimos a cópia e rodamos ensureSchema + ensureDefaultLearningProfiles.
    try {
      const snapDb = await openDatabase(snapPath);
      try { ensureSchema(snapDb); } catch (e) { safeLogError('takePreImportSnapshot snap ensureSchema', e); }
      try { ensureDefaultLearningProfiles(snapDb); } catch (e) { safeLogError('takePreImportSnapshot snap ensureProfiles', e); }
      try { (snapDb as unknown as { close?: () => void }).close?.(); } catch { /* ignore */ }
    } catch (e) {
      safeLogError('takePreImportSnapshot snap open', e);
    }
    return { snapshotPath: snapPath };
  } catch (e) {
    safeLogError('takePreImportSnapshot outer', e);
    return { snapshotPath: null, skippedReason: 'outer_error' };
  }
}

const IMPORTED_FILE_HASH_CONFIG_PREFIX = 'imported_file_sha256::v1::';
const _nodeCryptoLazy: { sha256Hex: (buf: Buffer) => string } = (() => {
  const nodeCrypto = require('node:crypto') as {
    createHash: (algo: string) => { update: (b: Buffer) => { digest: (enc?: 'hex') => string } };
  };
  return {
    sha256Hex(buf: Buffer): string {
      return nodeCrypto.createHash('sha256').update(buf).digest('hex');
    },
  };
})();
function _computeImportedFileHashConfigKey(sha256Hex: string): string {
  return `${IMPORTED_FILE_HASH_CONFIG_PREFIX}${sha256Hex}`;
}
function isFileAlreadyImportedByContentHash(db: Database, sha256Hex: string): { imported: boolean; at?: string; meta?: unknown } {
  try {
    const raw = getConsignadoAppConfigValue(db, _computeImportedFileHashConfigKey(sha256Hex));
    if (typeof raw === 'string' && raw.trim() !== '') {
      try {
        const parsed = JSON.parse(raw);
        return { imported: true, at: typeof parsed?.at === 'string' ? parsed.at : undefined, meta: parsed?.meta ?? undefined };
      } catch {
        return { imported: true, at: undefined, meta: undefined };
      }
    }
  } catch (e) {
    safeLogError('isFileAlreadyImportedByContentHash lookup', e);
  }
  return { imported: false };
}
function markFileImportedByContentHash(db: Database, sha256Hex: string, meta?: Record<string, unknown>): void {
  try {
    const key = _computeImportedFileHashConfigKey(sha256Hex);
    const val = JSON.stringify({ at: new Date().toISOString(), meta: meta ?? null });
    setConsignadoAppConfigValue(db, key, val);
  } catch (e) {
    safeLogError('markFileImportedByContentHash write', e);
  }
}

function getSqlitePath(): string {
  const raw = (() => {
    if (process.env.SQLITE_PATH) return process.env.SQLITE_PATH;
    const cwd = process.cwd();
    const projectRootData = path.resolve(cwd, '..', 'data', 'consignado.sqlite');
    if (path.basename(cwd).toLowerCase() === 'backend' && fs.existsSync(projectRootData)) {
      return projectRootData;
    }
    return path.join(cwd, 'data', 'consignado.sqlite');
  })();
  const resolved = path.isAbsolute(raw) ? raw : path.resolve(process.cwd(), raw);
  fs.mkdirSync(path.dirname(resolved), { recursive: true });
  return resolved;
}

function escapeSqlIdentifier(name: string): string {
  const normalized = name
    .normalize('NFKC')
    .replace(/[\u0000-\u001F\u007F-\u009F]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  const safe = normalized.length > 0 ? normalized : 'COL';
  return `"${safe.replaceAll('"', '""')}"`;
}

function normalizeSqlIdentifierKey(name: string): string {
  const normalized = String(name ?? '')
    .normalize('NFKC')
    .replace(/[\u0000-\u001F\u007F-\u009F]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  const safe = normalized.length > 0 ? normalized : 'COL';
  return safe.toUpperCase();
}

function dedupeSqlColumns(columns: string[]): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  for (const col of columns) {
    const key = normalizeSqlIdentifierKey(col);
    if (!key) continue;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(col);
  }
  return out;
}

function tableExists(db: Database, name: string): boolean {
  const escaped = String(name ?? '').replaceAll("'", "''");
  if (!escaped) return false;
  try {
    // === CRITICAL FIX 2026-08-19 ===
    // SQL.js / SQLite por padrão é CASE SENSITIVE em nomes de colunas na tabela sqlite_master
    // sem COLLATE NOCASE. A tabela pode existir como "extratos" (minúsculo) no banco,
    // mas o perfil de aprendizado procura "Extratos" (PascalCase) → retornava false →
    // tentava criar a tabela novamente, dava erro interno e matava o job INTEIRO.
    // Solução: COLLATE NOCASE + também tentar normalizar ambas as formas.
    const stmt = db.prepare(
      `SELECT name FROM sqlite_master WHERE type='table' AND name='${escaped}' COLLATE NOCASE LIMIT 1;`,
    );
    try {
      return stmt.step() === true;
    } finally {
      try { (stmt as { free?: () => void }).free?.(); } catch { /* ignore */ }
    }
  } catch {
    return false;
  }
}

function listRecursoTableNamesFromDbSafe(db: Database): string[] {
  try {
    const res = db.exec(
      `SELECT name FROM sqlite_master WHERE type='table' AND name LIKE 'Recurso %' ORDER BY name;`,
    );
    const idx = res[0]?.columns?.indexOf('name') ?? -1;
    if (idx < 0) return [];
    return (res[0]?.values ?? [])
      .map((r) => String(r[idx] ?? '').trim())
      .filter(Boolean);
  } catch {
    return [];
  }
}

function hasAnyExtratoLikeTable(db: Database): boolean {
  if (tableExists(db, 'extratos')) return true;
  return listRecursoTableNamesFromDbSafe(db).length > 0;
}

function getExtratoLikeTableNames(db: Database): string[] {
  if (tableExists(db, 'extratos')) return ['extratos'];
  return listRecursoTableNamesFromDbSafe(db);
}

function readAllExtratoLikeRows(db: Database, columns: string[]): Array<Record<string, unknown>> {
  const tables = getExtratoLikeTableNames(db);
  const out: Array<Record<string, unknown>> = [];
  for (const tableName of tables) {
    const cols = getTableColumns(db, tableName);
    const wanted = columns.filter((c) => cols.some((x) => normalizeSqlIdentifierKey(x) === normalizeSqlIdentifierKey(c)));
    if (wanted.length === 0) continue;
    const rows = readTableRows(db, tableName, wanted);
    const orgaoFromTableName = tableName === 'extratos'
      ? null
      : tableName.replace(/^Recurso\s+/i, '').trim();
    for (const r of rows) {
      const augmented: Record<string, unknown> = { ...r };
      if (orgaoFromTableName) augmented['__ORGAO_TABLE__'] = orgaoFromTableName;
      augmented['__SOURCE_TABLE__'] = tableName;
      out.push(augmented);
    }
  }
  return out;
}

function pickFirstExtratoLikeColumn(db: Database, candidateNames: string[]): string | null {
  const tables = getExtratoLikeTableNames(db);
  for (const tableName of tables) {
    const cols = getTableColumns(db, tableName);
    const hit = pickFirstExistingColumn(cols, candidateNames);
    if (hit) return hit;
  }
  return null;
}

function pickFirstExtratoLikeColumnContaining(db: Database, needles: string[]): string | null {
  const tables = getExtratoLikeTableNames(db);
  for (const tableName of tables) {
    const cols = getTableColumns(db, tableName);
    const hit = pickFirstColumnContaining(cols, needles);
    if (hit) return hit;
  }
  return null;
}

function getExtratoLikeColumnsUnion(db: Database): string[] {
  const tables = getExtratoLikeTableNames(db);
  const seen = new Set<string>();
  const out: string[] = [];
  for (const tableName of tables) {
    const cols = getTableColumns(db, tableName);
    for (const c of cols) {
      const k = normalizeSqlIdentifierKey(c);
      if (!k || seen.has(k)) continue;
      seen.add(k);
      out.push(c);
    }
  }
  return out;
}

function getTableColumns(db: Database, tableName: string): string[] {
  const escaped = tableName.replaceAll("'", "''");
  const res = db.exec(`PRAGMA table_info('${escaped}');`);
  const colsIndex = res[0]?.columns?.indexOf('name') ?? -1;
  if (!res[0] || colsIndex === -1) return [];
  return res[0].values.map((row) => String(row[colsIndex]));
}

function intersectionCount(a: string[], b: string[]): number {
  const setB = new Set(b);
  let count = 0;
  for (const v of a) if (setB.has(v)) count += 1;
  return count;
}

function migrateLegacyExtratosIfNeeded(
  db: Database,
  expectedColumns: string[],
) {
  if (!tableExists(db, 'extratos')) return;
  const cols = getTableColumns(db, 'extratos');
  const shouldMigrate =
    cols.includes('payload') ||
    cols.some((c) => c.startsWith('__EMPTY')) ||
    (expectedColumns.length > 0 &&
      cols.length > 0 &&
      intersectionCount(cols, expectedColumns) === 0);

  if (!shouldMigrate) return;
  const suffix = new Date()
    .toISOString()
    .replaceAll(':', '')
    .replaceAll('-', '');
  const legacyName = `extratos_legacy_${suffix}`;
  db.run(`ALTER TABLE extratos RENAME TO ${escapeSqlIdentifier(legacyName)};`);
}

function migrateLegacyRelatorioIfNeeded(
  db: Database,
  expectedColumns: string[],
) {
  if (!tableExists(db, 'relatorio_consignado')) return;
  const cols = getTableColumns(db, 'relatorio_consignado');
  const shouldMigrate =
    cols.includes('payload') ||
    cols.some((c) => c.startsWith('__EMPTY')) ||
    (expectedColumns.length > 0 &&
      cols.length > 0 &&
      intersectionCount(cols, expectedColumns) === 0);

  if (!shouldMigrate) return;
  const suffix = new Date()
    .toISOString()
    .replaceAll(':', '')
    .replaceAll('-', '');
  const legacyName = `relatorio_consignado_legacy_${suffix}`;
  db.run(
    `ALTER TABLE relatorio_consignado RENAME TO ${escapeSqlIdentifier(legacyName)};`,
  );
}

function ensureExtratosTable(db: Database, fileColumns: string[]) {
  migrateLegacyExtratosIfNeeded(db, fileColumns);
  const headerMap = buildExtratoHeaderMapping(fileColumns);
  const effectiveColumns = headerMap.mappedColumns.slice();
  if (
    effectiveColumns.some(
      (c) => normalizeHeaderKey(c).replace(/\s/g, '') === 'REFANOMES',
    ) &&
    !effectiveColumns.some((c) =>
      ['COMPETENCIA', 'COPETENCIA'].includes(
        normalizeHeaderKey(c).replace(/\s/g, ''),
      ),
    )
  ) {
    effectiveColumns.push('Copetencia');
  }
  if (!tableExists(db, 'extratos')) {
    const columnsSql = effectiveColumns
      .map((c) => `${escapeSqlIdentifier(c)} TEXT`)
      .join(', ');
    db.run(`CREATE TABLE IF NOT EXISTS extratos (${columnsSql});`);
    return;
  }
  const existing = getTableColumns(db, 'extratos');
  const existingKeys = new Set(existing.map((c) => normalizeHeaderKey(c).replace(/\s/g, '')));
  for (const col of effectiveColumns) {
    const key = normalizeHeaderKey(col).replace(/\s/g, '');
    if (existingKeys.has(key)) continue;
    const legacyMatch = existing.find(
      (c) => normalizeHeaderKey(c).replace(/\s/g, '') === key,
    );
    if (legacyMatch) continue;
    db.run(`ALTER TABLE extratos ADD COLUMN ${escapeSqlIdentifier(col)} TEXT;`);
  }
}

function ensureRelatorioConsignadoTable(db: Database, fileColumns: string[]) {
  migrateLegacyRelatorioIfNeeded(db, fileColumns);

  if (!tableExists(db, 'relatorio_consignado')) {
    const columnsSql = fileColumns
      .map((c) => `${escapeSqlIdentifier(c)} TEXT`)
      .join(', ');
    db.run(`CREATE TABLE IF NOT EXISTS relatorio_consignado (${columnsSql});`);
    return;
  }

  const existing = new Set(getTableColumns(db, 'relatorio_consignado'));
  for (const col of fileColumns) {
    if (existing.has(col)) continue;
    db.run(
      `ALTER TABLE relatorio_consignado ADD COLUMN ${escapeSqlIdentifier(col)} TEXT;`,
    );
  }
}

