function listRecursoTableNamesFromDb(db: Database): string[] {
  const res = db.exec(
    `SELECT name FROM sqlite_master WHERE type='table' AND name LIKE 'Recurso %' ORDER BY name;`,
  );
  const idx = res[0]?.columns?.indexOf('name') ?? -1;
  return idx < 0
    ? []
    : (res[0]?.values ?? [])
        .map((r) => String(r[idx] ?? '').trim())
        .filter(Boolean);
}

export async function getRecursoTableNames() {
  const dbFilePath = getSqlitePath();
  const db = await openDatabase(dbFilePath);
  ensureSchema(db);

  const values = listRecursoTableNamesFromDb(db);

  return { values, dbFilePath };
}

export async function getExtratosHistorico1Values() {
  const dbFilePath = getSqlitePath();
  const db = await openDatabase(dbFilePath);
  ensureSchema(db);

  if (!tableExists(db, 'extratos')) {
    return { values: [] as Array<{ value: string; count: number }>, dbFilePath };
  }

  const cols = getTableColumns(db, 'extratos');
  const historico1Col = pickFirstExistingColumn(cols, ['HISTÓRICO_1', 'HISTORICO_1']);
  const historicoCol = pickFirstExistingColumn(cols, ['HISTÓRICO', 'HISTORICO']);
  if (!historico1Col && !historicoCol) {
    return { values: [] as Array<{ value: string; count: number }>, dbFilePath };
  }

  const merged = new Map<string, { value: string; count: number }>();
  for (const column of [historico1Col, historicoCol].filter(Boolean) as string[]) {
    const values = listDistinctColumnValues({
      db,
      table: 'extratos',
      column,
      limit: 600,
    });
    for (const item of values) {
      const key = normalizeOrgaoValueKey(item.value);
      const cur = merged.get(key);
      if (cur) cur.count += item.count;
      else merged.set(key, { value: item.value, count: item.count });
    }
  }
  const values = Array.from(merged.values())
    .sort((a, b) => b.count - a.count || a.value.localeCompare(b.value))
    .slice(0, 600);

  return { values, dbFilePath };
}

function normalizeEmail(value: string): string {
  return value.trim().toLowerCase();
}

function normalizeEmails(emails: string[]): string[] {
  return emails
    .map(normalizeEmail)
    .filter(Boolean)
    .filter((e, i, arr) => arr.indexOf(e) === i);
}

function toEmailSearchDisplayName(email: string): string {
  const normalized = normalizeEmail(email);
  const localPart = normalized.split('@')[0] || normalized;
  return localPart
    .split(/[._-]+/g)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

async function searchKnownLocalEmails(opts: { q: string; limit: number }) {
  const q = normalizeEmail(String(opts.q ?? ''));
  if (!q) return [] as Array<{ displayName: string; email: string }>;

  const dbFilePath = getSqlitePath();
  const db = await openDatabase(dbFilePath);
  ensureSchema(db);

  const emails = new Set<string>();

  if (tableExists(db, 'consignado_access_emails')) {
    const rows = readTableRows(db, 'consignado_access_emails', ['email']);
    for (const row of rows) {
      const email = typeof row.email === 'string' ? normalizeEmail(row.email) : '';
      if (email.includes('@')) emails.add(email);
    }
  }

  if (
    tableExists(db, 'conciliacao_pendencia_actions') &&
    getTableColumns(db, 'conciliacao_pendencia_actions').includes('gerente_email')
  ) {
    const rows = readTableRows(db, 'conciliacao_pendencia_actions', ['gerente_email']);
    for (const row of rows) {
      const email =
        typeof (row as any).gerente_email === 'string' ? normalizeEmail(String((row as any).gerente_email)) : '';
      if (email.includes('@')) emails.add(email);
    }
  }

  return [...emails]
    .map((email) => ({
      email,
      displayName: toEmailSearchDisplayName(email) || email,
    }))
    .filter((item) => {
      const displayNameKey = normalizeEmail(item.displayName).replace(/\s+/g, ' ').trim();
      return item.email.includes(q) || displayNameKey.includes(q);
    })
    .sort((a, b) => a.displayName.localeCompare(b.displayName) || a.email.localeCompare(b.email))
    .slice(0, opts.limit)
    .map((item) => ({
      displayName: item.displayName,
      email: item.email,
    }));
}

const FIXED_ACCESS_EMAIL = 'mario.junior@sicoobjuriscred.com.br';

type ConsignadoAccessRole = 'admin' | 'usuario';
type ConsignadoMenuPermission =
  | 'home'
  | 'dashboard'
  | 'fluxo-pendencias'
  | 'conciliacao-extratos'
  | 'conciliacao-relatorio'
  | 'relatorios-valores'
  | 'relatorios-ocorrencias'
  | 'relatorios-auditoria'
  | 'configuracoes-automacao'
  | 'configuracoes-acessos';
type ConsignadoFlowStagePermission = 'financeiro' | 'credito' | 'negocios';

const CONSIGNADO_MENU_PERMISSION_VALUES: ConsignadoMenuPermission[] = [
  'home',
  'dashboard',
  'fluxo-pendencias',
  'conciliacao-extratos',
  'conciliacao-relatorio',
  'relatorios-valores',
  'relatorios-ocorrencias',
  'relatorios-auditoria',
  'configuracoes-automacao',
  'configuracoes-acessos',
];

const CONSIGNADO_FLOW_STAGE_PERMISSION_VALUES: ConsignadoFlowStagePermission[] = [
  'financeiro',
  'credito',
  'negocios',
];

function normalizeAccessRole(value: unknown): ConsignadoAccessRole {
  if (typeof value !== 'string') return 'usuario';
  return value.trim().toLowerCase() === 'admin' ? 'admin' : 'usuario';
}

function normalizeMenuPermissions(
  value: unknown,
  fallbackToAll = true,
): ConsignadoMenuPermission[] {
  const raw = Array.isArray(value) ? value : [];
  const normalized = raw
    .map((item) => String(item ?? '').trim())
    .filter((item): item is ConsignadoMenuPermission =>
      CONSIGNADO_MENU_PERMISSION_VALUES.includes(item as ConsignadoMenuPermission),
    )
    .filter((item, index, arr) => arr.indexOf(item) === index);
  return normalized.length > 0 || !fallbackToAll
    ? normalized
    : [...CONSIGNADO_MENU_PERMISSION_VALUES];
}

function normalizeFlowStagePermissions(
  value: unknown,
  fallbackToAll = true,
): ConsignadoFlowStagePermission[] {
  const raw = Array.isArray(value) ? value : [];
  const normalized = raw
    .map((item) => String(item ?? '').trim().toLowerCase())
    .filter((item): item is ConsignadoFlowStagePermission =>
      CONSIGNADO_FLOW_STAGE_PERMISSION_VALUES.includes(item as ConsignadoFlowStagePermission),
    )
    .filter((item, index, arr) => arr.indexOf(item) === index);
  return normalized.length > 0 || !fallbackToAll
    ? normalized
    : [...CONSIGNADO_FLOW_STAGE_PERMISSION_VALUES];
}

function parseJsonArraySafe(value: unknown): unknown[] {
  if (Array.isArray(value)) return value;
  if (typeof value !== 'string') return [];
  const raw = value.trim();
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

