type ConciliacaoPorDataValidationStatus = 'pending' | 'approved' | 'rejected';
type ConciliacaoPorDataValidationDecision = 'approved' | 'rejected';

function parseJsonObjectSafe(value: unknown): Record<string, unknown> | null {
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    return value as Record<string, unknown>;
  }
  if (typeof value !== 'string') return null;
  const raw = value.trim();
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : null;
  } catch {
    return null;
  }
}

export function splitEmailRecipients(input: string | string[] | null | undefined): string[] {
  const rawItems = Array.isArray(input)
    ? input
    : String(input ?? '')
        .split(/[,;\n]/g)
        .map((item) => item.trim())
        .filter(Boolean);
  const seen = new Set<string>();
  const out: string[] = [];
  for (const item of rawItems) {
    const email = String(item ?? '').trim();
    if (!email || !email.includes('@')) continue;
    const lower = email.toLowerCase();
    if (seen.has(lower)) continue;
    seen.add(lower);
    out.push(email);
  }
  return out;
}

function getFirstEmailRecipient(input: string | string[] | null | undefined): string | null {
  const items = splitEmailRecipients(input);
  return items[0] ?? null;
}

