export async function runImportConsignado(opts: {
  folderUrl?: string;
  notificationTo?: string[];
  modalidades?: string[];
  mode?: 'append' | 'replace';
  target?: string;
}, ctxOpts?: {
  onProgressHook?: (partial: { importedFiles: unknown[]; totalFilesScanned?: number; totalFilesMatched?: number; totalRowsInserted?: number; totalRowsSkipped?: number; snapshotPath?: string }) => void;
  cancellationRequested?: () => boolean;
}): Promise<{
  executed: true;
  summary: Record<string, unknown>;
  resultsPerKind: Record<string, ReturnType<typeof importByLearningProfileFromFolderUrl>>;
  notificationEmail?: { attempted: boolean; sent: boolean; to: string[]; error?: string | null };
  notificationEmailsByKind?: Record<string, { attempted: boolean; sent: boolean; to: string[]; error?: string | null }>;
}> {
  const dbFilePath = getSqlitePath();
  const db = await openDatabase(dbFilePath);
  ensureSchema(db);
  let preSnap: { snapshotPath?: string } = { snapshotPath: undefined };
  try {
    const snap = await takePreImportSnapshot(dbFilePath, 'batch');
    preSnap.snapshotPath = snap.snapshotPath ?? undefined;
  } catch (e) {
    safeLogError('runImportConsignado pre-import snapshot', e);
  }
  if (ctxOpts?.onProgressHook) {
    try { ctxOpts.onProgressHook({ importedFiles: [], snapshotPath: preSnap.snapshotPath }); } catch { /* ignore */ }
  }
  const rootUrl =
    (typeof opts.folderUrl === 'string' && opts.folderUrl.trim()) ||
    String(
      getConsignadoAppConfigValue(db, CONFIG_KEY_SHAREPOINT_FOLDER_URL) ??
        getConsignadoAppConfigValue(db, CONFIG_KEY_RECURSO_TJGO_URL) ??
        '',
    ).trim();
  if (!rootUrl) throw new Error('URL raiz do SharePoint não configurada (Configurações → Automação).');

  const kindsAll = [
    { kind: 'recurso_tjgo' },
    { kind: 'recurso_mpgo' },
    { kind: 'recurso_adfego' },
    { kind: 'recurso_alego' },
    { kind: 'recurso_tce' },
    { kind: 'recurso_tcm' },
    { kind: 'recurso_tre' },
    { kind: 'recurso_trt' },
    { kind: 'recurso_eletra' },
    { kind: 'recurso_neoconsig' },
  ];
  const rawTarget = String(opts.target ?? '').trim();
  let kinds: Array<{ kind: string }> = kindsAll;
  if (rawTarget) {
    const tLow = rawTarget.toLowerCase();
    if (tLow === 'extratos' || tLow === 'extrato') {
      kinds = [{ kind: 'extratos' }];
    } else if (tLow === 'extratos_todos' || tLow === 'extrato_todos') {
      kinds = [{ kind: 'extratos' }];
    } else if (tLow === 'relatorio' || tLow === 'relatorios' || tLow === 'sisbr') {
      kinds = [{ kind: 'relatorio' }];
    } else if (kindsAll.some((k) => k.kind === rawTarget || k.kind.toLowerCase() === tLow)) {
      kinds = [{ kind: kindsAll.find((k) => k.kind === rawTarget || k.kind.toLowerCase() === tLow)!.kind }];
    }
  }
  const resultsPerKind: Record<string, any> = {};
  const cumulRowsInjected: { totalRowsInserted: number; totalRowsSkipped: number; totalFilesMatched: number; totalFilesScanned: number; cumulFiles: unknown[]; firstErrorMessage?: string | null; firstErrorStack?: string | null } = {
    totalRowsInserted: 0,
    totalRowsSkipped: 0,
    totalFilesMatched: 0,
    totalFilesScanned: 0,
    cumulFiles: [],
    firstErrorMessage: null,
    firstErrorStack: null,
  };
  for (const k of kinds) {
    if (ctxOpts && ctxOpts.cancellationRequested && ctxOpts.cancellationRequested()) {
      const err = new Error('Cancelado pelo usuário antes de ' + k.kind);
      resultsPerKind[k.kind] = {
        error: err.message,
        importedFiles: [], totalFilesScanned: 0, totalFilesMatched: 0, totalRowsInserted: 0, totalRowsSkipped: 0,
        mode: 'append', tableName: null, rows: 0, columns: 0, skippedDuplicates: 0, skippedNoCpf: 0, movedToImportados: false, movedToImportadosCount: null, moveError: null, filesImported: [], tablesCreated: [], dbFilePath: null,
      };
      break;
    }
    try {
      resultsPerKind[k.kind] = await importByLearningProfileFromFolderUrl({
        folderUrl: rootUrl,
        forceKind: k.kind,
        forceMode: String(opts.mode || 'append') === 'replace' ? 'replace' : 'append',
        notificationTo: opts.notificationTo,
      }, {
        onProgressHook: (p) => {
          if (ctxOpts?.onProgressHook) {
          try {
            const mergedFiles = p.importedFiles || [];
            const mergedRowsIn = Number(p.totalRowsInserted ?? 0);
            const mergedRowsSk = Number(p.totalRowsSkipped ?? 0);
            const mergedFmatch = Number(p.totalFilesMatched ?? 0);
            const mergedFscan = Number(p.totalFilesScanned ?? 0);
            cumulRowsInjected.totalRowsInserted += mergedRowsIn;
            cumulRowsInjected.totalRowsSkipped += mergedRowsSk;
            cumulRowsInjected.totalFilesMatched += mergedFmatch;
            cumulRowsInjected.totalFilesScanned += mergedFscan;
            (mergedFiles as unknown[]).forEach((f) => cumulRowsInjected.cumulFiles.push(f));
            ctxOpts.onProgressHook({ importedFiles: cumulRowsInjected.cumulFiles, totalRowsInserted: cumulRowsInjected.totalRowsInserted, totalRowsSkipped: cumulRowsInjected.totalRowsSkipped, totalFilesMatched: cumulRowsInjected.totalFilesMatched, totalFilesScanned: cumulRowsInjected.totalFilesScanned, snapshotPath: preSnap.snapshotPath });
          } catch { /* ignore */ }
        }
        },
        cancellationRequested: () => Boolean(ctxOpts?.cancellationRequested?.()),
      });
      const rr = resultsPerKind[k.kind];
      const errTxt = String(rr?.error ?? '').trim();
      if (errTxt && !cumulRowsInjected.firstErrorMessage) {
        cumulRowsInjected.firstErrorMessage = errTxt;
      }
      cumulRowsInjected.totalRowsInserted += Number(rr?.totalRowsInserted ?? 0);
      cumulRowsInjected.totalRowsSkipped += Number(rr?.totalRowsSkipped ?? 0);
      cumulRowsInjected.totalFilesMatched += Number(rr?.totalFilesMatched ?? 0);
      cumulRowsInjected.totalFilesScanned += Number(rr?.totalFilesScanned ?? 0);
      if (ctxOpts?.onProgressHook) {
        try {
          (rr.importedFiles || []).forEach((f: unknown) => cumulRowsInjected.cumulFiles.push(f));
          ctxOpts.onProgressHook({ importedFiles: cumulRowsInjected.cumulFiles, totalRowsInserted: cumulRowsInjected.totalRowsInserted, totalRowsSkipped: cumulRowsInjected.totalRowsSkipped, totalFilesMatched: cumulRowsInjected.totalFilesMatched, totalFilesScanned: cumulRowsInjected.totalFilesScanned, snapshotPath: preSnap.snapshotPath });
        } catch { /* ignore */ }
      }
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e ?? 'Falha desconhecida');
      const stack = e instanceof Error ? e.stack || null : null;
      if (!cumulRowsInjected.firstErrorMessage) {
        cumulRowsInjected.firstErrorMessage = message;
        cumulRowsInjected.firstErrorStack = stack;
      }
      resultsPerKind[k.kind] = {
        error: message,
        errorStack: stack,
        importedFiles: [],
        totalFilesScanned: 0,
        totalFilesMatched: 0,
        totalRowsInserted: 0,
        totalRowsSkipped: 0,
        mode: String(opts.mode || 'append') === 'replace' ? 'replace' : 'append',
        tableName: null,
        rows: 0,
        columns: 0,
        skippedDuplicates: 0,
        skippedNoCpf: 0,
        movedToImportados: false,
        movedToImportadosCount: null,
        moveError: null,
        filesImported: [],
        tablesCreated: [],
        dbFilePath: null,
      };
    }
  }
  const notificationEmailsByKind: Record<string, { attempted: boolean; sent: boolean; to: string[]; error?: string | null }> = {};
  let primaryNotificationEmail: { attempted: boolean; sent: boolean; to: string[]; error?: string | null } | undefined = undefined;
  const kindKeys = Object.keys(resultsPerKind);
  for (const k of kindKeys) {
    const rr = resultsPerKind[k];
    if (rr && typeof rr === 'object' && (rr as any).notificationEmail) {
      notificationEmailsByKind[k] = (rr as any).notificationEmail;
      if (!primaryNotificationEmail) primaryNotificationEmail = (rr as any).notificationEmail;
    }
  }
  return {
    executed: true,
    summary: {
      importedKinds: Object.keys(resultsPerKind).filter(
        (k) => !resultsPerKind[k]?.error && (resultsPerKind[k]?.totalFilesMatched ?? 0) > 0,
      ),
      failedKinds: Object.keys(resultsPerKind).filter((k) => Boolean(resultsPerKind[k]?.error)),
      firstErrorMessage: cumulRowsInjected.firstErrorMessage ?? null,
      firstErrorStack: cumulRowsInjected.firstErrorStack ?? null,
      selectedTarget: rawTarget || null,
      executedKinds: kinds.map((k) => k.kind),
      totals: {
        totalRowsInserted: cumulRowsInjected.totalRowsInserted,
        totalRowsSkipped: cumulRowsInjected.totalRowsSkipped,
        totalFilesMatched: cumulRowsInjected.totalFilesMatched,
        totalFilesScanned: cumulRowsInjected.totalFilesScanned,
        preImportSnapshotPath: preSnap.snapshotPath ?? null,
      },
    },
    resultsPerKind,
    notificationEmail: primaryNotificationEmail,
    notificationEmailsByKind,
  };
}

function formatOccurrencesPanoramaOrgaoLabel(orgaoRaw: unknown): string {
  const raw = String(orgaoRaw ?? '').trim();
  const key = normalizeExtratosOrgaoForMatch(raw) ?? '';
  if (key === 'PIX RECEBIDO OUTRA IF') return '(ELETRA) PIX RECEBIDO - OUTRA IF';
  if (key === 'CRED LIQUIDACAO COBRANCA') return '(ADFEGO) CRÉD.LIQUIDAÇÃO COBRANÇA';
  return raw;
}
function formatOccurrenceActionLabel(actionRaw: unknown): string {
  const t = String(actionRaw ?? '').trim().toLowerCase() || '';
  if (!t) return '-';
  const simple = t.replace(/_/g, ' ').replace(/\s+/g, ' ').trim();
  if (!simple) return '-';
  if (simple.startsWith('solicitar encaminhamento credito')) return 'Solicitar Encaminhamento Crédito';
  if (simple.startsWith('solicitar encaminhamento negocios')) return 'Solicitar Encaminhamento Negócios';
  if (simple.startsWith('solicitar recurso sisbr')) return 'Solicitar Recurso SISBR';
  if (simple.startsWith('enviar para contabilidade')) return 'Enviar para Contabilidade';
  if (simple.startsWith('fechamento financeiro')) return 'Fechamento Financeiro';
  if (simple.startsWith('credito liquidacao cobranca')) return 'Crédito Liquidação Cobrança';
  if (simple.startsWith('liquidacao fora vencimento')) return 'Liquidação Fora Vencimento';
  if (simple.startsWith('nao possui recurso')) return 'Não Possui Recurso';
  if (simple.startsWith('clonar sisbr')) return 'Clonar para SISBR';
  if (simple.startsWith('alterar orgao relatorio')) return 'Alterar Órgão Relatório';
  if (simple.startsWith('devolucao antecipado')) return 'Devolução (Antecipado)';
  if (simple.startsWith('devolucao quitado')) return 'Devolução (Quitado)';
  if (simple.startsWith('antecipado devolvido')) return 'Antecipado Devolvido';
  return simple.length > 1
    ? simple.charAt(0).toUpperCase() + simple.slice(1)
    : simple;
}
function formatOccurrencesPanoramaStageLabel(stage: unknown): string {
  const value = String(stage ?? '').trim().toLowerCase();
  if (value === 'credito') return 'Crédito';
  if (value === 'negocios') return 'Negócios';
  return 'Financeiro';
}
function formatOccurrencesPanoramaManagerLabel(emailRaw: unknown): string {
  const email = String(emailRaw ?? '').trim().toLowerCase();
  if (!email) return 'Sem gerente';
  const localPart = email.split('@')[0] ?? '';
  const words = localPart
    .split(/[._-]+/g)
    .map((item) => item.trim())
    .filter(Boolean)
    .map((item) => item.charAt(0).toUpperCase() + item.slice(1));
  return words.length > 0 ? words.join(' ') : email;
}
function getOccurrencesPanoramaMonthLabel(monthKey: unknown): string {
  const match = String(monthKey ?? '').trim().match(/^(\d{4})-(\d{2})$/);
  if (!match) return String(monthKey ?? '').trim() || '-';
  return `${match[2]}/${match[1]}`;
}
function resolveLatestOccurrencesPanoramaMonthKey(db: Database): string | null {
  if (!tableExists(db, 'conciliacao_pendencia_actions')) return null;
  const stmt = db.prepare(`SELECT month
     FROM conciliacao_pendencia_actions
     WHERE COALESCE(TRIM(undone_at),'')=''
       AND COALESCE(TRIM(error),'')=''
       AND TRIM(COALESCE(month,''))<>''
     GROUP BY month
     ORDER BY month DESC
     LIMIT 1;`);
  try {
    if (!stmt.step()) return null;
    const row = stmt.getAsObject() as any;
    return String(row.month ?? '').trim() || null;
  } finally { stmt.free(); }
}

