export async function getImportJob(jobId: string): Promise<JobRecord | null> {
  const r = ImportJobsManager.getOrNull(jobId);
  return r;
}
export function cancelImportJob(jobId: string): Promise<{ ok: boolean; reason?: string }> { return ImportJobsManager.cancel(jobId); }
export async function attachImportJobSse(jobId: string, res: { writeHead?: (status: number, headers: Record<string, string>) => void; write?: (chunk: string) => boolean; flushHeaders?: () => void; end?: () => void; socket?: unknown; connection?: unknown }): Promise<{ ok: boolean; reason?: string }> {
  const rec = await ImportJobsManager.getOrNull(jobId);
  if (!rec) return { ok: false, reason: 'job_not_found' };
  if (typeof (res as { writeHead?: unknown }).writeHead === 'function') {
    (res as { writeHead: (s: number, h: Record<string, string>) => void }).writeHead(200, {
      'Content-Type': 'text/event-stream; charset=utf-8',
      'Cache-Control': 'no-cache, no-transform',
      Connection: 'keep-alive',
      'X-Accel-Buffering': 'no',
    });
  }
  try {
    const sAny = res.socket || (res as { connection?: unknown }).connection;
    if (sAny) {
      try { (sAny as { setKeepAlive?: (b: boolean) => void }).setKeepAlive?.(true); } catch { /* ignore */ }
      try { (sAny as { setNoDelay?: (b: boolean) => void }).setNoDelay?.(true); } catch { /* ignore */ }
      try { (sAny as { setTimeout?: (n: number) => void }).setTimeout?.(0); } catch { /* ignore */ }
    }
  } catch { /* ignore */ }
  const send = (event: string, data: unknown): boolean => {
    const lines = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
    try { return Boolean(res.write?.(lines)); } catch { return false; }
  };
  send('hello', { jobId, atIso: _jobNowIso(), initial: rec });
  if (rec.status === 'succeeded' || rec.status === 'failed' || rec.status === 'cancelled') {
    send('final', { jobId, status: rec.status, summary: rec });
    try { res.end?.(); } catch { /* ignore */ }
    return { ok: true };
  }
  const reg = ImportJobsManager.on(jobId, (ev) => { send(ev.type, ev.payload); });
  const ticker = setInterval(async () => { try { const cur = await ImportJobsManager.getOrNull(jobId); if (cur) send('heartbeat', { heartbeatAtIso: cur.heartbeatAtIso || _jobNowIso(), status: cur.status }); } catch { /* ignore */ } }, JOB_EVENT_SSE_KEEPALIVE_MS);
  const cleanup = () => { try { clearInterval(ticker); reg.off(); } catch { /* ignore */ } try { res.end?.(); } catch { /* ignore */ } };
  const sAny2 = res.socket || (res as { connection?: unknown }).connection;
  try { (sAny2 as { on?: (ev: string, cb: () => void) => void })?.on?.('close', cleanup); } catch { /* ignore */ }
  try { (sAny2 as { once?: (ev: string, cb: () => void) => void })?.once?.('finish', cleanup); } catch { /* ignore */ }
  return { ok: true };
}

function _progressEventFromBatchResult(jobId: string, r: { importedFiles?: Array<{ fileName: string; insertedRows: number; skippedRows: number; skippedReason?: string; targetTable?: string }>; totalFilesScanned?: number; totalFilesMatched?: number; totalRowsInserted?: number; totalRowsSkipped?: number; snapshotPath?: string }): Array<Parameters<JobEventHandler>[0]> {
  const out: Array<Parameters<JobEventHandler>[0]> = [];
  const baseAt = _jobNowIso();
  if (typeof r.snapshotPath === 'string') out.push({ jobId, type: 'progress', atIso: baseAt, payload: { preImportSnapshotPath: r.snapshotPath } });
  if (typeof r.totalFilesScanned === 'number' || typeof r.totalFilesMatched === 'number') out.push({ jobId, type: 'progress', atIso: baseAt, payload: { totalFilesScanned: r.totalFilesScanned, totalFilesMatched: r.totalFilesMatched } });
  (r.importedFiles || []).forEach((f, idx) => { out.push({ jobId, type: 'progress', atIso: baseAt, payload: { file: { idx, fileName: f.fileName, targetTable: f.targetTable, insertedRows: f.insertedRows, skippedRows: f.skippedRows, skippedReason: f.skippedReason, atIso: baseAt } } }); });
  if (typeof r.totalRowsInserted === 'number' || typeof r.totalRowsSkipped === 'number') out.push({ jobId, type: 'progress', atIso: baseAt, payload: { totalRowsInserted: r.totalRowsInserted, totalRowsSkipped: r.totalRowsSkipped } });
  return out;
}

export function submitImportJobAsync(kind: JobKind, opts: unknown): { jobId: string; status: JobStatus; createdAtIso: string; kind: JobKind } {
  const submitted = ImportJobsManager.submit(kind, opts, async ({ onProgress, isCancelled }) => {
    const _wrapFire = (r: { importedFiles?: Array<{ fileName: string; insertedRows: number; skippedRows: number; skippedReason?: string; targetTable?: string }>; totalFilesScanned?: number; totalFilesMatched?: number; totalRowsInserted?: number; totalRowsSkipped?: number; snapshotPath?: string }) => {
      for (const ev of _progressEventFromBatchResult(submitted.jobId, r)) onProgress(ev);
    };
    if (kind === 'runImportConsignado') {
      const res = await runImportConsignado(opts as Parameters<typeof runImportConsignado>[0], {
        onProgressHook: (hook: any) => _wrapFire(hook),
        cancellationRequested: () => (typeof isCancelled === 'function' ? isCancelled() : false),
      });
      return res;
    }
    if (kind === 'importByLearningProfileFromFolderUrl') {
      const res = await importByLearningProfileFromFolderUrl(opts as Parameters<typeof importByLearningProfileFromFolderUrl>[0], {
        onProgressHook: (hook: { importedFiles?: unknown[]; totalFilesScanned?: number; totalFilesMatched?: number; totalRowsInserted?: number; totalRowsSkipped?: number; snapshotPath?: string }) => _wrapFire({ ...hook, totalFilesMatched: hook.importedFiles?.length ? 1 : undefined, totalFilesScanned: hook.importedFiles?.length ? 1 : undefined } as any),
        cancellationRequested: () => (typeof isCancelled === 'function' ? isCancelled() : false),
      });
      return res;
    }
    const res = await importByLearningProfileFromShareUrl(opts as Parameters<typeof importByLearningProfileFromShareUrl>[0]);
    return res;
  });
  return { jobId: submitted.jobId, status: submitted.status, createdAtIso: submitted.createdAtIso, kind };
}

