async function _f3OpenDb<T>(fn: (db: Database) => T | Promise<T>): Promise<T | null> {
  try {
    const path = getSqlitePath();
    const db = await openDatabase(path) as unknown as Database;
    try {
      const r = fn(db);
      return r instanceof Promise ? await r : r;
    } finally {
      /* NOTA: NÃO fechamos o db retornado por openDatabase().
         openDatabase() retorna uma instância CACHEADA compartilhada, gerenciada
         por cachedDbByPath, e fechá-la aqui causa "out of memory" no sql.js WASM
         pois outros trechos ainda estão usando a mesma referência. */
    }
  } catch (e) {
    console.error('[FASE3][_f3OpenDb] erro abrir/executar db:', e instanceof Error ? (e.stack || e.message) : String(e));
    return null;
  }
}
async function _cfgGet(key: string): Promise<string | null> {
  try {
    const v = await _f3OpenDb<string | null>((db) => getConsignadoAppConfigValue(db, key) ?? null) ?? null;
    return v;
  } catch (e) {
    console.error('[FASE3][_cfgGet] erro key=' + key, e instanceof Error ? (e.stack || e.message) : String(e));
    return null;
  }
}
async function _cfgSet(key: string, val: unknown): Promise<void> {
  try {
    const vRaw = typeof val === 'string' ? val : JSON.stringify(val);
    if (val === null || vRaw === 'null') {
      await _f3OpenDb<void>(async (db) => {
        try {
          if (!tableExists(db, 'consignado_app_config')) return;
          const stmt = db.prepare(`DELETE FROM consignado_app_config WHERE key=?;`);
          try { stmt.run([key]); } finally { try { (stmt as { free?: () => void }).free?.(); } catch { /* ignore */ } }
          try { persistDatabase(db, getSqlitePath()); } catch (e) { console.error('[FASE3][_cfgSet][DELETE] persistDatabase erro key=' + key, e instanceof Error ? e.message : String(e)); }
        } catch (e) { console.error('[FASE3][_cfgSet][DELETE] erro key=' + key, e instanceof Error ? (e.stack || e.message) : String(e)); }
      });
      return;
    }
    await _f3OpenDb<void>(async (db) => {
      try {
        setConsignadoAppConfigValue(db, key, vRaw as string);
        try { persistDatabase(db, getSqlitePath()); } catch (e) { console.error('[FASE3][_cfgSet][UPSERT] persistDatabase erro key=' + key, e instanceof Error ? e.message : String(e)); }
      } catch (e) { console.error('[FASE3][_cfgSet][UPSERT] erro key=' + key + ' valueLen=' + String(vRaw ?? '').length, e instanceof Error ? (e.stack || e.message) : String(e)); }
    });
  } catch (e) {
    console.error('[FASE3][_cfgSet] erro GLOBAL key=' + key, e instanceof Error ? (e.stack || e.message) : String(e));
  }
}
async function _f3JobPatch(jobId: string, patch: Partial<JobRecord>): Promise<void> {
  try {
    const rec = await ImportJobsManager.getOrNull(jobId);
    if (!rec) return;
    const merged: JobRecord = { ...rec, ...patch };
    if (patch.optsSnapshot && rec.optsSnapshot && typeof rec.optsSnapshot === 'object' && !Array.isArray(rec.optsSnapshot) && typeof patch.optsSnapshot === 'object' && !Array.isArray(patch.optsSnapshot)) {
      merged.optsSnapshot = { ...(rec.optsSnapshot as any), ...(patch.optsSnapshot as any) };
    }
    void _jobPersist(null, merged);
    try { ImportJobsManager.inMem.set(jobId, merged); } catch { /* ignore */ }
  } catch { /* ignore */ }
}
async function _f3ListKvKeysByPrefix(prefix: string, limit?: number): Promise<string[]> {
  const r = await _f3OpenDb<string[]>(async (db) => {
    const tryTable = async (tableName: 'consignado_app_config_values' | 'consignado_app_config'): Promise<string[]> => {
      try {
        if (!tableExists(db, tableName)) return [];
        const out: string[] = [];
        const sql = typeof limit === 'number'
          ? `SELECT key FROM ${tableName} WHERE key LIKE ? LIMIT ?`
          : `SELECT key FROM ${tableName} WHERE key LIKE ?`;
        const stmt = db.prepare(sql);
        try {
          const params: unknown[] = [`${prefix}%`];
          if (typeof limit === 'number') params.push(Math.max(1, limit));
          try { stmt.bind(params as any); } catch { /* alguns drivers não precisam de bind separado */ }
          while (stmt.step() === true) {
            const row = stmt.getAsObject() as { key?: unknown };
            const k = String(row?.key ?? '').trim();
            if (k) out.push(k);
          }
          return out;
        } finally { try { (stmt as { free?: () => void }).free?.(); } catch { /* ignore */ } }
      } catch { return []; }
    };
    const a = await tryTable('consignado_app_config_values');
    if (a && a.length > 0) return a;
    return await tryTable('consignado_app_config');
  });
  return r ?? [];
}
async function _f3CountKvKeysByPrefix(prefix: string): Promise<number> {
  const r = await _f3OpenDb<number>(async (db) => {
    const tryTable = async (tableName: 'consignado_app_config_values' | 'consignado_app_config'): Promise<number | null> => {
      try {
        if (!tableExists(db, tableName)) return null;
        const stmt = db.prepare(`SELECT COUNT(*) as c FROM ${tableName} WHERE key LIKE ?`);
        try {
          try { stmt.bind([`${prefix}%`] as any); } catch { /* ignore */ }
          if (stmt.step() !== true) return 0;
          const row = stmt.getAsObject() as { c?: unknown };
          const n = Number(row?.c ?? 0);
          return Number.isFinite(n) ? n : 0;
        } finally { try { (stmt as { free?: () => void }).free?.(); } catch { /* ignore */ } }
      } catch { return null; }
    };
    const a = await tryTable('consignado_app_config_values');
    if (typeof a === 'number' && Number.isFinite(a)) return a;
    const b = await tryTable('consignado_app_config');
    return typeof b === 'number' && Number.isFinite(b) ? b : 0;
  });
  return r ?? 0;
}

export async function getAutomationConfig(): Promise<AutomationConfigFull> {
  const ttlRaw = Number(await _cfgGet(KEY_CFG_TTL_JOBS_DAYS) || '90');
  const horaRaw = Number(await _cfgGet(KEY_CFG_SCHED_HH) || '8');
  const minRaw = Number(await _cfgGet(KEY_CFG_SCHED_MM) || '0');
  return {
    teamsWebhookUrl: (await _cfgGet(KEY_CFG_WEBHOOK_TEAMS)) || null,
    teamsNotifyEnabled: ((await _cfgGet(KEY_CFG_NOTIFY_TEAMS_ENABLED)) || '1') === '1',
    jobsTtlDias: Number.isFinite(ttlRaw) && ttlRaw >= 1 ? ttlRaw : 90,
    schedulerEnabled: ((await _cfgGet(KEY_CFG_ENABLE_SCHEDULER)) || '1') === '1',
    scheduleDefaultHora: Number.isFinite(horaRaw) ? Math.max(0, Math.min(23, horaRaw)) : 8,
    scheduleDefaultMin: Number.isFinite(minRaw) ? Math.max(0, Math.min(59, minRaw)) : 0,
  };
}

export async function saveAutomationConfigPartial(partial: Partial<AutomationConfigFull> & { teamsWebhookUrlClear?: boolean }): Promise<AutomationConfigFull> {
  console.log('[FASE3][saveAutomationConfigPartial] INICIANDO com campos:', JSON.stringify(Object.keys(partial)));
  if (typeof partial.jobsTtlDias === 'number') { const v = String(Math.max(1, partial.jobsTtlDias)); console.log('[FASE3][saveAutomationConfigPartial] Salvando jobsTtlDias=' + v + ' key=' + KEY_CFG_TTL_JOBS_DAYS); await _cfgSet(KEY_CFG_TTL_JOBS_DAYS, v); }
  if (typeof partial.schedulerEnabled === 'boolean') { const v = partial.schedulerEnabled ? '1' : '0'; console.log('[FASE3][saveAutomationConfigPartial] Salvando schedulerEnabled=' + v); await _cfgSet(KEY_CFG_ENABLE_SCHEDULER, v); }
  if (typeof partial.teamsNotifyEnabled === 'boolean') { const v = partial.teamsNotifyEnabled ? '1' : '0'; console.log('[FASE3][saveAutomationConfigPartial] Salvando teamsNotifyEnabled=' + v); await _cfgSet(KEY_CFG_NOTIFY_TEAMS_ENABLED, v); }
  if (typeof partial.scheduleDefaultHora === 'number') { const v = String(Math.max(0, Math.min(23, Math.round(partial.scheduleDefaultHora)))); console.log('[FASE3][saveAutomationConfigPartial] Salvando scheduleDefaultHora=' + v); await _cfgSet(KEY_CFG_SCHED_HH, v); }
  if (typeof partial.scheduleDefaultMin === 'number') { const v = String(Math.max(0, Math.min(59, Math.round(partial.scheduleDefaultMin)))); console.log('[FASE3][saveAutomationConfigPartial] Salvando scheduleDefaultMin=' + v); await _cfgSet(KEY_CFG_SCHED_MM, v); }
  if (partial.teamsWebhookUrlClear === true) { console.log('[FASE3][saveAutomationConfigPartial] LIMPANDO teamsWebhookUrl'); await _cfgSet(KEY_CFG_WEBHOOK_TEAMS, null as any); }
  if (typeof partial.teamsWebhookUrl === 'string' && partial.teamsWebhookUrl.trim()) { console.log('[FASE3][saveAutomationConfigPartial] Salvando teamsWebhookUrl len=' + partial.teamsWebhookUrl.trim().length); await _cfgSet(KEY_CFG_WEBHOOK_TEAMS, partial.teamsWebhookUrl.trim()); }
  const result = await getAutomationConfig();
  console.log('[FASE3][saveAutomationConfigPartial] CONCLUÍDO. Resultado final jobsTtlDias=' + result.jobsTtlDias + ' schedulerEnabled=' + result.schedulerEnabled);
  return result;
}

/* ---------- TTL Limpeza de Jobs Antigos ---------- */
export async function cleanupOldJobsTtl(overrideTtlDias?: number): Promise<{ removed: number; ttlDias: number; checked: number }> {
  const cfg = await getAutomationConfig();
  const dias = overrideTtlDias ?? cfg.jobsTtlDias;
  const cutMs = Date.now() - dias * 24 * 60 * 60 * 1000;
  const allKeys = await _f3ListKvKeysByPrefix('job_record::v1::', 20000);
  let removed = 0;
  for (const k of allKeys) {
    try {
      const raw = await _cfgGet(k);
      if (!raw) continue;
      const parsed = JSON.parse(raw) as Partial<JobRecord> | null;
      const ts = new Date(parsed?.finishedAtIso || parsed?.heartbeatAtIso || parsed?.createdAtIso || 0).getTime();
      if (Number.isFinite(ts) && ts < cutMs) {
        await _cfgSet(k, null as any);
        removed += 1;
      }
    } catch {
      /* ignore parse errors — não apaga para não perder dados */
    }
  }
  try {
    const cap = typeof (ImportJobsManager as any).JOB_MAX_IN_MEM === 'number' ? Number((ImportJobsManager as any).JOB_MAX_IN_MEM) : 80;
    if (ImportJobsManager.inMem.size > cap) {
      const ord = [...ImportJobsManager.inMem.values()].sort((a, b) => a.createdAtIso.localeCompare(b.createdAtIso));
      const cutIdx = Math.floor(cap * 0.7);
      const toDel = ord.slice(0, ord.length - cutIdx);
      for (const r of toDel) ImportJobsManager.inMem.delete(r.jobId);
    }
  } catch { /* ignore */ }
  return { removed, ttlDias: dias, checked: allKeys.length };
}

/* ---------- Notificações Teams Webhook Incoming (Adaptive Card) ---------- */
async function maybeNotifyTeamsJobFinal(rec: JobRecord): Promise<{ ok: boolean; reason?: string }> {
  try {
    const cfg = await getAutomationConfig();
    if (!cfg.teamsNotifyEnabled) return { ok: false, reason: 'teams_notify_disabled' };
    const url = cfg.teamsWebhookUrl;
    if (!url || !/^https?:\/\//i.test(url)) return { ok: false, reason: 'teams_webhook_nao_configurada' };
    const STATUS_STYLES_LOCAL: Record<JobStatus, { label: string }> = { queued: { label: 'Na fila' }, running: { label: 'Executando' }, succeeded: { label: 'Concluído' }, failed: { label: 'Falhou' }, cancelled: { label: 'Cancelado' } };
    const statusLabel = STATUS_STYLES_LOCAL?.[rec.status]?.label ?? rec.status;
    const titleEmoji = rec.status === 'succeeded' ? '✅' : rec.status === 'failed' ? '❌' : rec.status === 'cancelled' ? '🛑' : 'ℹ️';
    const cardColor = rec.status === 'succeeded' ? 'good' : rec.status === 'failed' ? 'attention' : rec.status === 'cancelled' ? 'warning' : 'accent';
    const fmtD = (iso?: string) => { if (!iso) return '–'; try { const d = new Date(iso); if (!Number.isFinite(d.getTime())) return '–'; return d.toLocaleString('pt-BR'); } catch { return '–'; } };
    const fmtDur = (aIso?: string, bIso?: string): string => {
      if (!aIso || !bIso) return '–'; const ms = new Date(bIso).getTime() - new Date(aIso).getTime();
      if (!Number.isFinite(ms) || ms < 0) return '–'; const s = Math.floor(ms / 1000); const m = Math.floor(s / 60); const h = Math.floor(m / 60);
      if (h > 0) return `${h}h ${m % 60}m ${s % 60}s`; if (m > 0) return `${m}m ${s % 60}s`; return `${s}s`;
    };
    const kindLabel = (k: string): string => {
      if (k === 'runImportConsignado') return '🔁 Importação Principal (Lote)';
      if (k === 'importByLearningProfileFromFolderUrl') return '📂 Importação Pasta/Órgão';
      if (k === 'importByLearningProfileFromShareUrl') return '📎 Importação Arquivo Direto'; return String(k);
    };
    const facts = [
      { title: 'Job ID', value: `\`${rec.jobId}\`` },
      { title: 'Tipo', value: kindLabel(rec.kind) },
      { title: 'Status', value: statusLabel },
      { title: 'Criado em', value: fmtD(rec.createdAtIso) },
      { title: 'Iniciado em', value: fmtD(rec.startedAtIso) },
      { title: 'Finalizado em', value: fmtD(rec.finishedAtIso) || new Date().toLocaleString('pt-BR') },
      { title: 'Duração', value: fmtDur(rec.startedAtIso || rec.createdAtIso, rec.finishedAtIso || new Date().toISOString()) },
      { title: 'Arquivos processados', value: String(rec.progressFiles?.length ?? 0) },
      { title: 'Linhas inseridas', value: String((rec.totalRowsInserted ?? 0).toLocaleString('pt-BR')) },
      { title: 'Linhas puladas', value: String((rec.totalRowsSkipped ?? 0).toLocaleString('pt-BR')) },
    ];
    if (rec.errorMessage) facts.push({ title: 'Erro', value: String(rec.errorMessage).slice(0, 500) });
    const body = {
      type: 'message',
      attachments: [{
        contentType: 'application/vnd.microsoft.card.adaptive',
        content: {
          $schema: 'http://adaptivecards.io/schemas/adaptive-card.json', type: 'AdaptiveCard', version: '1.4',
          msteams: { width: 'Full' }, accent: cardColor as any,
          body: [{ type: 'Container', items: [
            { type: 'TextBlock', size: 'medium', weight: 'bolder', text: `${titleEmoji} Automação de Importação: ${statusLabel}` },
            { type: 'FactSet', facts },
          ] }],
        },
      }],
    };
    const r = await fetchWithRetryExponential(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    }, { label: 'teams-webhook', maxAttempts: 2, baseMs: 1500, timeoutMs: 20000 }).catch((e) => e as Error);
    if (r instanceof Error) return { ok: false, reason: r.message };
    if (!r.ok) {
      const txt = (await r.text().catch(() => '')).slice(0, 200);
      return { ok: false, reason: `teams_http_${r.status} ${txt}` };
    }
    return { ok: true };
  } catch (e) {
    return { ok: false, reason: e instanceof Error ? e.message : String(e ?? 'unknown') };
  }
}

/* ---------- Scheduler (sem dependências, setInterval 30s) ---------- */
const SCHED_TICK_MS = 30 * 1000;
const _schedState: SchedTickState = { startedAtIso: new Date().toISOString(), running: false, tickCount: 0 };

function _isWeekdayPtBr(d: Date): boolean {
  const w = d.getDay(); return w >= 1 && w <= 5;
}
function scheduleCalculateNextRunAt(s: Pick<AutomationScheduleRecord, 'hora' | 'minuto' | 'diasUteisOnly' | 'diasSemana'>, from?: Date): string {
  const base = from ? new Date(from) : new Date();
  base.setMilliseconds(0); base.setSeconds(0); base.setMinutes(s.minuto); base.setHours(s.hora);
  for (let i = 0; i < 14; i += 1) {
    const t = new Date(base.getTime() + i * 24 * 60 * 60 * 1000);
    const dw = t.getDay() as 0 | 1 | 2 | 3 | 4 | 5 | 6;
    const diaOk = s.diasUteisOnly ? _isWeekdayPtBr(t) : (s.diasSemana && s.diasSemana.length > 0 ? s.diasSemana.includes(dw) : true);
    if (!diaOk) continue;
    if (t.getTime() <= (from?.getTime() ?? Date.now())) continue;
    return t.toISOString();
  }
  return new Date(base.getTime() + 24 * 60 * 60 * 1000).toISOString();
}
function scheduleIsDueNow(s: Pick<AutomationScheduleRecord, 'hora' | 'minuto' | 'diasUteisOnly' | 'diasSemana' | 'lastRunAtIso'>, now?: Date): boolean {
  const n = now ?? new Date();
  const dw = n.getDay() as 0 | 1 | 2 | 3 | 4 | 5 | 6;
  const diaOk = s.diasUteisOnly ? _isWeekdayPtBr(n) : (s.diasSemana && s.diasSemana.length > 0 ? s.diasSemana.includes(dw) : true);
  if (!diaOk) return false;
  if (n.getHours() !== s.hora || n.getMinutes() !== s.minuto) return false;
  const last = s.lastRunAtIso ? new Date(s.lastRunAtIso) : null;
  if (last) {
    const msDiff = n.getTime() - last.getTime();
    if (msDiff < 23 * 60 * 60 * 1000) return false;
  }
  return true;
}

async function _ensureDefaultSchedules(): Promise<void> {
  try {
    const existing = await _cfgGet(PREFIX_SCHED + SCHED_DEFAULT_ID);
    const cfg = await getAutomationConfig();
    if (!existing) {
      const rec: AutomationScheduleRecord = {
        id: SCHED_DEFAULT_ID,
        title: 'Lote Diário Automático (dias úteis)',
        kind: 'runImportConsignado',
        target: 'both',
        folderUrl: null,
        hora: cfg.scheduleDefaultHora,
        minuto: cfg.scheduleDefaultMin,
        diasUteisOnly: true,
        enabled: cfg.schedulerEnabled,
        createdAtIso: new Date().toISOString(),
        updatedAtIso: new Date().toISOString(),
        notificationTeams: cfg.teamsNotifyEnabled,
        nextRunAtIso: '',
      };
      rec.nextRunAtIso = scheduleCalculateNextRunAt(rec);
      await _cfgSet(PREFIX_SCHED + SCHED_DEFAULT_ID, JSON.stringify(rec));
      console.log('[FASE3][_ensureDefaultSchedules] CRIADO schedule default id=' + SCHED_DEFAULT_ID + ' nextRunAt=' + rec.nextRunAtIso);
    } else {
      try {
        const r = JSON.parse(existing) as AutomationScheduleRecord;
        if (typeof r.hora !== 'number' || typeof r.minuto !== 'number') { r.hora = cfg.scheduleDefaultHora; r.minuto = cfg.scheduleDefaultMin; }
        r.nextRunAtIso = scheduleCalculateNextRunAt(r);
        if (cfg.schedulerEnabled && !r.enabled) r.enabled = true;
        r.updatedAtIso = new Date().toISOString();
        await _cfgSet(PREFIX_SCHED + SCHED_DEFAULT_ID, JSON.stringify(r));
        console.log('[FASE3][_ensureDefaultSchedules] ATUALIZADO schedule default id=' + SCHED_DEFAULT_ID + ' enabled=' + r.enabled + ' nextRunAt=' + r.nextRunAtIso);
      } catch (e) { console.error('[FASE3][_ensureDefaultSchedules] erro parse existing schedule', e instanceof Error ? (e.stack || e.message) : String(e)); }
    }
  } catch (e) { console.error('[FASE3][_ensureDefaultSchedules] erro GLOBAL', e instanceof Error ? (e.stack || e.message) : String(e)); }
}

export async function listAutomationSchedules(): Promise<AutomationScheduleRecord[]> {
  const rows = await _f3ListKvKeysByPrefix(PREFIX_SCHED);
  const out: AutomationScheduleRecord[] = [];
  for (const k of rows) {
    try {
      const raw = await _cfgGet(k);
      if (!raw) continue;
      const obj = JSON.parse(raw) as AutomationScheduleRecord;
      obj.nextRunAtIso = scheduleCalculateNextRunAt(obj);
      out.push(obj);
    } catch { /* ignore */ }
  }
  out.sort((a, b) => (a.id < b.id ? -1 : 1));
  return out;
}
export async function getAutomationSchedule(id: string): Promise<AutomationScheduleRecord | null> {
  if (!id) return null;
  const raw = await _cfgGet(PREFIX_SCHED + id);
  if (!raw) return null;
  try {
    const r = JSON.parse(raw) as AutomationScheduleRecord;
    r.nextRunAtIso = scheduleCalculateNextRunAt(r);
    return r;
  } catch { return null; }
}
export async function toggleAutomationSchedule(id: string, force?: boolean): Promise<{ ok: boolean; record?: AutomationScheduleRecord; reason?: string }> {
  const cur = await getAutomationSchedule(id);
  if (!cur) return { ok: false, reason: 'schedule_nao_encontrado' };
  cur.enabled = typeof force === 'boolean' ? force : !cur.enabled;
  cur.updatedAtIso = new Date().toISOString();
  cur.nextRunAtIso = scheduleCalculateNextRunAt(cur);
  await _cfgSet(PREFIX_SCHED + id, JSON.stringify(cur));
  return { ok: true, record: cur };
}
export async function runAutomationScheduleNow(id: string): Promise<{ ok: boolean; reason?: string; jobId?: string; status?: JobStatus; createdAtIso?: string }> {
  const cur = await getAutomationSchedule(id);
  if (!cur) return { ok: false, reason: 'schedule_nao_encontrado' };
  try {
    const opts = cur.kind === 'runImportConsignado'
      ? { folderUrl: cur.folderUrl || undefined, mode: 'append' as const, target: (cur.target as any) || 'both' }
      : cur.kind === 'importByLearningProfileFromFolderUrl'
      ? { folderUrl: cur.folderUrl || '', forceKind: (cur.target as any) || 'both', forceMode: 'append' as const }
      : {};
    const submitted = submitImportJobAsync(cur.kind, opts);
    cur.lastRunAtIso = new Date().toISOString();
    cur.lastJobId = submitted.jobId;
    cur.lastStatus = submitted.status;
    cur.updatedAtIso = new Date().toISOString();
    cur.nextRunAtIso = scheduleCalculateNextRunAt(cur);
    await _cfgSet(PREFIX_SCHED + id, JSON.stringify(cur));
    try { void _f3JobPatch(submitted.jobId, { optsSnapshot: { scheduleId: cur.id, scheduleTitle: cur.title } }); } catch { /* ignore */ }
    return { ok: true, jobId: submitted.jobId, status: submitted.status, createdAtIso: submitted.createdAtIso };
  } catch (e) {
    return { ok: false, reason: e instanceof Error ? e.message : String(e ?? 'unknown') };
  }
}

async function _schedulerTickOnce(): Promise<void> {
  try {
    _schedState.tickCount += 1;
    _schedState.lastTickAtIso = new Date().toISOString();
    const cfg = await getAutomationConfig();
    if (!cfg.schedulerEnabled) return;
    _schedState.lastRunDueCheckAtIso = new Date().toISOString();
    const schedules = await listAutomationSchedules();
    const now = new Date();
    for (const s of schedules) {
      if (!s.enabled) continue;
      if (!scheduleIsDueNow(s, now)) continue;
      try { void (async () => { try { console.log('[FASE3][Scheduler] Tick disparou execução automática scheduleId=' + s.id + ' title=' + s.title); await runAutomationScheduleNow(s.id); } catch (e) { console.error('[FASE3][Scheduler] erro runScheduleNow id=' + s.id, e instanceof Error ? (e.stack || e.message) : String(e)); } })(); } catch { /* ignore schedule run individual errors */ }
    }
    if (_schedState.tickCount % 120 === 0) {
      void cleanupOldJobsTtl().catch((e) => { console.error('[FASE3][Scheduler] cleanupOldJobsTtl erro periódico:', e instanceof Error ? (e.stack || e.message) : String(e)); });
    }
  } catch (e) { console.error('[FASE3][Scheduler] _schedulerTickOnce erro GLOBAL tickCount=' + (_schedState.tickCount + 1), e instanceof Error ? (e.stack || e.message) : String(e)); }
}

function _attachBootstrapListenersOnce(): void {
  if ((globalThis as any).__f3_listeners_attached === true) return;
  (globalThis as any).__f3_listeners_attached = true;
  try {
    ImportJobsManager.on('*' as any, (ev: { type?: string; jobId?: string; payload?: unknown }) => {
      try {
        if (ev.type !== 'status' || !ev.jobId) return;
        const payload = ev.payload as any;
        const status = payload?.status as JobStatus | undefined;
        if (!status || !['succeeded','failed','cancelled'].includes(status)) return;
        void (async () => {
          const rec = await ImportJobsManager.getOrNull(ev.jobId!);
          if (!rec || rec.status !== status) return;
          void maybeNotifyTeamsJobFinal(rec);
        })();
      } catch (e) { console.error('[FASE3][listener][status] erro', e instanceof Error ? (e.stack || e.message) : String(e)); }
    });
    console.log('[FASE3][_attachBootstrapListenersOnce] Listener JobManager.on(*) anexado com sucesso.');
  } catch (e) { console.error('[FASE3][_attachBootstrapListenersOnce] erro anexar listener', e instanceof Error ? (e.stack || e.message) : String(e)); }
  let intervalRef: ReturnType<typeof setInterval> | null = null;
  const start = () => {
    if (intervalRef) return;
    _schedState.running = true;
    _schedState.startedAtIso = new Date().toISOString();
    console.log('[FASE3][Scheduler] Iniciando setInterval tick_ms=' + SCHED_TICK_MS);
    void _schedulerTickOnce();
    intervalRef = setInterval(() => { void _schedulerTickOnce(); }, SCHED_TICK_MS);
    try { if ((globalThis as any).__automation_scheduler_interval) clearInterval((globalThis as any).__automation_scheduler_interval); } catch { /* ignore */ }
    (globalThis as any).__automation_scheduler_interval = intervalRef;
  };
  void (async () => {
    try {
      const cfg = await getAutomationConfig();
      if (cfg.schedulerEnabled) { console.log('[FASE3][Scheduler] Agendamento habilitado, start() em 5s...'); setTimeout(start, 5000); }
      else { console.log('[FASE3][Scheduler] Agendamento DESABILITADO via config schedulerEnabled=false'); }
    } catch (e) { console.error('[FASE3][Scheduler] erro obter cfg no attachListeners', e instanceof Error ? (e.stack || e.message) : String(e)); }
  })();
}

/* ---------- Failures Dashboard ---------- */
export interface FailureDashboardRow {
  jobId: string;
  jobKind: string;
  jobStatus: JobStatus;
  jobCreatedAtIso: string;
  fileName?: string;
  targetTable?: string;
  insertedRows: number;
  skippedRows: number;
  skippedReason?: string;
  fileAtIso?: string;
  errorMessage?: string;
}
export async function listAutomationImportFailures(opts?: { dias?: number; limit?: number; onlySkipped?: boolean }): Promise<{ total: number; rows: FailureDashboardRow[]; dias: number }> {
  const dias = Math.max(1, Math.min(365, opts?.dias ?? 30));
  const limit = Math.max(1, Math.min(1000, opts?.limit ?? 200));
  const corteMs = Date.now() - dias * 24 * 60 * 60 * 1000;
  const rowsKeys = await _f3ListKvKeysByPrefix('job_record::v1::', 1000);
  const out: FailureDashboardRow[] = [];
  for (const k of rowsKeys) {
    if (out.length >= limit) break;
    try {
      const raw = await _cfgGet(k);
      if (!raw) continue;
      const job = JSON.parse(raw) as JobRecord;
      const ts = new Date(job.finishedAtIso || job.heartbeatAtIso || job.createdAtIso || 0).getTime();
      if (!Number.isFinite(ts) || ts < corteMs) continue;
      const files = job.progressFiles || [];
      for (const f of files) {
        const temSkip = (f.skippedRows ?? 0) > 0 || Boolean(f.skippedReason);
        if (opts?.onlySkipped && !temSkip) continue;
        if (!opts?.onlySkipped && !temSkip && job.status !== 'failed' && !job.errorMessage) continue;
        out.push({
          jobId: job.jobId, jobKind: job.kind, jobStatus: job.status, jobCreatedAtIso: job.createdAtIso,
          fileName: f.fileName, targetTable: f.targetTable || undefined, insertedRows: f.insertedRows ?? 0,
          skippedRows: f.skippedRows ?? 0, skippedReason: f.skippedReason || undefined,
          fileAtIso: f.atIso || undefined, errorMessage: job.status === 'failed' ? job.errorMessage : undefined,
        });
        if (out.length >= limit) break;
      }
    } catch { /* ignore */ }
  }
  return { total: out.length, rows: out, dias };
}

/* ---------- Health Geral ---------- */
export async function runAutomationHealthGeneral(): Promise<{
  serverAtIso: string;
  scheduler: SchedTickState & { enabled: boolean; nextRuns: Array<{ id: string; title: string; nextRunAtIso?: string; enabled: boolean; lastRunAtIso?: string }> };
  ttl: { lastCleanupAtIso?: string; jobsInMem: number; jobsPersistedApprox?: number };
  jobsLast7d: { succeeded: number; failed: number; cancelled: number; queuedRunning: number; totalRowsInserted: number; totalRowsSkipped: number };
  drive?: Awaited<ReturnType<typeof runAutomationDriveHealthCheck>>;
  config: AutomationConfigFull;
}> {
  const cfg = await getAutomationConfig();
  const schedules = (await listAutomationSchedules()).map((s) => ({ id: s.id, title: s.title, nextRunAtIso: s.nextRunAtIso, enabled: s.enabled, lastRunAtIso: s.lastRunAtIso }));
  const jobs = listImportJobsRecent({ limit: 500 }).jobs;
  const cutoff7 = Date.now() - 7 * 24 * 60 * 60 * 1000;
  const j7 = jobs.filter((j) => new Date(j.createdAtIso).getTime() >= cutoff7);
  let linhasIn = 0, linhasSkip = 0;
  for (const j of j7) { linhasIn += j.totalRowsInserted ?? 0; linhasSkip += j.totalRowsSkipped ?? 0; }
  let drive: Awaited<ReturnType<typeof runAutomationDriveHealthCheck>> | undefined;
  try { drive = await runAutomationDriveHealthCheck('all'); } catch { /* ignore */ }
  const jobsPersisted = await _f3CountKvKeysByPrefix('job_record::v1::');
  return {
    serverAtIso: new Date().toISOString(),
    scheduler: { ..._schedState, enabled: cfg.schedulerEnabled, nextRuns: schedules.slice(0, 20) },
    ttl: { jobsInMem: ImportJobsManager.inMem.size, jobsPersistedApprox: jobsPersisted || undefined },
    jobsLast7d: {
      succeeded: j7.filter((j) => j.status === 'succeeded').length,
      failed: j7.filter((j) => j.status === 'failed').length,
      cancelled: j7.filter((j) => j.status === 'cancelled').length,
      queuedRunning: j7.filter((j) => j.status === 'queued' || j.status === 'running').length,
      totalRowsInserted: linhasIn, totalRowsSkipped: linhasSkip,
    },
    drive,
    config: cfg,
  };
}

/* ---------- Bootstrap (1x no boot do processo) ---------- */
const __bootstrapFase3Done = { value: false };
export async function bootstrapAutomationSystem(): Promise<{ ok: boolean; cleanupTtl: { removed: number; ttlDias: number; checked: number }; }> {
  let cleanup = { removed: 0, ttlDias: 90, checked: 0 };
  try {
    if (__bootstrapFase3Done.value) { console.log('[FASE3][bootstrap] Já executado anteriormente, skip.'); return { ok: true, cleanupTtl: cleanup }; }
    __bootstrapFase3Done.value = true;
    console.log('[FASE3][bootstrap] INICIANDO bootstrapAutomationSystem()...');
    await _ensureDefaultSchedules();
    _attachBootstrapListenersOnce();
    try {
      const p = startDailyOccurrencesPanoramaScheduler();
      console.log('[PANORAMA][bootstrap] startDailyOccurrencesPanoramaScheduler: started=' + p.started + ' alreadyRunning=' + p.alreadyRunning + ' next=' + p.nextRunAtIso + ' intervalMs=' + p.intervalMs);
    } catch (e) {
      console.error('[PANORAMA][bootstrap] startDailyOccurrencesPanoramaScheduler ERRO:', e instanceof Error ? (e.stack || e.message) : String(e));
    }
    void cleanupOldJobsTtl().then((r) => { cleanup = r; console.log('[FASE3][bootstrap][TTL] cleanupOldJobsTtl concluído: removed=' + r.removed + ' checked=' + r.checked + ' ttlDias=' + r.ttlDias); }).catch((e) => { console.error('[FASE3][bootstrap][TTL] cleanupOldJobsTtl erro:', e instanceof Error ? (e.stack || e.message) : String(e)); });
    try { const sz = ImportJobsManager.inMem.size; console.log('[FASE3][bootstrap] ImportJobsManager.inMem size inicial=' + sz); } catch { /* placeholder p/ touch ImportJobsManager no boot */ }
    console.log('[FASE3][bootstrap] CONCLUÍDO com sucesso.');
    return { ok: true, cleanupTtl: cleanup };
  } catch (e) {
    console.error('[FASE3][bootstrap] ERRO GLOBAL no bootstrapAutomationSystem:', e instanceof Error ? (e.stack || e.message) : String(e));
    return { ok: false, cleanupTtl: cleanup };
  }
}

/* Chamada Lazy 1x após 7s do carregamento do módulo (assim não trava Nest boot) */
setTimeout(() => {
  console.log('[FASE3][bootstrap] setTimeout 7s disparado, chamando bootstrapAutomationSystem()...');
  void (async () => {
    try {
      const r = await bootstrapAutomationSystem();
      console.log('[FASE3][bootstrap] Resultado bootstrap: ok=' + r.ok + ' cleanupRemoved=' + r.cleanupTtl.removed);
    } catch (e) {
      console.error('[FASE3][bootstrap] ERRO CRÍTICO fora do try da função:', e instanceof Error ? (e.stack || e.message) : String(e));
    }
  })();
}, 7000);

/**
 * Endpoint de debug: roda ensureSchema + ensureDefaultLearningProfiles + persistDatabase FORÇADO
 *   no DB principal (sem snapshot). Garante que tabelas novas como Extratos/Relatorios
 *   existam no arquivo do disco antes de rodar qualquer job de importação.
 *   Necessário pois o sql.js trabalha em memória e os jobs dependem de snapshot/merge via fs.
 *   Também força PRAGMA wal_checkpoint(TRUNCATE) para visualizadores externos (DB Browser, Beekeeper, etc)
 *   lerem as últimas transações SEM depender dos arquivos -wal/-shm auxiliares.
 */
export async function debugEnsureExtratosRelatoriosTables(): Promise<{
  ok: boolean;
  dbFilePath: string;
  tablesAfter: Array<{ name: string; columnsCount: number; rowCount?: number | null }>;
  learningProfiles: Array<{ id: string; kind: string; targetTable: string }>;
  allTablesContainingExtratoOrRelatorio: Array<{ name: string; rowCount: number | null; kind: string }>;
  walCheckpointResult: unknown;
  lastExtratosRows: Array<Record<string, unknown>>;
  extratosColumns: Array<string>;
  adfegoEletraFound: Array<Record<string, unknown>>;
  extratosRowIdInfo: Record<string, unknown>;
}> {
  const dbFilePath = getSqlitePath();
  const db = await openDatabase(dbFilePath);
  // Garantias: schema + learning profiles + learning profile idempotente
  try { ensureSchema(db); } catch (e) { safeLogError('debug ensureSchema', e); }
  try { ensureDefaultLearningProfiles(db); } catch (e) { safeLogError('debug ensureLearningProfiles', e); }
  // 1) Forçar persistência no DISCO (sql.js → writeFileSync buffer da memória para o arquivo)
  persistDatabase(db, dbFilePath);
  // 2) WAL / Checkpoint — DESATIVADO INTENCIONALMENTE em 2026-08-19.
  //    Ver correção no openDatabase: SQL.js (WebAssembly) em memória NÃO implementa journal_mode
  //    WAL do disco nativo. Se rodamos wal_checkpoint sem ter o sqlite nativo rodando, ou o DB
  //    Browser está com lock nos arquivos -wal/-shm, dá erro falso ou força criação de WAL.
  //    Solução: só usamos journal_mode=DELETE (padrão SQLite) — o persistDatabase() sempre
  //    reescreve o arquivo INTEIRO em disco, então o -wal não tem sentido aqui.
  let walCheckpointResult: unknown = {
    skipped: true,
    reason: 'sql.js não implementa WAL de disco; persistDatabase() reescreve o arquivo inteiro.',
  };
  // Forçar persistência de novo (redundância defensiva — garantias que writeFileSync rodou 2x)
  try { persistDatabase(db, dbFilePath); } catch (e) { safeLogError('debug post-checkpoint persist', e); }

  const listTables = db.prepare(
    "SELECT name FROM sqlite_master WHERE type='table' AND (UPPER(name) LIKE '%EXTRATO%' OR UPPER(name) LIKE '%RELATORIO%' OR UPPER(name) LIKE 'EXTRATOS' OR UPPER(name) LIKE 'RELATORIOS') ORDER BY name COLLATE NOCASE;"
  );
  const tblRows: Array<{ name: string }> = (() => {
    try {
      const out: Array<{ name: string }> = [];
      while (listTables.step()) {
        const r = listTables.getAsObject() as { name?: string };
        if (r && typeof r.name === 'string') out.push({ name: r.name });
      }
      return out;
    } finally { try { (listTables as { free?: () => void }).free?.(); } catch { /* ignore */ } }
  })();
  const tablesAfter = tblRows.map((r) => {
    const cols = getTableColumns(db, r.name);
    let rowCount: number | null = null;
    try {
      const cnt = db.prepare(`SELECT COUNT(*) AS c FROM ${escapeSqlIdentifier(r.name)};`);
      try {
        if (cnt.step()) {
          const o = cnt.getAsObject() as { c?: number };
          rowCount = typeof o.c === 'number' ? o.c : null;
        }
      } finally { try { (cnt as { free?: () => void }).free?.(); } catch { /* ignore */ } }
    } catch { /* ignore */ }
    return { name: r.name, columnsCount: cols.length, rowCount };
  });
  const listAllStmt = db.prepare(
    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name COLLATE NOCASE;"
  );
  const allRows: Array<{ name: string }> = (() => {
    const out: Array<{ name: string }> = [];
    try {
      while (listAllStmt.step()) {
        const r = listAllStmt.getAsObject() as { name?: string };
        if (r && typeof r.name === 'string') out.push({ name: r.name });
      }
    } finally { try { (listAllStmt as { free?: () => void }).free?.(); } catch { /* ignore */ } }
    return out;
  })();
  const allTablesContainingExtratoOrRelatorio = allRows
    .filter((r) => /xtrat|relatori/i.test(r.name))
    .map((r) => {
      let rowCount: number | null = null;
      try {
        const cnt = db.prepare(`SELECT COUNT(*) AS c FROM ${escapeSqlIdentifier(r.name)};`);
        try {
          if (cnt.step()) {
            const o = cnt.getAsObject() as { c?: number };
            rowCount = typeof o.c === 'number' ? o.c : null;
          }
        } finally { try { (cnt as { free?: () => void }).free?.(); } catch { /* ignore */ } }
      } catch { /* ignore */ }
      const up = r.name.toUpperCase();
      const kind = (up.includes('EXTRATO') ? 'extrato_like' : '') + (up.includes('RELATORI') ? 'relatorio_like' : '') || 'outro';
      return { name: r.name, rowCount, kind };
    });
  const lpStmt = db.prepare(
    "SELECT id, kind, target_table FROM import_learning_profiles WHERE kind IN ('extratos','relatorio') ORDER BY kind, id;"
  );
  const learningProfiles: Array<{ id: string; kind: string; targetTable: string }> = (() => {
    const out: Array<{ id: string; kind: string; targetTable: string }> = [];
    try {
      while (lpStmt.step()) {
        const r = lpStmt.getAsObject() as { id?: unknown; kind?: unknown; target_table?: unknown };
        out.push({
          id: String(r.id ?? ''),
          kind: String(r.kind ?? ''),
          targetTable: String(r.target_table ?? ''),
        });
      }
    } finally { try { (lpStmt as { free?: () => void }).free?.(); } catch { /* ignore */ } }
    return out;
  })();
  // 3) Mostrar PROVAS CONCRETAS das últimas linhas da tabela extratos
  //    → usuário confirma visualmente que RECURSO - ADFEGO E ELETTRA foi importado (2 linhas novas de DATA/DOCUMENTO/HISTÓRICO/VALOR)
  const extratosColumns = (() => {
    try { return getTableColumns(db, 'extratos'); } catch { return []; }
  })();
  const lastExtratosRows: Array<Record<string, unknown>> = (() => {
    const out: Array<Record<string, unknown>> = [];
    if (extratosColumns.length === 0) return out;
    try {
      const hasSourceFile = extratosColumns.includes('__source_file');
      const hasCopetencia = extratosColumns.some((c) => /copetenc|competenc/i.test(c));
      const hasDataReal = extratosColumns.includes('DATA');
      let orderBy = '1 DESC';
      if (hasDataReal) orderBy = 'CAST(DATA AS TEXT) DESC';
      else if (hasCopetencia) orderBy = 'CAST(Copetencia AS TEXT) DESC';
      else if (hasSourceFile) orderBy = '__source_file DESC';
      const colsQ = extratosColumns.map(escapeSqlIdentifier).join(', ');
      // NOTA: sql.js/WASM NÃO suporta a coluna virtual `_rowid` (existe apenas no sqlite nativo / better-sqlite3).
      // Removido o SELECT _rowid; usamos apenas a ordenação por DATA/Copetencia.
      const s = db.prepare(`SELECT ${colsQ} FROM extratos ORDER BY ${orderBy} LIMIT 20;`);
      try {
        while (s.step()) {
          const raw = s.getAsObject() as Record<string, unknown>;
          const clean: Record<string, unknown> = {};
          for (const col of extratosColumns) {
            if (Object.prototype.hasOwnProperty.call(raw, col)) clean[col] = raw[col];
          }
          out.push(clean);
        }
      } finally { try { (s as { free?: () => void }).free?.(); } catch { /* ignore */ } }
    } catch (e) { safeLogError('debug extratos last rows', e); out.push({ error: e instanceof Error ? e.message : String(e ?? '') }); }
    return out;
  })();
  // 4) Buscar linhas do RECURSO ADFEGO/ELETTRA por DOCUMENTO / HISTÓRICO (pois __source_file pode estar vazio)
  //    Palavras que estão no layout do Excel (MP GO / Defensoria GO etc — o arquivo original do ADFEGO)
  const adfegoEletraKeywords = ['ADFEGO','ELETTRA','MP PROCURADORIA','DEFENSORIA PUBLICA DO ESTADO DE GO','JUSTICA ESTADO DE GOIAS','GOIAS PREVIDENCIA','CORPO DE BOMBEIROS MILITAR','SECRETARIA DE ESTADO DA SEGURANCA','POLICIA CIVIL','JUNTA COMERCIAL DO ESTADO DE GOIAS'];
  const adfegoEletraFound: Array<Record<string, unknown>> = (() => {
    const out: Array<Record<string, unknown>> = [];
    if (extratosColumns.length === 0) return out;
    try {
      const colsQ = extratosColumns.map(escapeSqlIdentifier).join(', ');
      const where: string[] = [];
      const binds: unknown[] = [];
      const tryCols = extratosColumns.filter((c) => /DOCUMENTO|HIST|COMPLEMENTARES|INFO/i.test(c));
      for (const col of tryCols) {
        for (const kw of adfegoEletraKeywords) {
          where.push(`${escapeSqlIdentifier(col)} LIKE ?`);
          binds.push(`%${kw}%`);
        }
      }
      if (where.length === 0) return out;
      let orderBy = '1 DESC';
      if (extratosColumns.includes('DATA')) orderBy = 'CAST(DATA AS TEXT) DESC';
      const sql = `SELECT ${colsQ} FROM extratos WHERE (${where.join(' OR ')}) ORDER BY ${orderBy} LIMIT 30;`;
      const s = db.prepare(sql);
      try {
        s.bind(binds as any);
        while (s.step()) {
          const raw = s.getAsObject() as Record<string, unknown>;
          const clean: Record<string, unknown> = {};
          for (const col of extratosColumns) {
            if (Object.prototype.hasOwnProperty.call(raw, col)) clean[col] = raw[col];
          }
          out.push(clean);
        }
      } finally { try { (s as { free?: () => void }).free?.(); } catch { /* ignore */ } }
    } catch (e) { safeLogError('debug adfego_eletra search', e); out.push({ error: e instanceof Error ? e.message : String(e ?? '') }); }
    return out;
  })();
  // 5) COUNT + COLS (confirma contagem global - sql.js não suporta _rowid virtual)
  const extratosRowIdInfo: Record<string, unknown> = (() => {
    try {
      const s = db.prepare('SELECT COUNT(*) AS c FROM extratos;');
      try {
        if (s.step()) {
          const r = s.getAsObject() as Record<string, unknown>;
          const maxData = (() => {
            try {
              if (!extratosColumns.includes('DATA')) return null;
              const sd = db.prepare('SELECT CAST(DATA AS TEXT) AS d FROM extratos ORDER BY CAST(DATA AS TEXT) DESC LIMIT 1;');
              try { if (sd.step()) { return (sd.getAsObject() as any).d ?? null; } } finally { try { (sd as any).free?.(); } catch {} }
              return null;
            } catch { return null; }
          })();
          const minData = (() => {
            try {
              if (!extratosColumns.includes('DATA')) return null;
              const sd = db.prepare('SELECT CAST(DATA AS TEXT) AS d FROM extratos ORDER BY CAST(DATA AS TEXT) ASC LIMIT 1;');
              try { if (sd.step()) { return (sd.getAsObject() as any).d ?? null; } } finally { try { (sd as any).free?.(); } catch {} }
              return null;
            } catch { return null; }
          })();
          return { count: r.c, columnsCount: extratosColumns.length, columns: extratosColumns, minData, maxData };
        }
      } finally { try { (s as { free?: () => void }).free?.(); } catch { /* ignore */ } }
      return {};
    } catch (e) { return { error: e instanceof Error ? e.message : String(e ?? '') }; }
  })();
  return { ok: true, dbFilePath, tablesAfter, learningProfiles, allTablesContainingExtratoOrRelatorio, walCheckpointResult, lastExtratosRows, extratosColumns, adfegoEletraFound, extratosRowIdInfo };
}

